COLLDATA("asabahur","ur",[[9368,"§۱۰۷۵۸ ۔ آمنہ بنت سعد\n(1) بن وہب، ابوسفیان کی زوجہ ہیں، ابو عمر(2) نے ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۶۸۶) تجرید اسماء الصحابہ (۲۴۲/۲)\n(2) الاستیعاب (۱۷۹۰/۴)"}],[9369,"§۱۰۷۵۹ ۔ آمنہ بنت ابی سفیان\nبن حرب بن امیہ، ابن اسحاق نے غزوہ طائف میں ان کا ذکر کیا ہے۔ اور وہ امیمہ تصغیر کے ساتھ ہے، ان کا ذکر آ رہا ہے۔"],[9370,"§۱۰۷۶۰ ۔ آمنہ بنت ابی الصلت الغفاریہ\nیا بنت الصلت۔ دوسری قسم میں ان کے حالات آئیں گے۔"],[9371,"§۱۰۷۶۱ ۔ آمنہ بنت عفان\n(1) بن ابی العاص بن امیہ بن عبد الشمس الامویہ۔ امیر المومنین سیدنا عثمان رضی اللہ عنہ کی بہن ہیں۔ ابو موسیٰ نے بیان کیا ہے کہ فتح مکہ کے دن اسلام لائیں، اور سعد جو بنی مخزوم کے حلیف تھے، کی بیوی تھیں۔ اور ان خواتین میں سے تھیں جنہوں نے ہند زوجہ ابوسفیان کے ساتھ اس بات پر بیعت کی تھی کہ وہ اللہ کے ساتھ نہ کسی کو شریک ٹھہرائیں گی اور نہ چوری کریں گی اور نہ زنا کریں گی، ابن اسحاق نے یہ مغازی میں ذکر کیا ہے۔ اور ابن کلبی نے ذکر کیا ہے کہ وہ جاہلیت میں ماما تھیں اور انہوں نے حکم بن کیسان جو بنی مخزوم کے آزاد کردہ غلام تھے، سے نکاح کیا، اس بارے میں حکم ابن کیسان کے حالات میں جو سند پہلے گزر چکی ہے وہ ابو موسیٰ کے قول سے زیادہ قوی ہے کہ وہ سعد کے پاس تھیں۔","",{"fn":"(1) اسد الغابہ (ت: ۶۶۸۸) تجرید اسماء الصحابہ (۲۴۳/۲)"}],[9372,"§۱۰۷۶۲ ۔ آمنہ بنت عمرو\nبن حرب بن امیہ الامویہ، سیدنا معاویہ رضی اللہ عنہ کی چچا زاد بہن تھیں۔ ان سے ابوحذیفہ بن عقبہ نے نکاح کیا جس سے عاصم پیدا ہوئے، ابن سعد نے ان (عاصم) کا ذکر کیا ہے۔"],[9373,"§۱۰۷۶۳ ۔ آمنہ بنت غفار\n(1) ذہبی(2) نے مہمات النووی میں لکھا ہے کہ یہ ابن عمر رضی اللہ عنہ کی وہ زوجہ تھیں جنہیں انہوں نے طلاق دی تھی اور سیدنا عمر رضی اللہ عنہ نے ان سے رجوع کرنے کا حکم دیا تھا۔ میں کہتا ہوں: ابن لہیعہ نے عبدالرحمن الاعرج کے حوالے سے ان کا نام آمنہ بنت عفان بتایا ہے۔ اور کہا ہے کہ وہ خاتون جنہیں ابن عمر رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم کے زمانے میں طلاق دی تھی، آمنہ بنت عفان تھیں، اس کا ذکر ابن سعد نے حسن بن موسیٰ سے اور انہوں نے ابن لہیعہ کے حوالے سے کیا ہے۔ اور ہم نے اسے قتیبہ کی جمع کردہ احادیث میں سے روایت کیا ہے۔ یہ روایت سعید العیار کی سند سے ہے جو انہوں نے قتیبہ سے اور انہوں نے ابن لہیعہ سے نقل کی ہے۔ اور قتیبہ کی روایت میں بنت غفار (غین کا زیر اور فاء کی تخفیف اور راء کے ساتھ ہے) اور طبقات کے نسخے میں غین کا زبر اور فاء کی تشدید اور الف نون کے ساتھ ہے۔","",{"fn":"(1) تجرید اسماء الصحابہ (۲۴۳/۲)\n(2) التجرید (۱۸۰)"}],[9374,"§۱۰۷۶۴ ۔ آمنہ بنت قرط\n(1) بن خنساء بن سنان الانصاریہ۔ ان کا نسب ان کی بہن امامہ کے حالات میں آئے گا۔ ابن سعد(2) نے کہا کہ ان دونوں کی والدہ ماریہ بنت القین بن کعب بن سواد ہیں، ان آمنہ نے اوس بن المعلی بن لوذان سے نکاح کیا، جن سے ابوسعید پیدا ہوئے، بعد میں آمنہ ایمان لائیں اور بیعت کی۔","",{"fn":"(1) تجرید اسماء الصحابہ (۲۴۳/۲)\n(2) الطبقات الکبریٰ (۲۹۴/۸)"}],[9375,"§۱۰۷۶۵ ۔ آمنہ بنت محصن\nسہیلی نے ذکر کیا ہے کہ یہ ام قیس بنت محصن کا نام ہے جو عکاشہ بن محصن الاسدی کی بہن ہیں۔"],[9376,"§۱۰۷۶۶ ۔ آمنہ بنت نعیم النعام\nان کا ذکر ان کی والدہ کے حالات میں آئے گا۔"],[9377,"§۱۰۷۶۷ ۔ آمنہ یا عاتکہ\nولید بن مغیرہ کی والدہ ہیں۔ ان کے حالات میں کوئی ایسی بات ہے جو ان کے اسلام لانے پر دلالت کرتی ہے۔"],[9378,"§۱۰۷۶۸ ۔ أبرہہ الحبشیہ\n(1) نجاشی کے خدام میں سے تھیں۔ واقدی رحمہ اللہ نے ذکر کیا ہے کہ جب نجاشی نے سیدہ ام حبیبہ رضی اللہ عنہا کا نکاح نبی کریم صلی اللہ علیہ وسلم سے کیا تو وہ ان کے پاس تھیں۔ ابن سعد نے ان کا قصہ ام حبیبہ رضی اللہ عنہا کے حالات میں ذکر کیا ہے۔ بحوالہ عبداللہ بن عمرو بن زہیر، اور انہوں نے اسماعیل بن عمرو بن سعید اور انہوں نے ام حبیبہ رضی اللہ عنہا سے روایت کیا ہے۔","",{"fn":"(1) الاستیعاب (ت: ۳۲۶۸) تجرید اسماء الصحابہ (۲۴۳/۲)"}],[9379,"§۱۰۷۶۹ ۔ أثیلہ بنت الحارث\n(1) بن ثعلبہ بن حرام بن مسفر بن امیہ بن حرام بن ثابت بن النجار الانصاری، انہیں شرف صحابیت حاصل ہے۔ ابن سعد(2) نے ذکر کیا ہے کہ وہ بیعت کرنے والی صحابیات رضی اللہ عنہن میں سے تھیں، اور فرمایا کہ ان کی والدہ فاطمہ بنت زید مناۃ بن عمرو بن مازن الغسانیہ ہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۶۶۹۰) تجرید اسماء الصحابہ (۲۴۳/۲)\n(2) الطبقات الکبریٰ (۳۰۵/۸)"}],[9380,"§۱۰۷۷۰ ۔ أثیلہ بنت راشد الہذلیہ\n(1) ان کا ذکر عامر بن مرزقش کے حالات میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۶۹۱) تجرید اسماء الصحابہ (۲۴۳/۲)"}],[9381,"§۱۰۷۷۱ ۔ أثیلہ الخزاعیہ\n(1) ایوب بن عبد اللہ بن زہیر الاسدی کی دادی ہیں۔ فاکہی نے کتاب مکہ میں ابن جریج کے حوالہ سے اور انہوں نے ابن ابی حسین سے حدیث نقل کی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے سہیل بن عمرو کو خط لکھا کہ اگر میرا یہ خط تمہارے پاس رات کو پہنچے تو صبح ہونے سے پہلے اور اگر دن کے وقت پہنچے تو شام ہونے سے پہلے میرے پاس آب زم زم روانہ کر دینا۔ راوی کا بیان ہے کہ سہیل رضی اللہ عنہ نے اثیلہ الخزاعی کی مدد حاصل کی یہاں تک کہ دونوں نے دو توشہ دان بنا دیے اور بنا کے ارغ ہو گئے۔ پھر سہیل نے ان دونوں کو آب زم زم سے بھر دیا اور اونٹ پر لاد کر روانہ کر دیا۔ عمر بن شبہ نے اسی طرح نقل کیا ہے۔","",{"fn":"(1) جلد اول ترجمہ ۳۸ میں یہی قصہ اور یہی شخصیت مردوں میں مذکور ہے اور یہاں ان کا تذکرہ عورتوں میں ہو رہا ہے۔"}],[9382,"§۱۰۷۷۲ ۔ أثیمہ المخزومیہ\n(1) خطاف کی دادی ہیں۔ ابن عبدالبر نے ان کا ذکر کیا ہے، اور کہا گیا ہے کہ یہ وہی اروی ہیں جن کا ذکر آ رہا ہے۔","",{"fn":"(1) الاستیعاب (ت: ۳۲۶۸) تجرید اسماء الصحابہ (۲۴۳/۲)"}],[9383,"§۱۰۷۷۳ ۔ إرام بنت الجموح الأنصاریہ\nعمرو بن الجموح رضی اللہ عنہ کی بہن ہیں جو خزرج کے سردار ہیں، ابن سعد(1) نے ان کا ذکر کیا ہے۔","",{"fn":"(1) الطبقات الکبریٰ (۲۸۹/۸)"}],[9384,"§۱۰۷۷۴ ۔ إرام بنت قرط\n(1) بن خنساء الانصاریہ، بیعت کرنے والی خواتین میں سے ہیں۔ ابن سعد(2) نے ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید اسماء الصحابہ (۲۴۳/۲)\n(2) الطبقات الکبریٰ (۲۹۴/۸)"}],[9385,"§۱۰۷۷۵ ۔ أردہ بنت الحارث\nبن کلدہ ثقفی، عتبہ بن غزوان کی زوجہ ہیں۔ بلاذری وغیرہ نے ان کا ذکر کیا ہے اور وہ کہتے ہیں کہ وہ عقبہ کے ساتھ بصرہ میں تھیں وہ اس کے گورنر تھے۔ ان کی وجہ سے ابوبکرہ اور ان کے ماں شریک بھائی نافع اور زیاد آئے۔"],[9386,"§۱۰۷۷۶ ۔ أرنب بنت عفیف\nبن ابی العاص بن عبد الشمس، ان کی والدہ نابغہ ہیں، جو عمرو بن العاص کی والدہ ہیں، یوں عمرو ان کے ماں شریک بھائی ہیں۔ زبیر بن بکار نے ان کا ذکر کیا ہے۔ پھر طبری نے ان کا ذکر کیا ہے۔"],[9387,"§۱۰۷۷۷ ۔ أرنب المدنیۃ المغنیۃ\nہم نے اسے محاملی کے امالی میں سے جز ثالث میں ابن جریج کے سلسلہ سے اصبہانیین کی روایت سے نقل کیا ہے۔ وہ فرماتے ہیں کہ مجھے ابوالاصبح نے خبر دی کہ انہیں جمیلہ مغنیہ نے بتایا کہ انہوں نے جابر بن عبد اللہ رضی اللہ عنہ سے غنا کے بارے میں سوال کیا، انہوں نے فرمایا کہ انصار کے کسی گھرانے نے سیدہ عائشہ رضی اللہ عنہا کے کسی گھرانے سے نکاح کیا تو انہوں نے ان کی طرف قباء میں ہدیہ بھیجا، ان سے نبی کریم صلی اللہ علیہ وسلم نے فرمایا: کیا تم نے دلہن کی طرف ہدیہ بھیجا ہے۔ انہوں نے فرمایا: جی ہاں۔ آپ صلی اللہ علیہ وسلم نے پوچھا: کیا تم نے اس کے ساتھ سر لگانے والی کو بھیجا ہے؟ انصار سر لگانے کو پسند کرتے ہیں۔ آپ رضی اللہ عنہ نے فرمایا: نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: اس کے پاس ارنب کو تلاش کر کے بھیجو۔ یہ خاتون شادی بیاہ پر گیت گایا کرتی تھیں۔"],[9388,"§۱۰۷۷۸ ۔ أروی بنت أنیس\n(1) ابن مندہ نے ان کا ذکر کیا ہے۔ جامع ترمذی میں وضو کے باب میں ان کا ذکر ہے۔ اسی طرح التجرید(2) میں بھی ہے۔ ابن مندہ نے صرف ان کا ذکر کیا ہے، ان کے والد کا نام نہیں لکھا۔ امام ترمذی رحمہ اللہ فرماتے ہیں کہ حدیث برہ جس میں مس ذکر کے بعد وضو کا ذکر ہے کے بعد ان کا ذکر ہے۔ انہوں نے راویوں کی ایک جماعت کا ذکر کیا ہے جس میں اروی بھی ہیں، ابن سکن اور دار قطنی نے علل میں نقل کیا ہے۔ بسلسلہ عثمان بن الیمان کہ وہ فرماتے ہیں کہ میں نے ہشام بن زیاد سے سنا ان کی کنیت ابوالمقدام ہے انہوں نے ہشام بن عروہ سے انہوں نے اپنے والد اسی طرح انہوں نے آروی بنت انیس سے نقل کیا ہے۔ اور وضو کے باب میں مس ذکر کے بارے میں مرفوع حدیث ذکر کی ہے۔ ابن سکن نے فرمایا کہ یہ ثابت نہیں، اور اس بارے میں ہشام بن عروہ کے علاوہ کسی نے حدیث نقل نہیں کی، اسی طرح ابی المقدام سے بھی روایت ہے۔ وہ بصری راوی ہیں جو ضعیف ہیں۔ ابن مندہ نے کہا ہے کہ ابو المقدام سے اس سند کے ساتھ روایت کی گئی لیکن کہا کہ اس میں ”عن ابي اروى“ کے الفاظ ہیں اور یہی صحیح ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۶۹۶) تجرید اسماء الصحابہ (۲۴۳/۲)\n(2) التجرید (۱۸۰)"}],[9389,"§۱۰۷۷۹ ۔ أروی بنت الحارث\nبن عبدالمطلب الہاشمیہ۔ وہ مطلب بن ابی وداعہ السہمی کی والدہ ہیں۔ ابن سعد نے صحابیان میں نبی کریم صلی اللہ علیہ وسلم کی چچازاد بہنوں کے باب میں ان کا ذکر کیا ہے۔ اور فرمایا ہے کہ ان کی والدہ غزیہ بنت قیس بن طریف ہیں جو بنو حارث بن فہر بن مالک سے ہیں۔ اور کہا کہ ابو وداعہ سے ان کی اولاد یہ ہے: مطلب، ابوسفیان، ام جمیل، ام حکیم، ربعہ۔"],[9390,"§۱۰۷۸۰ ۔ أروی بنت ربیعہ\n(1) بن حارث بن عبدالمطلب الہاشمی، دار قطنی نے ان کا کتاب الاخوہ میں ذکر کیا ہے۔ اور لکھا ہے کہ ان سے حبان بن منقذ الانصاری نے نکاح کیا، جس سے اولاد بھی ہوئی، اور کہا گیا ہے کہ ان کا نام ہند ہے۔ یہاں تک عبارت ختم ہوئی۔ ابن مندہ نے کہا کہ اروی ان کی حدیث عطاف بن خالد سے روایت کی گئی ہے۔ انہوں نے اپنی والدہ سے اور انہوں نے اپنی والدہ جو کہ اروی ہیں سے نقل کیا ہے۔ عبدالقدوس بن ابراہیم نے عطاف سے انہوں نے اپنی والدہ سے اور انہوں نے اپنی والدہ اہیمہ سے جو عطاف کی نانی ہیں(2) روایت کیا ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور وہ بچی تھیں۔","",{"fn":"(1) اسد الغابہ (ت: ۶۶۹۲) تجرید اسماء الصحابہ (۲۴۳/۲)\n(2) الاستیعاب (۱۷۷۸/۴)"}],[9391,"§۱۰۷۸۱ ۔ أروی بنت ابی العاص\n(1) بن امیہ بن عبد الشمس الامویہ، حکم کی بہن ہیں جو مروان کے والد ہیں، وہ عثمان بن عفان کی پھوپھی ہیں۔ مستغفری نے ان کا ذکر کیا ہے، اور سلمہ بن فضل کے سلسلے سے کہ انہوں نے محمد بن اسحاق سے روایت کی اپنی سند کو چلایا ہے کہ انہوں نے ان کا ان صحابیات میں ذکر کیا ہے جنہوں نے فتح کے دن رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی۔","",{"fn":"(1) اسد الغابہ (ت: ۶۶۹۳) تجرید اسماء الصحابہ (۲۴۳/۲)"}],[9392,"§۱۰۷۸۲ ۔ أروی بنت عبدالمطلب\n(1) بن ہاشم الہاشمی، رسول اللہ صلی اللہ علیہ وسلم کی پھوپھی ہیں۔ ابو عمر نے لکھا ہے کہ عمیر بن وہب بن عبد بن قصی کی زوجہ تھی۔ جن سے طلیب پیدا ہوئے، اس کے بعد کلدہ بن عبد مناف بن عبدالدار بن قصی کی زوجیت میں آئیں جن سے اروی پیدا ہوئیں۔ ابو عمر(2) نے بیان کیا ہے کہ انہوں نے محمد بن اسحاق سے سنا، نبی کریم صلی اللہ علیہ وسلم کی پھوپھیوں میں سے صرف سیدہ صفیہ رضی اللہ عنہا ایمان لائیں ان کا قصہ سیدہ اروی رضی اللہ عنہا کے بعد آ رہا ہے۔ عقیلی نے صحابہ رضی اللہ عنہم میں واقدی کی سند سے ان کا ذکر کیا ہے کہ انہوں نے موسیٰ بن محمد بن ابراہیم بن الحارث التیمی سے اور انہوں نے اپنے والد سے نقل کیا ہے کہ جب طلیب بن عمیر ایمان لائے تو اپنی والدہ اروی بنت عبدالمطلب کے پاس آئے اور کہا میں اسلام لایا ہوں اور محمد صلی اللہ علیہ وسلم سے بیعت کر چکا ہوں۔ پھر قصہ ذکر کیا، اس میں ہے: آپ کو اسلام لانے سے کس چیز نے روکا ہے؟ آپ کے بھائی سیدنا حمزہ رضی اللہ عنہ ایمان لا چکے ہیں۔ انہوں نے کہا: میں بھوں گی میرے دونوں بھائی ایمان لانے کے بعد کیا کرتے ہیں۔ فرماتے ہیں کہ میں نے کہا: میں آپ کو اللہ کا واسطہ دیتا ہوں کہ آپ صلی اللہ علیہ وسلم کے پاس جائیں انہیں سلام کریں اور ان کی تصدیق کریں۔ انہوں نے کہا: میں گواہی دیتی ہوں کہ اللہ کے سوا کوئی معبود نہیں اور محمد صلی اللہ علیہ وسلم اللہ کے رسول ہیں۔ اس کے بعد وہ نبی کریم صلی اللہ علیہ وسلم کی زبانی مدد کرتی تھیں اور اپنے بیٹے کو آپ صلی اللہ علیہ وسلم کی مدد کرنے اور ان کے لائے ہوئے دین کو قائم کرنے پر ابھارتی تھیں۔ ابن سعد(3) نے لکھا ہے کہ وہ ایمان لائیں اور مدینہ کی طرف ہجرت کی۔ انہوں نے واقدی رحمہ اللہ کی سند سے بُرہ بنت ابی تجراۃ کے حوالے سے لکھا ہے وہ فرماتی ہیں: ابو جہل اور اس کے ساتھی نبی کریم صلی اللہ علیہ وسلم کے سامنے آئے اور آپ صلی اللہ علیہ وسلم کو ایذاء دی۔ سیدنا طلیب بن عمیر رضی اللہ عنہ نے ابو جہل کو مارا اور اسے زخمی کر دیا۔ انہیں ابو جہل کے ساتھیوں نے پکڑ لیا، چنانچہ ابولہب انہیں چھڑانے لگے۔ جب سیدہ اروی رضی اللہ عنہا کو یہ معلوم ہوا تو انہوں نے فرمایا: تمام دنوں میں سے اس کا اچھا دن وہ ہے جب اس نے اپنے ماموں زاد کی مدد کی، ابولہب سے کہا گیا کہ اروی بے دین ہو گئی ہے۔ وہ ان کے پاس آئے اور ڈانٹنے لگے۔ انہوں نے کہا: اپنے بھتیجے کے لیے آڑ بن جاؤ، اگر وہ تم پر غالب آ گیا تو تم نیک لوگوں میں سے ہو گے، اور اگر ایسا نہ ہوا تو تم اپنے بھتیجے کے بارے میں عذر پیش کر چکے ہو گے۔ ابولہب نے کہا: ہمارے پاس سارے عرب کی طاقت ہے، وہ نیا دین لے کر آیا ہے۔ ابن سعد(4) نے کہا، کہا جاتا ہے کہ اروی نے یہ اشعار کہے:\nان طليباً نصر ابن خالہ و اساہ في ذي دمہ و مالہ\n”طلیب نے اپنے ماموں زاد کی مدد کی، خون اور مال والے کے بارے میں تسلی دی۔“\nابن سعد نے یہ بھی ذکر کیا ہے کہ اروی نے مندرجہ ذیل اشعار میں نبی صلی اللہ علیہ وسلم کا مرثیہ کہا ہے:\nالا يا رسول اللہ کنت رجاءنا و کنت بنا برا و لم تک جافيا\nکان علي قلبي لذکر محمد و ما جمعت بعد النبي المجاويا\n”اللہ کے رسول صلی اللہ علیہ وسلم! آپ ہماری امید گاہ تھے، اور آپ نے ہم سے ہمیشہ اچھا سلوک کیا ہے، کبھی بدسلوکی نہیں کی۔ گویا میرے دل پر محمد صلی اللہ علیہ وسلم کے ذکر اور آپ صلی اللہ علیہ وسلم کے بعد جمع ہونے والے حالات نے غموں کے ڈیرے ڈال لیے ہیں۔“","",{"fn":"(1) اسد الغابہ (ت: ۶۶۹۴) الاستیعاب (ت: ۳۲۶۹) تجرید اسماء الصحابہ (۲۴۳/۲)\n(2) الاستیعاب (۱۷۷۹/۴)\n(3) الطبقات الکبریٰ (۲۸/۸)\n(4) الطبقات الکبریٰ (۲۹/۸)"}],[9393,"§۱۰۷۸۳ ۔ أروی بنت عمیس\nابن اثیر نے اروی بنت کریز کے حالات کے آخر میں ان کا ذکر کیا ہے۔"],[9394,"§۱۰۷۸۴ ۔ أروی بنت کریز\n(1) بن ربیعہ بن حبیب بن عبد شمس العبشمیہ، سیدنا عثمان بن عفان رضی اللہ عنہ کی والدہ ہیں۔ ان کی والدہ کا نام بیضاء بنت عبدالمطلب ہے جو نبی کریم صلی اللہ علیہ وسلم کی پھوپھی تھیں، ابن ابی عاصم نے وحدان میں ان کا ذکر کیا ہے۔ انہوں نے اور حاکم نے جس سند سے ذکر کیا ہے اس میں ضعف ہے جو زہری، عبید اللہ بن عبد اللہ بن عتبہ، ابن عباس رضی اللہ عنہ سے مروی ہے۔ فرمایا: ام عثمان، ام طلحہ، ام عمار، ام ابی بکر، ام زبیر اور ام عبدالرحمن بن عوف ایمان لائیں اور ابن مندہ نے لکھا ہے کہ وہ عثمان بن عفان کی خلافت میں فوت ہوئیں، ان کی کوئی حدیث معروف نہیں۔ ابن سعد(2) نے کہا: ان سے عفان بن ابی العاص نے نکاح کیا ان سے عثمان اور آمنہ پیدا ہوئے پھر ان سے عقبہ بن ابی معیط نے نکاح کیا۔ ان سے ولید، عمار، خالد، ام کلثوم، ام حکیم اور ہند پیدا ہوئے۔ سیدہ اروی رضی اللہ عنہا نے ام کلثوم کے بعد اسلام قبول کیا اور ہجرت کی، اور نبی کریم صلی اللہ علیہ وسلم سے بیعت کے بعد مدینے میں ہی رہیں، یہاں تک کہ ان کی وفات ہوگئی۔ میں نے بخیری رحمہ اللہ کے قلم سے لکھا ہوا پڑھا کہ ام عثمان رضی اللہ عنہا نے وفات پائی، اس وقت ان کی عمر نوے برس تھی، سیدنا عثمان رضی اللہ عنہ نے ان کی چار پائی اٹھائی اور نماز جنازہ پڑھی۔ ابن سعد رضی اللہ عنہ نے واقدی رحمہ اللہ کی سند سے جس میں انہوں نے سیدنا عبداللہ بن حنظلہ بن الراہب سے نقل کیا ہے، روایت کیا ہے: جس دن ام عثمان فوت ہوئیں میں موجود تھا، ان کے بیٹے نے انہیں بقیع میں دفن کیا اور واپس لوٹ آئے، لوگ نماز پڑھ چکے تھے، انہوں نے تنہا نماز ادا کی، اور میں نے ان کے ساتھ نماز پڑھی، میں نے سنا وہ کہہ رہے تھے: اے اللہ! میری ماں پر رحم فرما، اے اللہ! میری ماں کی مغفرت فرما، یہ ان کی خلافت کا دور تھا اور عیسی بن طلحہ کی سند سے ہے کہ میں نے دیکھا کہ سیدنا عثمان رضی اللہ عنہ نے دار غطیش سے دو بانسوں کے درمیان اپنی والدہ کی چار پائی اٹھائی یہاں تک کہ اسے جنازگاہ میں رکھ دیا۔ راوی کہتے ہیں کہ میں نے انہیں دیکھا کہ وہ انہیں دفن کرنے کے بعد ان کی قبر پر کھڑے دعا کر رہے تھے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۶۹۵) تجرید اسماء الصحابہ (۲۴۴/۲)\n(2) الطبقات الکبریٰ (۱۶۶/۸)"}],[9395,"§۱۰۷۸۵ ۔ أروی بنت المقوم\n(1) بن عبدالمطلب الہاشمیہ، رسول اللہ صلی اللہ علیہ وسلم کی چچا زاد تھیں، ان کے شوہر ابوسفیان بن حارث ہیں جو ان کے چچا زاد تھے۔ زبیر رحمہ اللہ نے ان کا ذکر کیا ہے اور کہا ہے کہ ابوسفیان سے ان کی بیٹیاں ہوئیں۔ اور ابن سعد رحمہ اللہ(2) نے لکھا ہے: ان سے ابو مسروح حارث بن یعمر بن حبان بن عمیر نے نکاح کیا جو بنو سعد بن بکر بن ہوازن سے تھے۔ وہ عباس بن عبدالمطلب کے حلیف تھے۔ ان سے عبداللہ بن ابی مسروح پیدا ہوئے۔","",{"fn":"(1) تجرید اسماء الصحابہ (۲۴۴/۲)\n(2) الطبقات الکبریٰ (۳۳/۸)"}],[9396,"§۱۰۷۸۶ ۔ أزدہ بنت الحارث\nبن کلدہ ثقفیہ، عتبہ بن غزوان کی زوجہ ہیں جو بصرہ کے امیر تھے۔ جب وہ بصرہ اور اس کے شہر آئے تو وہ ان کے ساتھ تھیں۔ ان کے سبب ان کے ماں شریک بھائی ابو بکرہ، نافع، زیاد بن عبید جنہیں اس کے بعد زیاد بن ابی سفیان کہا جاتا تھا بھی بصرہ آگئے۔ ان سب کی والدہ سمیہ تھیں جو حارث بن کلدہ کی باندی تھی، بلاذری نے اس کا ذکر کیا ہے۔ اور ہم پہلے بیان کر چکے ہیں کہ حجۃ الوداع کے موقع پر قریش اور ثقیف میں سے کوئی ایسا نہ تھا جو ایمان نہ لایا ہو اور اس موقع پر حاضر نہ ہو۔"],[9397,"§۱۰۷۸۷ ۔ إزمہ\nہمزہ کے زیر اور ”ز“ کے سکون کے ساتھ ہے۔ ہروی رحمہ اللہ کی کتاب الغریبین جسے کسی نے جمع کیا ہے کے ذیل میں ابو موسیٰ المدینی رحمہ اللہ نے ذکر کیا ہے ”اشتدّي إزمة تنفرجي“ اس مثل سے عربوں کی مراد یہ ہے کہ ایک عورت جس کا نام ازمہ تھا سے درد زہ ہوا اس کے بارے میں یہ مثل کہی گئی یعنی اے ازمہ صبر کرو یہاں تک کہ عنقریب تم وضع حمل سے فارغ ہو جاؤ تو تمہاری تکلیف دور ہو جائے گی۔ اسے میں نے اسد الغابہ کے حاشیے سے مغلطائی کی تحریر سے نقل کیا ہے۔ اور ذیل سے اس کی مراجعت کی ہے۔ میں نے اس میں کوئی تصریح نہیں دیکھی جو ان کے صحابیہ ہونے پر دلالت کرتی ہو، انہوں نے اس کے بعد لکھا ہے: بعض جہال نے اس کا ذکر کیا ہے اور یہ باطل ہے۔ اور بعض نے اس میں اضافہ کیا ہے کہ اس سے یہ بات نبی کریم صلی اللہ علیہ وسلم نے فرمائی تھی۔"],[9398,"§۱۰۷۸۸ ۔ أسماء بنت أنس\nبن مدرک التنعمیہ، خالد بن ولید کی زوجہ ہیں، اور ان کی اولاد مہاجر عبد اللہ، عبد الرحمن کی والدہ ہیں، ان کا ذکر ان کے والد انس بن مدرک کے حالات میں گزر چکا ہے۔"],[9399,"§۱۰۷۸۹ ۔ أسماء بنت أبی بکر الصدیق\n(1) ان کا ذکر اسماء بنت عبد اللہ بن عثمان کے حالات میں آئے گا۔","",{"fn":"(1) اسد الغابہ (ت: ۶۶۹۸) تجرید اسماء الصحابہ (۲۴۴/۲)"}],[9400,"§۱۰۷۹۰ ۔ أسماء بنت الحارث\n(1) خطاب بن حارث جمحی کی زوجہ ہیں، ابن اسحاق رحمہ اللہ(2) نے اہل مکہ میں سے ایمان لانے والوں میں ان کا ذکر کیا ہے اور جب ان کا ذکر کیا تو فرمایا: خطاب اور ان کی زوجہ اسماء بنت حارث۔ ابو نعیم نے ابراہیم بن یوسف کی سند سے بحوالہ زیاد البکائی جو ان سے مروی ہے اس کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۶۹۹) تجرید اسماء الصحابہ (۲۴۴/۲)\n(2) السیر والمغازی (۱۴۷)"}],[9401,"§۱۰۷۹۱ ۔ أسماء بنت سعید\nبن زید بن عمرو بن نفیل القرشیہ العدویہ۔ انہیں اور ان کے والد کو شرف صحابیت حاصل ہے۔ دار قطنی(1) نے علل میں ان کی حدیث حفص بن غیاث، أبی حرملہ، اور ان کے والد کی روایت سے نقل کی ہے۔ فرماتے ہیں کہ رباح بن عبدالرحمن فرماتے ہیں کہ مجھ سے میری دادی نے حدیث بیان کی کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا وہ فرما رہے تھے ”اس شخص کی نماز نہیں جس کا وضو نہیں“۔ (الحدیث) اسے بیہقی(2) نے نقل کرنے کے بعد کہا ہے کہ ان کی دادی اسماء بنت سعید بن زید ہیں۔","",{"fn":"(1) دارقطنی فی سننہ (الحدیث: ۷۲/۱)\n(2) بیہقی فی السنن"}],[9402,"§۱۰۷۹۲ ۔ أسماء بنت سلامہ\n(1) کہا جاتا ہے کہ یہ سلمہ بن نضر یہ ہیں (ایک نقطے کے ساتھ) بن جندل بن ابیر بن نبشل بن دارم التمیمیہ الدارمی۔ ابن اسحاق رحمہ اللہ(2) نے ان کا مکہ میں ایمان لانے والوں میں ذکر کیا اور فرمایا عیاش بن ابی ربیعہ بن المغیرہ المخزومی اور ان کی بیوی اسماء بنت سلامہ۔ ابو عمر رحمہ اللہ(3) نے فرمایا: اسماء بنت سلمہ بن مخربہ مہاجرات میں سے تھیں۔ انہوں نے اپنے شوہر کے ساتھ حبشہ ہجرت کی، ان سے عبداللہ بن عیاش بن ابی ربیعہ پیدا ہوئے پھر انہوں نے مدینہ ہجرت کی ان کی کنیت ام الجلاس ہے۔ نبی کریم صلی اللہ علیہ وسلم سے روایت کی، ان سے ان کے بیٹے عبداللہ بن عیاش بن ابی ربیعہ، میں نے کہا: ابن مندہ نے ان کے حالات ان کی پھوپھی اسماء بنت مخربہ سے خلط کر دیئے ہیں۔ ان کی پھوپھی کے حالات میں ان شاء اللہ میں اسے ذکر کروں گا۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۰۱) تجرید اسماء الصحابہ (۲۴۴/۲)\n(2) السیرۃ النبویۃ (۲۰۵/۱)\n(3) الاستیعاب (۱۷۸۳/۴)"}],[9403,"§۱۰۷۹۳ ۔ أسماء بنت سمی\nمسدد نے اپنی مسند میں ان کا ذکر کیا ہے، فرمایا: ہم سے یحیی القطان نے بحوالہ ابی مسکین نقل کیا ہے، فرماتے ہیں کہ میں نے ابو الحکم سے سنا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: اسماء بنت سمی کو اختیار دیا گیا یعنی تیرے شوہر کے بارے میں جسے تو اختیار کرے، انہوں نے عرض کیا، میں فلاں کو اختیار کرتی ہوں، وہ وفات پاگئے وہ سب میں سے اچھے اخلاق والے تھے۔ ان کے دو شوہر قتل ہوئے، یہ حسن اسناد، مرسل ہے۔ اس خبر کو نبی کریم صلی اللہ علیہ وسلم کی صحابہ رضی اللہ عنہم سے بیان کردہ حدیث کے ساتھ ملایا جائے گا۔ اور مشہور یہ ہے کہ یہ تمیم داری کے خصائص میں سے ہے، ان کے علاوہ ایک جماعت کے ساتھ بھی ایسا ہی واقعہ پیش آیا۔"],[9404,"§۱۰۷۹۴ ۔ أسماء بنت شکل\n(1) شین کے ساتھ، دو حروف پر زبر اور آخر میں لام آئے گا۔ صحیح مسلم،(2) کتاب الحیض میں سیدہ عائشہ رضی اللہ عنہا کی سند سے ان کا ذکر ہے۔ فرماتی ہیں: اسماء بنت شکل نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور پوچھا، اے اللہ کے رسول! جب ہم میں سے کوئی حیض سے پاک ہو تو کیسے غسل کرے۔ (الحدیث) ابو موسیٰ نے ذیل میں ان کا ذکر مستغفری کی سند سے کیا ہے۔ ان کی روایت ابی بکر بن ابی شیبہ سے مروی ہے۔ جو اس روایت میں امام مسلم رحمہ اللہ کے استاد ہیں۔ ابوعلی جیانی نے الاستیعاب کے حاشیہ میں لکھا ہے: ابو عمر نے جن صحابیات کا ذکر کیا ہے، معلوم نہیں یہ ان میں سے ایک ہیں یا بعض راویوں نے شکل کے بارے غلطی کی ہے۔ حالانکہ وہ اسماء بنت یزید بن السکن ہیں جن کا ذکر آ رہا ہے۔ ان کے والد کا ذکر چھوٹ گیا ہے۔ اور ان کے دادا کے نام میں لفظی غلطی ہے۔ ان کی نسبت ان کے دادا کی طرف ہے۔ خطیب ابوبکر الحافظ نے اس کی طرف سبقت کی ہے۔ اس کی تائید اس بات سے ہوتی ہے کہ انصار میں سے کسی کا نام شکل نہیں، صحیح بخاری کے اس قصہ سے ثابت ہے کہ وہ صحابیہ جنہوں نے سوال کیا تھا انصاریہ تھیں، ابوالفتح بن سید الناس نے اس کی پیروی کی ہے۔ اس میں تامل ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۰۲) الاستیعاب (ت: ۳۲۷۲) تجرید اسماء الصحابہ (۲۴۴/۲)\n(2) مسلم (الحدیث: ۷۵۰)"}],[9405,"§۱۰۷۹۵ ۔ أسماء بنت عبداللہ بن عثمان\nالتیمیہ، عبداللہ بن زبیر بن عوام التیمیہ کی والدہ ہیں۔ اور وہ ابوبکر صدیق رضی اللہ عنہ کی بیٹی ہیں، ان کی والدہ قتلہ یا قتیلہ بنت عبدالعزی ہیں۔ قریشی ہیں، بنی عامر بن لوی سے ہیں۔ مکہ میں ابتدائی دور میں ایمان لائیں۔ ابن اسحاق رحمہ اللہ نے فرمایا کہ سترہ افراد کے بعد ایمان لائیں، ان سے زبیر بن عوام نے نکاح کیا۔ انہوں نے ہجرت کی اور وہ حاملہ تھیں، جہاں قباء کے مقام پر ان کے ہاں عبداللہ کی ولادت ہوئی۔ اپنے بیٹے کی خلافت تک بقید حیات رہیں جب انہیں شہید کر دیا گیا تو تھوڑے عرصے بعد وفات پا گئیں، ان کا لقب ذات النطاقین تھا۔ ابو عمر رحمہ اللہ نے فرمایا: ان کا یہ نام رسول اللہ صلی اللہ علیہ وسلم نے رکھا تھا، کیونکہ جب آپ صلی اللہ علیہ وسلم نے ہجرت کا قصد کیا تو انہوں نے آپ صلی اللہ علیہ وسلم کے لیے توشہ دان تیار کیا تھا، جب اسے باندھنے کی ضرورت پڑی تو انہوں نے اپنا دوپٹہ پھاڑا، اس کے آدھے حصے سے توشہ دان باندھا اور باقی آدھے کو کمر بند بنالیا۔(1) فرمایا: اسی طرح ابن اسحاق رحمہ اللہ وغیرہ نے ذکر کیا ہے۔ میں نے کہا: اصل قصہ صحیح مسلم میں نبی کریم صلی اللہ علیہ وسلم تک مرفوع روایت کی تصریح کے بغیر ہے اور ابو عمر نے ابونوفل بن ابی عقرب کی سند سے یہ روایت مسند نقل کی ہے کہ انہوں نے حجاج سے کہا تھا کہ میرے پاس ایک کمر بند تھا جس سے میں نبی کریم صلی اللہ علیہ وسلم کے کھانے کو چیونٹیوں سے بچانے کے لیے ڈھانپا کرتی تھی، اور دوسرا کمر بند جو ہر عورت کے لیے ضروری ہے۔ ابن سعد رحمہ اللہ(2) نے لکھا ہے کہ ہم سے ابواسامہ نے ہشام بن عروہ سے انہوں نے اپنے والد اور فاطمہ بنت منذر سے اور انہوں نے سیدہ اسماء رضی اللہ عنہا سے حدیث بیان کی، فرماتی ہیں جب رسول اللہ صلی اللہ علیہ وسلم نے ہجرت کا قصد فرمایا تو میں نے ابوبکر رضی اللہ عنہ کے گھر نبی کریم صلی اللہ علیہ وسلم کے لیے توشہ دان تیار کیا، ہمیں توشہ دان اور مشکیزہ باندھنے کے لیے کوئی شے نہ ملی تو میں نے ابوبکر رضی اللہ عنہ سے عرض کیا: ”میرے پاس اپنے کمر بند کے علاوہ کوئی شے نہیں“۔ فرمایا: ”اسے پھاڑ کر دو حصے کر لو، ان میں سے ایک سے توشہ دان اور دوسرے سے مشکیزہ باندھ دو“۔(3) اس کی سند صحیح ہے۔ اور اسی سند کے ساتھ حضرت عروہ رحمہ اللہ سیدہ اسماء رضی اللہ عنہا سے روایت کرتے ہیں، فرماتی ہیں: مجھ سے زبیر رضی اللہ عنہ نے نکاح کیا، ان کے پاس کوئی مال اور غلام نہ تھا، اور سوائے گھوڑے کے کوئی شے نہ تھی۔ فرماتی ہیں: میں گھوڑے کو چارہ ڈالتی تھی، اس کی دیکھ بھال اور سائسی کرتی تھی، اور ان کے اونٹ کے لیے گٹھلیاں کوٹتی تھی، اور میں گٹھلیاں زبیر رضی اللہ عنہ کی زمین سے لاتی تھی۔۔۔۔ (الحدیث) اور اس حدیث میں یہ بھی ہے: یہاں تک کہ ابوبکر رضی اللہ عنہ نے میرے پاس خادمہ بھیجی تو مجھے گھوڑے کی سائسی سے نجات مل گئی۔ راوی کا بیان ہے: زبیر بن بکار نے اس قصے میں فرمایا، نبی کریم صلی اللہ علیہ وسلم نے ان سے فرمایا: ”اللہ تعالیٰ تمہیں اس کمر بند کے بدلے جنت کے دو کمر بند عطا فرمائے“۔ اس لیے انہیں ذات النطاقین کہا جاتا ہے۔ سیدہ اسماء رضی اللہ عنہا نے کئی احادیث نبی کریم صلی اللہ علیہ وسلم سے روایت کی ہیں جو صحیحین اور سنن میں ہیں۔ ان سے ان کے بیٹوں عبداللہ اور عروہ نے روایت کی اور پوتوں عباد بن عبداللہ، عبداللہ بن عروہ، فاطمہ بنت المنذر بن زبیر، عباد بن حمزہ بن عبداللہ بن زبیر اور آزاد کردہ غلام عبداللہ بن کیسان، ابن عباس، صفیہ بنت شیبہ، ابن ابی ملیکہ اور وہب بن کیسان وغیرہ نے روایت کی ہے۔ ابن اسکن رحمہ اللہ نے ابی الحیاء یحییٰ بن یعلیٰ التیمی کی سند سے اور انہوں نے اپنے والد سے نقل کیا ہے۔ فرماتے ہیں: میں ابن زبیر کے قتل کے بعد مکہ میں داخل ہوا، میں نے انہیں سولی پر لٹکا ہوا دیکھا، میں نے ان کی والدہ اسماء کو دیکھا کہ بے حد عمر رسیدہ، دراز قد اور نابینا ہیں۔ حجاج کے پاس آ کر کہنے لگی: کیا اس سوار (مراد عبداللہ بن زبیر رضی اللہ عنہ) کے اترنے کا وقت نہیں ہوا۔ تو وہ (حجاج) کہنے لگا: یہ منافق تھا۔ اس پر انہوں نے فرمایا: اللہ کی قسم! وہ منافق نہ تھا وہ روزہ دار اور شب دار تھا۔ حجاج کہنے لگا: جائیں! بڑھاپے کی وجہ سے آپ بہکی بہکی باتیں کر رہی ہیں۔ انہوں نے فرمایا: اللہ کی قسم! میں تو نہیں بہکی، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”ثقیف سے شریعت کی تکذیب کرنے والا اور خون ریز ظاہر ہوگا“۔ سو کذاب تو ہم نے دیکھ لیا ہے رہا خون ریز تو وہ تم ہی ہو۔ حجاج نے کہا: اس قبیلہ سے منافق پیدا ہوں گے۔ ابن سعد نے ایک حسن سند سے بحوالہ ابن ابی ملیکہ روایت کی ہے کہ جب ان کے سر میں درد ہوتا تو سر پر ہاتھ رکھ کر فرماتیں: میری خطا کی وجہ سے ہوا اور اللہ تعالیٰ تو اس سے زیادہ معاف کر دیتا ہے۔ ہشام بن عروہ اپنے والد کے حوالے سے نقل کرتے ہیں کہ سیدہ اسماء رضی اللہ عنہا کی عمر سو سال ہوگئی پھر بھی ان کا دانت تک نہ گرا، اور نہ عقل میں فتور آیا۔ ابونعیم اصبہانی کا قول ہے: وہ ہجرت سے ستائیس(۲۷) سال پہلے پیدا ہوئیں اور ۲۴ھ کے ابتدائی دور تک زندہ رہیں۔ بعض لوگوں نے کہا کہ اپنے بیٹے (کی شہادت) کے بعد بیس(۲۰) دن زندہ رہیں، بعض نے کچھ اور کہا ہے۔","",{"fn":"(1) صحیح بخاری (الحدیث: ۲۹۷۹) مسند احمد (الحدیث: ۳۴۶/۶)\n(2) الطبقات الکبریٰ (۱۸۲/۸)\n(3) اس کا حوالہ پہلے گزر چکا ہے۔"}],[9406,"§۱۰۷۹۶ ۔ أسماء بنت عبداللہ بن مسافع\nبن ربیعہ، قیس بن مخربہ کی والدہ ہیں، سیدنا حسان بن ثابت رضی اللہ عنہ کے شعر میں ان کا ذکر ہے۔"],[9407,"§۱۰۷۹۷ ۔ أسماء بنت عدی\nبن عمرو، ان کا ذکر بعد والی صحابیہ کے حالات میں آ رہا ہے۔"],[9408,"§۱۰۷۹۸ ۔ أسماء بنت عمرو بن عدی\n(1) بن تابی بن سواد بن غنم بن کعب بن سلمہ الانصاریہ السلامیہ۔ معاذ بن جبل کی والدہ ہیں، ان کی کنیت ام منبع ہے۔ ابن اسحاق(2) نے صحیح سند کے ساتھ سیدنا کعب بن مالک رضی اللہ عنہ سے نقل کیا ہے کہ وہ اور نسیبہ بنت کعب ان ستر لوگوں کے ساتھ تھیں جو عقبہ میں حاضر تھے اور تجرید میں فرمایا(3) اور کہا گیا ہے کہ وہ اسماء بنت عدی بن عمرو ہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۰۵) الاستیعاب (ت: ۳۲۷۴) تجرید اسماء الصحابہ (۲۴۴/۲)\n(2) السیرۃ النبویۃ (۶۳/۲)\n(3) تجرید (۱۸۰)"}],[9409,"§۱۰۷۹۹ ۔ أسماء بنت عمرو بن مخربہ\nاسماء بنت مخربہ کے حالات میں ان کا ذکر آئے گا۔"],[9410,"§۱۰۸۰۰ ۔ أسماء بنت عمیس\n(1) بن معد (بروزن سعد) اس کے شروع میں میم ہے۔ ابن حبیب نے اسے قلمبند کیا ہے اور استیعاب میں عین کے فتح کے ساتھ معد ہے۔ جس کا تعاقب کیا گیا ہے اور کہا گیا ہے ابن الحارث بن تیم بن کعب بن مالک بن محافہ بن عامر بن ربیعہ بن غانم بن معاویہ بن زید الخثعمیہ، اور کہا گیا ہے، عمیس ابن نعمان بن کعب اور باقی اسی طرح ہے۔ میمونہ بنت حارث کی ماں شریک بہن ہیں، جو نبی کریم صلی اللہ علیہ وسلم کی زوجہ ہیں اور کئی صحابیات کی باپ شریک یا ماں شریک یا حقیقی بہن ہیں۔ بعض نے کہا ہے کہ ان کی تعداد نو ہے اور بعض نے کہا کہ ماں شریک دس، حقیقی بہنیں چھ ہیں، جن میں سے ایک خولہ بنت عوف بن زہیر ہیں، اور ابو عمر کی کتاب میں خولہ کی جگہ ہند لکھا ہے۔ ابو عمر کہتے ہیں کہ وہ ان مہاجر خواتین میں سے ہیں جنہوں نے اپنے خاوند ابو طالب کے ہمراہ حبشہ ہجرت کی، وہاں ان کی اولاد ہوئی۔ جب سیدنا جعفر رضی اللہ عنہ شہید ہوئے تو بعد میں سیدنا ابو بکر رضی اللہ عنہ نے ان سے شادی کر لی جس سے ان کے ہاں محمد(2) پیدا ہوئے پھر ان سے سیدنا علی رضی اللہ عنہ نے شادی کی، کچھ لوگ کہتے ہیں کہ ان کے ہاں عون کی ولادت ہوئی، ابوعمر کہتے ہیں کہ اس روایت میں ابن کلبی تنہا ہیں، جو اس طرح کہا ہے۔ ابن سعد رحمہ اللہ(3) نے بحوالہ واقدی ذکر کیا ہے کہ سیدنا علی رضی اللہ عنہ کے ہاں اُن سے عون اور بیٹی پیدا ہوئے اور ابن سعد ہی نے بحوالہ واقدی، وہ محمد بن صالح سے وہ یزید بن رومان سے نقل کرتے ہیں کہ دار ارقم میں داخل ہونے سے پہلے اسماء مسلمان ہو گئی تھیں۔ پھر بیعت کر کے جعفر کے ساتھ حبشہ ہجرت کر گئیں جہاں عبداللہ، محمد اور عون پیدا ہوئے۔ جعفر رضی اللہ عنہ کی شہادت کے بعد سیدنا ابو بکر رضی اللہ عنہ نے ان سے شادی کر لی۔ ابن وہب رحمہ اللہ نے بحوالہ عمرو بن الحارث، سعد بن ابی ہلال سے ان کا تذکرہ کیا ہے۔ فرماتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے جنگ حنین کے دن اسماء بنت عمیس کی سیدنا ابو بکر رضی اللہ عنہ سے شادی کرائی، اس بات کو عمر بن شبہ نے کتاب مکہ میں نقل کیا ہے۔ اور یہ اچھی سند والی مرسل روایت ہے۔ سیدہ اسماء نبی صلی اللہ علیہ وسلم سے روایت کرتی ہیں اور ان سے ان کے بیٹے عبداللہ بن جعفر، پوتے قاسم بن محمد بن ابو بکر اور عبداللہ بن عباس جو ان کے بھانجے اور لبابہ بنت حارث کے بیٹے ہیں، اور ان کی دوسری بہن کے بیٹے عبد اللہ بن شداد بن الہاد اور ان کی پوتی ام عون بنت محمد بن جعفر بن ابی طالب، اور ان کے علاوہ سعید بن المسیب اور عروہ بن زبیر اور دوسرے لوگوں نے روایت کی ہے۔ سیدنا عمر رضی اللہ عنہ ان سے خواب کی تعبیر پوچھتے تھے، جس کے متعلق ان سے اور ان کے علاوہ لوگوں سے کئی چیزیں منقول ہیں۔ بخاری کے باب ہجرۃ الحبشۃ میں ابی بردہ بن ابی موسیٰ کی سند سے لکھا ہے وہ اپنے والد اور سیدہ اسماء رضی اللہ عنہا سے نقل کرتے ہیں۔ پھر ایک حدیث ذکر کی اور اسماء رضی اللہ عنہا سے مراد یہی ہیں جن کے حالات بیان ہو رہے ہیں، کہا جاتا ہے کہ انہیں جب مصر میں اپنے بیٹے محمد کے قتل ہونے کی اطلاع ملی تو گھر کی مسجد میں نماز پڑھنے کھڑی ہوگئیں، اپنا غصہ پی لیا، یہاں تک کہ ان کے پستانوں سے خون بہنے لگا اور صحیح روایت میں ابو بردہ بحوالہ سیدہ اسماء رضی اللہ عنہا مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ان سے فرمایا: تمہارے لیے دو ہجرتیں اور لوگوں کے لیے ایک ہجرت ہے۔ ابن سعد رحمہ اللہ نے اس روایت کو شعبی کی مراسیل سے نقل کیا ہے کہ سیدہ اسماء رضی اللہ عنہا نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! کیا کچھ لوگ ہم پر فخر کرتے ہوئے یہ جتلاتے ہیں کہ ہم پہلے پہل ہجرت کرنے والوں میں سے نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: کیوں نہیں! تمہارے لیے دو ہجرتوں کا ثواب ہے۔ پھر کئی طرق سے یہ بات ذکر کی کہ سیدنا ابوبکر صدیق رضی اللہ عنہ نے اس بات کی وصیت کی کہ (وفات کے وقت) ان کی بیوی اسماء بنت عمیس انہیں غسل دے۔ شعبی رحمہ اللہ سے ابن اسکن نے صحیح سند کے ساتھ نقل کیا ہے، فرمایا: اسماء بنت عمیس سے سیدنا علی رضی اللہ عنہ نے نکاح کیا تو ان کے دونوں بیٹوں محمد بن جعفر اور محمد بن ابو بکر نے آپس میں ایک دوسرے پر فخر کیا، ان میں سے ہر ایک نے کہا میں تم سے زیادہ عزت والا ہوں اور میرا باپ تیرے والد سے زیادہ بہتر ہے۔ تو ان سے سیدنا علی رضی اللہ عنہ نے فرمایا: ان دونوں کے درمیان فیصلہ کرو۔ انہوں نے کہا: میں نے جعفر سے زیادہ اچھا جوان نہیں دیکھا اور ابوبکر بوڑھوں میں سب سے بہتر تھے، ان سے سیدنا علی رضی اللہ عنہ نے فرمایا: تو ہمارے لیے کیا باقی رہا؟","",{"fn":"(1) اسد الغابہ (ت: ۶۷۰۶) تجرید اسماء الصحابہ (۲۴۴/۲)\n(2) جامع المسانید والسنن (۲۴۸/۱۵)\n(3) الطبقات الکبریٰ (۲۰۵/۸)"}],[9411,"§۱۰۸۰۱ ۔ اسماء بنت قرط\n(1) بن خنساء بن سنان انصاریہ، فضل بن نعمان کی زوجہ ہیں۔ ابن سعد رحمہ اللہ(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید اسماء الصحابہ (۲۴۴/۲)\n(2) الطبقات الکبریٰ (۲۹۴/۸)"}],[9412,"§۱۰۸۰۲ ۔ اسماء بنت کعب\nان کا ذکر اسماء بنت نعمان کے حالات میں ہے۔"],[9413,"§۱۰۸۰۳ ۔ اسماء بنت محرز\n(1) بن عامر بن مالک بن عدی بن عامر بن غنم بن عدی بن نجار، ابن سعد رحمہ اللہ(2) نے ان کا ذکر کیا ہے اور فرمایا ان کی والدہ ام سہل بنت ابی خارجہ ہیں، ان سے ابو بشیر بن عبید نے نکاح کیا جس سے بشیر اور جعد پیدا ہوئے، ابن ماکولا رحمہ اللہ(3) نے تجرید میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید اسماء الصحابہ (۲۵۵/۲)\n(2) الطبقات الکبریٰ (۳۰۹/۸)\n(3) الاکمال (۲۴۳/۲)"}],[9414,"§۱۰۸۰۴ ۔ اسماء بنت مخربہ\n(1) ان کا نسب اسماء بنت سلامہ بن مخربہ کے ترجمہ میں گزر چکا ہے۔ بلاذری رحمہ اللہ نے ابوعبیدہ معمر بن مثنیٰ کے حوالے سے ذکر کیا ہے کہ ہشام بن مغیرہ نجران آئے، وہاں اسماء بنت مخربہ کو دیکھا۔ بعض نے کہا: بنت عمرو بن مُخَرَّبہ بن جندل بن ابیر بن نہمل بن دارم، یہ انہیں بھلی لگیں اور نکاح کر کے مکہ لے آئے، ان سے ابو جہل اور حارث پیدا ہوئے۔ جب وہ فوت ہوئے تو ان سے عبداللہ بن ابی ربیعہ بن المغیرہ نے شادی کی، جس سے عیاش پیدا ہوئے جو کہ ابو جہل اور حارث کے ماں شریک بھائی تھے۔ ابن سعد رحمہ اللہ نے لکھا ہے، ان سے عبداللہ اور ام مجیر بھی پیدا ہوئے، اور محمد بن سعد نے کہا کہ وہ حالت کفر میں فوت ہوئیں، یہ ان کے بیٹے عیاش کی مدینہ ہجرت سے پہلے کا واقعہ ہے۔ اور بعض نے کہا کہ وہ اسلام لائیں اور سیدنا عمر رضی اللہ عنہ کی خلافت پائی اور یہ زیادہ صحیح ہے۔ پھر واقدی رحمہ اللہ کی سند سے ایک روایت بیان کی جو انہوں نے عبدالحمید بن جعفر، ابو عبیدہ بن محمد بن عمار کے حوالے سے نقل کی کہ انہوں نے ربیع بنت معوذ سے سنا، فرماتی ہیں: میں انصار کی عورتوں کے ساتھ اسماء بنت مخربہ کے پاس آئی، وہ ابو جہل کی ماں ہیں۔ یہ سیدنا عمر رضی اللہ عنہ کی خلافت کی بات ہے۔ ان کا بیٹا عیاش بن عبداللہ بن ابو ربیعہ ان کے پاس یمن سے عطر بھیجا کرتا تھا۔ وہ یہ عطر ہدیہ دینے والی عورتوں کے ہاتھ بیچتی تھیں، اس نے مجھ سے کہا: تو اپنے سردار کے قاتل کی بیٹی ہے۔ میں نے کہا: نہیں! میں غلام کے قاتل کی بیٹی ہوں۔ کہنے لگیں: مجھ پر حرام ہے کہ میں تمہیں عطر بیچوں۔ میں نے کہا: مجھ پر حرام ہے کہ میں اس میں سے کچھ خریدوں، میں نے تمہارے عطر سے زیادہ بدبودار شے نہیں دیکھی۔ اور ایک روایت میں ہے: اللہ کی قسم! یہ خوشبودار عطر نہیں ہے۔ اللہ کی قسم! میں نے اس سے اچھا عطر نہیں سونگھا، لیکن میں نے غصے کی وجہ سے یہ کہہ دیا۔ میں نے کہا: یہ وہ اشعار کہنے والی ہیں جنہوں نے ننگے طواف کیا تھا۔ “آج سارا یا کچھ بدن ظاہر ہو جائے گا، تو جو اس سے ظاہر ہوگا میں اسے حلال نہیں کروں گی، بہت سے عقل و دانش والے اور دیکھنے والے کو گمراہ کر دے گی، جس کی میں وجہ بیان کر رہی ہوں۔” بعض نے کہا کہ یہ آیت ﴿خُذُوْا زِیْنَتَکُمْ عِنْدَ کُلِّ مَسْجِدٍ﴾(2) “یعنی ہر عبادت کے وقت اپنی زینت کو اختیار کرو” اس کے بارے میں نازل ہوئی اور صحیح مسلم میں ہے۔ ابو عمر(3) نے فرمایا: ان کی بھتیجی کے حالات میں اسماء بنت سلامہ ہیں۔ وہ ام عبداللہ بن عیاش بن ابی ربیعہ ہیں۔ ام عیاش ان کا نام ہے، اسی طرح اسماء بنت مخربہ بھی ہیں، جو ابو جہل اور حارث بن ہشام کی ماں ہیں۔ یہی اسماء بنت مخربہ اور ام الجلاس ہیں، عبداللہ اور عیاش کی والدہ ہیں جو ابو ربیعہ کے بیٹے ہیں۔ ان سے عبداللہ بن عیاش اور ربیع بنت معوذ نے روایت کیا ہے، اور اسحاق بن محمد القروی کے سلسلے سے سند بیان کی ہے جو انہوں نے عبدالرحمن بن ابو زناد سے، انہوں نے عبدالرحمن بن حارث سے، انہوں نے اپنے بھائی عبداللہ بن حارث سے، جنہوں نے عبداللہ بن عیاش بن ابو ربیعہ سے سنا، فرماتی ہیں: نبی کریم صلی اللہ علیہ وسلم ابو ربیعہ کے کسی گھر میں عیادت کرنے یا کسی اور وجہ سے تشریف لائے تو سیدہ اسماء التمیمیہ رضی اللہ عنہا نے عرض کی، ان کی کنیت ام الجلاس تھی، اور یہ ام عیاش بن ابی ربیعہ ہیں۔ یا رسول اللہ صلی اللہ علیہ وسلم مجھے وصیت کیجئے۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: اے ام الجلاس! اپنے بھائی کے ساتھ وہ معاملہ کرو جو تم پسند کرتی ہو کہ وہ تمہارے ساتھ کرے، اور اپنے بھائی کے لیے وہ چیز پسند کرو جو تم چاہتی ہو کہ وہ تمہارے لیے پسند کرے۔ پھر نبی کریم صلی اللہ علیہ وسلم عیاش کے بچوں میں سے ایک بچے کے پاس تشریف لائے، ام الجلاس نے نبی کریم صلی اللہ علیہ وسلم سے اس کی بیماری کا ذکر کیا، نبی کریم صلی اللہ علیہ وسلم اس پر جھاڑ پھونک کرنے لگے، بچہ بھی ایسا کرنے لگا، بعض گھر والوں نے بچے کو روکا تو نبی کریم صلی اللہ علیہ وسلم نے انہیں روکا۔ میں کہتا ہوں کہ ربیع بنت معوذ اور عبداللہ بن عیاش دونوں کے قصوں میں گڈمڈ کر دیا ہے۔ ربیع کا قصہ تو اس اسماء بنت مخربہ کے ساتھ پیش آیا ہے جن کے صحابیہ ہونے میں اختلاف ہے۔ اور عبداللہ بن عیاش کا قصہ جو اس حدیث میں ہے وہ ان کی والدہ ہیں، جن کے صحابیہ ہونے پر اتفاق ہے۔ جبکہ زبیر بن بکار نے دونوں عورتوں میں فرق کیا ہے۔ چنانچہ جب انہوں نے حارث بن ہشام کا ذکر کیا تو کہا وہ عمرو یعنی ابو جہل کے حقیقی بھائی ہیں۔ دونوں کی والدہ اسماء بنت مخربہ ہیں۔ ان دونوں کے ماں شریک بھائی عبداللہ بن عبداللہ بن ابی ربیعہ اور عیاش بن عبداللہ بن ابی ربیعہ ہیں۔ پھر ان کی ہجرت، ماں کی قسم اور ان کے مکہ لوٹنے کا ذکر کیا اور جب عبداللہ بن عیاش بن ابی ربیعہ اور ان کی والدہ اسماء بنت سلامہ بن مخربہ کا ذکر کیا تو کہا۔ میں کہتا ہوں جس قصے میں ان کی طرف اشارہ ہے۔ اس کا ابن اسحاق رحمہ اللہ نے ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۰۷) تجرید اسماء الصحابہ (۲۴۵/۲)\n(2) سورۃ الاعراف الآیۃ (۳۱)\n(3) الاستيعاب (۱۷۸۳/۴)"}],[9415,"§۱۰۸۰۵ ۔ اسماء بنت مرثد\n(1) بنی حارثہ سے ہیں۔ ابو عمر رحمہ اللہ(2) نے ان کا ذکر کیا ہے، ان سے حدیث صحیح نہیں، حرام بن عثمان ان سے روایت کرنے میں منفرد ہیں، وہ سب کے نزدیک ضعیف ہیں۔ اسماعیل بن اسحاق قاضی نے احکام میں ان سے متصل روایت بیان کی ہے، روایت دراوردی کی سند سے اور ابن مندہ نے ابراہیم بن طہمان کے سلسلے سے بیان کی ہے۔ دونوں نے حرام بن عثمان اور عبدالرحمن، محمد سے جو جابر کے بیٹے ہیں، اور ابو عتیق بن عبداللہ سے اور انہوں نے جابر بن عبداللہ سے روایت کی ہے کہ اسماء بنت مرثد بنو حارثہ کی بہن ہیں۔ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور عرض کی: یا رسول اللہ صلی اللہ علیہ وسلم مجھے طہر کے تین چار دن کے بعد پھر حیض آ جاتا ہے۔ کیا مجھ پر نماز حرام ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: “جب تم (حیض کا خون) دیکھو تو تین دن رات ٹھہر جاؤ، پھر پاک ہو کر نماز پڑھو۔”(3) میں کہتا ہوں: ابن سعد رحمہ اللہ(4) نے “الطبقات” میں “اسماء بنت مرثدہ (ہاء زیادہ کیا ہے) بن جبیر بن مالک بن خویرش بن خارجہ، اور فرمایا: ان کی والدہ سلامہ بنت مسعود ہیں، اور لکھا ہے کہ ان سے ضحاک بن خلیفہ نے شادی کی، جس سے ثابت، ابوبکر، ابو الحسن، عمر، شبیتہ، بکرہ، حمادہ اور صفیہ پیدا ہوئے۔ محمد بن سلمہ نے شبیتہ سے شادی کی۔ راوی نے کہا کہ اسماء اسلام لائیں اور بیعت کی۔ میں کہتا ہوں کہ یوں لگتا ہے کہ یہ وہی ہیں جن کا حدیث جابر میں ذکر ہے اور یہ بھی ہو سکتا ہے کہ وہ اس کے علاوہ ہوں۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۰۸) الاستيعاب (ت: ۳۲۷۶) تجرید اسماء الصحابہ (۲۴۵/۲)\n(2) الاستيعاب (۱۷۸۵/۴)\n(3) جامع المسانید والسنن (۲۶۵/۱۵)\n(4) الطبقات الکبریٰ (۲۴۵/۸)"}],[9416,"§۱۰۸۰۶ ۔ اسماء بنت النعمان\n(1) بن حارث بن شراحیل، بعض نے کہا ہے کہ بنت نعمان بن الاسود بن حارث بن شراحیل الکندیہ، ابو عمر رحمہ اللہ(2) نے لکھا ہے: اس بات پر اتفاق ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ان سے نکاح کیا تھا۔ لوگوں نے ان کے فراق کے قصے میں اختلاف کیا ہے، یہاں تک کہ کہتے ہیں کہ قتادہ رحمہ اللہ نے کہا کہ وہ اسماء بنت نعمان ہیں۔ بنو حارث سے ان کا تعلق ہے۔ نبی کریم صلی اللہ علیہ وسلم کے پاس بھیجی گئیں تو آپ صلی اللہ علیہ وسلم نے انہیں بلایا، وہ کہنے لگیں: آپ ہی آ جائیں اور آنے سے انکار کر دیا۔ قتادہ رحمہ اللہ فرماتے ہیں: انہوں نے نبی علیہ السلام سے کہہ دیا تھا میں آپ صلی اللہ علیہ وسلم سے اللہ کی پناہ چاہتی ہوں، تو آپ صلی اللہ علیہ وسلم نے فرمایا: تو نے اس کی پناہ لی جس کی پناہ لی جاتی ہے۔ یہ بات جھوٹ ہے۔ یہ بات جس عورت نے کی تھی وہ اور ہے جس کا تعلق بنی سلیم سے تھا۔ ابو عبیدہ فرماتے ہیں کہ ان دونوں نے آپ صلی اللہ علیہ وسلم سے اللہ کی پناہ مانگی تھی، ابو عبیدہ کے علاوہ کسی نے کہا ہے کہ پناہ طلب کرنے والی عورت کا تعلق بنو عنبر سے تھا جو ذات الشقوق کے قیدیوں میں سے خوبصورت عورت تھی، تو آپ صلی اللہ علیہ وسلم کی ازواج کو خدشہ ہوا کہ کہیں یہ ہمارے مقابلے میں آپ صلی اللہ علیہ وسلم پر اپنے حسن کا جادو نہ چلا دے۔ عبداللہ بن محمد بن عقیل کہتے ہیں: کندیہ وہ بدبخت عورت ہے جس نے آپ صلی اللہ علیہ وسلم سے جدائی کا مطالبہ کیا تھا اور کہا تھا کہ اسے اس کی قوم کی طرف واپس کر دیا جائے۔ چنانچہ آپ صلی اللہ علیہ وسلم نے ایسا ہی کیا اور ابو اسید ساعدی رضی اللہ عنہ کے ہمراہ اسے واپس بھیج دیا۔ دیگر حضرات کا کہنا یہ ہے کہ اسماء بنت نعمان کندیہ خوبصورت عورت تھی، آپ صلی اللہ علیہ وسلم کی ازواج کو اندیشہ ہوا کہ آپ صلی اللہ علیہ وسلم پر ہمارے مقابلے میں اس کا حسن کہیں چھا نہ جائے، تو ان سب نے اس سے کہا: آپ صلی اللہ علیہ وسلم یہ پسند کرتے ہیں کہ جب وہ تمہارے قریب آئیں تو تم کہہ دینا میں آپ سے اللہ کی پناہ چاہتی ہوں۔ چنانچہ انہوں نے ایسا ہی کیا۔ بعد میں وہ اپنے آپ کو بدبخت کہتی تھیں۔ اور جرجانی نے اضافہ کیا ہے کہ اس کے بعد وہ مہاجر بن ابو امیہ مخزومی کے نکاح میں آئیں پھر قیس بن مکشوح المرادی سے شادی ہوئی۔ ابو عمر(3) نے لکھا ہے: بعض نے ان کا نام امیمہ بنت نعمان اور بعض نے امامہ بتایا ہے۔ جبکہ زیادہ اختلاف و اضطراب کندیہ اور ان کے ساتھ کی ان عورتوں میں ہے جن سے آپ صلی اللہ علیہ وسلم نے صحبت نہیں کی۔ میں کہتا ہوں: محمد بن حبیب نے ان عورتوں کے فضائل میں جن سے آپ صلی اللہ علیہ وسلم نے صحبت نہیں کی جو قول پہلے مذکور ہو چکا اسی جیسا قول ذکر کیا ہے، اور کہا ہے کہ وہ عورتوں میں سے حسین و جمیل تھیں۔ پھر عورتوں کا اُن کے ساتھ اور ان کی جدائی کا قصہ ذکر کیا اور یہ کہ مہاجر نے اور پھر قیس بن مکشوح نے ان سے شادی کی تھی۔ پھر فرماتے ہیں کہ جونیہ بھی کندہ کی ایک عورت ہے جسے ابو اسید الساعدی لائے۔ سیدہ عائشہ اور سیدہ حفصہ رضی اللہ عنہما اس کی دیکھ بھال پر مقرر ہوئیں۔ ان میں سے ایک اس سے کہنے لگی: آپ صلی اللہ علیہ وسلم کو یہ بات بڑی پسند ہے کہ جب کوئی عورت آپ صلی اللہ علیہ وسلم کے پاس (بیوی بن کر) آئے اور یوں کہے: میں آپ سے اللہ کی پناہ چاہتی ہوں، پھر سارا قصہ ذکر کیا۔ میں کہتا ہوں: صحیح بخاری(4) میں اوزاعی کی سند سے جونیہ کے بارے میں ہے، فرماتے ہیں کہ میں نے زہری رحمہ اللہ سے سوال کیا، نبی کریم صلی اللہ علیہ وسلم کی کسی زوجہ نے آپ سے پناہ چاہی تھی۔ فرمایا: مجھے عروہ رضی اللہ عنہ نے عائشہ رضی اللہ عنہا کے حوالے سے بتایا فرماتی ہیں کہ جون قبیلے کی عورت نبی کریم صلی اللہ علیہ وسلم کے نکاح میں آئی جب آپ صلی اللہ علیہ وسلم اس کے قریب ہوئے تو کہنے لگی: میں تجھ سے اللہ کی پناہ چاہتی ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: تم نے بڑی ذات کی پناہ مانگی ہے، اپنے گھر والوں کے پاس چلی جاؤ۔ اور حمزہ بن ابی اسید کی سند سے بحوالہ ابو اسید نقل کیا ہے، فرماتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ باہر نکلے، چلتے چلتے “شوط” نامی ایک باغ میں پہنچے، آپ صلی اللہ علیہ وسلم نے فرمایا: یہاں بیٹھ جاؤ۔ آپ صلی اللہ علیہ وسلم اندر داخل ہوئے، جونیہ کو لایا جا چکا تھا۔ وہ سیدنا علی رضی اللہ عنہ کے گھر میں ٹھہری ہوئی تھیں، ان کے ساتھ ان کی سواری تھی۔ جب آپ صلی اللہ علیہ وسلم اس کے پاس گئے، اس سے فرمایا: اپنی جان میرے سپرد کر دو، وہ کہنے لگی: بھلا کوئی ملکہ کسی غلام کو اپنی جان کا ہبہ کر سکتی ہے؟ آپ صلی اللہ علیہ وسلم نے اس کا غصہ ٹھنڈا کرنے کے لیے اس پر ہاتھ رکھنا چاہا تو جھٹ سے بولی: آپ سے اللہ کی پناہ، آپ صلی اللہ علیہ وسلم نے (ہاتھ کھینچ کر) فرمایا: جس کی پناہ لی جاتی ہے، تو نے اس کی پناہ مانگی۔ پھر راوی نے وہ حدیث نقل کی۔ ابن سعد(5) نے کئی طرق سے جو سارے کے سارے واقدی رحمہ اللہ سے منقول ہیں نقل کیا ہے کہ جونیہ نے نبی علیہ السلام سے پناہ مانگی تھی، پھر اس میں اختلاف ہے کہ آیا وہ نعمان کی بیٹی تھی یا بہن؟ عبداللہ بن جعفر مخزومی کے حوالے سے اس کا نام امیہ بتایا ہے۔ ابن سعد رحمہ اللہ ہی نے ہشام بن محمد جو ابن کلبی ہے، کے واسطے سے ابن الغسیل رحمہ اللہ(6) جن کی روایت امام بخاری رحمہ اللہ نے نقل کی ہے، نقل کیا ہے، اور اس میں یہ اضافہ ہے۔ سیدہ عائشہ رضی اللہ عنہا سے حفصہ رضی اللہ عنہا نے یا سیدہ حفصہ سے سیدہ عائشہ رضی اللہ عنہا نے کہا: تم اس کا بناؤ سنگھار کرو، میں اس کی کنگھی کرتی ہوں۔ جب دونوں یہ کام کر چکیں تو ان میں سے ایک نے اسے کہا: انہیں عورت کی یہ بات پسند ہوتی ہے جب وہ ان کے پاس آئے کہ وہ کہہ دے آپ سے اللہ کی پناہ۔ چنانچہ جب وہ اندر بھیجی گئیں، دروازہ بند کر کے پردے لٹکا دیئے گئے، آپ صلی اللہ علیہ وسلم نے اس کی طرف ہاتھ بڑھایا تو اس نے کہا: اللہ کی پناہ، آپ صلی اللہ علیہ وسلم نے اپنی آستین کو چہرے پر ڈال کر تین بار فرمایا: تو نے اس کی پناہ مانگی جس کی پناہ مانگی جاتی ہے، پھر میرے پاس آ کر فرمایا: ابو اسید! اسے دو کتانی جوڑوں کے ساتھ اس کے گھر پہنچا دو، بعد میں وہ کہتی رہتی تھیں: مجھے بدبخت کہو۔ اور عمر بن الحکم کی سند سے بحوالہ ابو اسید اس قصے میں ہے، میں نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم میں آپ کے گھر والوں کو لے آیا، چنانچہ آپ باہر نکل کر چلنے لگے میں بھی آپ صلی اللہ علیہ وسلم کے ساتھ تھا، اور بیٹھ کر اسے چومنا چاہا، اور آپ صلی اللہ علیہ وسلم کی یہ عادت مبارکہ تھا کہ جب اپنی ازواج میں سے کسی کے ساتھ تنہا ہوتے تو ایسا کرتے، تو وہ جھٹ سے بولی: آپ سے اللہ بچائے۔ (الحدیث) اس میں موسیٰ بن عبیدہ ضعیف راوی ہے۔ عباس بن سہل کی سند سے بحوالہ ابو اسید منقول ہے، فرمایا: جب میں اسے لے کر اس کی قوم کے سامنے ہوا تو چیخ کر کہنے لگے: تو بے برکت ہے۔ تو نے عرب میں ہماری کافی شہرت کرائی تھی، اب تمہیں کیا مصیبت پہنچی؟ وہ کہنے لگی: میں فریب خوردہ ہوگئی تھی۔ اس کے بعد اس نے ابو اسید سے کہا: اب میں کیا کروں؟ انہوں نے فرمایا: اپنے گھر میں ٹھہری رہو اور سوائے محرم رشتہ داروں کے سب سے پردہ کرو، یوں کہ کسی کو تمہارے بارے کوئی خواہش نہ ہو۔ چنانچہ انہوں نے ایسا ہی کیا یہاں تک کہ سیدنا عثمان رضی اللہ عنہ کی خلافت میں فوت ہو گئیں۔ ابن کلبی رحمہ اللہ سے بحوالہ ان کے والد، وہ ابو صالح سے، وہ ابن عباس رضی اللہ عنہما سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اسماء بنت نعمان سے شادی کی، اور وہ اس دور کی سب سے خوبصورت عورت تھی۔ سیدہ عائشہ رضی اللہ عنہا کہنے لگیں: آپ صلی اللہ علیہ وسلم نے کسی انوکھی چیز پر ہاتھ جا دھرا ہے، ایسا نہ ہو وہ آپ صلی اللہ علیہ وسلم کو ہم سے لاپرواہ کر دے۔ آپ صلی اللہ علیہ وسلم نے انہیں نکاح کا پیغام اس وقت دیا تھا جب ان کے والد کندہ کے وفد میں آپ صلی اللہ علیہ وسلم کے پاس آئے تھے۔ آپ صلی اللہ علیہ وسلم کی ازواج نے جب انہیں دیکھا تو انہیں اس پر رشک ہوا اور ان سے کہہ دیا: اگر تم ان کے پاس کوئی مقام چاہتی ہو تو اس طرح کرنا.... پھر سارا واقعہ ذکر کیا۔ اسی سند سے سیدنا ابن عباس رضی اللہ عنہما سے منقول ہے کہ فرمایا: بعد میں اسماء بنت نعمان سے مہاجر بن ابی امیہ نے نکاح کر لیا۔ سیدنا عمر رضی اللہ عنہ نے ان کو سزا دینا چاہی تو وہ بولیں: اللہ کی قسم! پردہ مجھ پر مسلط نہیں کر دیا گیا اور نہ مجھے ام المومنین کہا گیا۔ تو آپ رضی اللہ عنہ نے یہ ارادہ ترک کر دیا۔ واقدی رحمہ اللہ سے مروی ہے، کہتے ہیں کہ مجھے یہ اطلاع ملی کہ عکرمہ بن ابی جہل نے زمانہ ارتداد میں ان سے شادی کر لی تھی، لیکن اس کا ثبوت نہیں ملتا۔ اور سعید بن عبدالرحمن بن ابزی کی سند سے منقول ہے کہ سوائے جونیہ کے کسی نے پناہ نہیں مانگی۔ ادھر ابن سعد رحمہ اللہ نے واقدی کے حوالے سے اپنی سند کے ذریعے جونیہ کا لمبا قصہ ذکر کیا ہے۔ (ہمارے ہاں) نعمان بن ابی الجون کے سوانح میں وہ قصہ پہلے ذکر ہو چکا ہے جس کے آخر میں ہے کہ یہ واقعہ نو(۹) ہجری ربیع الاول میں پیش آیا۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۰۹) الاستيعاب (ت: ۳۲۷۷) تجرید اسماء الصحابہ (۲۴۵/۲)\n(2) الاستيعاب (۱۷۸۵/۴)\n(3) استيعاب (۱۷۸۷/۴)\n(4) بخاری (الحدیث: ۵۲۵۴)\n(5) الطبقات الکبریٰ (۱۰۴/۶)\n(6) بخاری (الحدیث: ۵۲۵۵)"}],[9417,"§۱۰۸۰۷ ۔ اسماء بنت یزید\n(1) بن السکن بن رافع بن امرئ القیس بن زید بن عبد الاشہل بن جشم بن حارث انصاریہ اوسیہ پھر اشہلیہ۔ ابو علی بن سکن نے لکھا ہے: یہ معاذ بن جبل کی چچا زاد ہیں، ان کی کنیت ام سلمہ تھی، اور انہیں خطیبہ النساء (عورتوں کی خطیب) کہا جاتا تھا۔ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے کئی احادیث روایت کی ہیں۔ حسن سند سے ابوداؤد نے ان سے روایت کی ہے۔ فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم سے فرماتے ہوئے سنا: “اپنی اولاد کو اے عورتو! خفیہ قتل مت کرو، اس لیے کہ دھوکے کا قتل شہسوار کو پالتا ہے اور اسے گھوڑے سے گرا دیتا ہے۔” محمود بن عمرو انصاری جو ان کے بھانجے ہیں، انہوں نے ان سے روایت کی ہے۔ اور مہاجر بن ابی مسلم جو ان کے غلام ہیں، اور شہر بن حوشب نے بھی ان سے احادیث نقل کی ہیں۔ ابن سکن رحمہ اللہ نے فرمایا: وہ ان سے سب سے زیادہ روایت کرنے والے ہیں۔ ان کی کئی احادیث احمد رحمہ اللہ کی مسند(2) میں ہیں۔ اور ابن سعد نے لکھا ہے کہ انہوں نے دوسری صحابیات کے ساتھ نبی کریم صلی اللہ علیہ وسلم سے بیعت کی اور اس روایت میں یہ الفاظ ہیں: “میں عورتوں سے مصافحہ نہیں کرتا۔” ترمذی رحمہ اللہ نے یزید بن عبداللہ الشیبانی کی سند نقل کرنے کے بعد کہا ہے کہ میں نے شہر بن حوشب سے فرماتے ہوئے سنا کہ ہم سے ام سلمہ الانصاریہ رضی اللہ عنہا نے روایت کی، فرماتی ہیں کہ آپ صلی اللہ علیہ وسلم سے بیعت کرنے والی خواتین میں سے ایک صحابیہ نے آپ صلی اللہ علیہ وسلم سے پوچھا: کیا ہمارے لیے آپ صلی اللہ علیہ وسلم کی نافرمانی کا کوئی عذر باقی بچتا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: نہیں۔ اسی مفہوم کی حدیث ہے۔ عبد بن حمید کہتے ہیں: ام سلمہ انصاریہ رضی اللہ عنہا وہی اسماء بنت یزید بن سکن ہیں جو جنگ یرموک میں شریک تھیں اس دن انہوں نے خیمے کے کھونٹے سے نو(۹) رومی قتل کر دیئے تھے۔ اس کے بعد بھی کافی عرصہ زندہ رہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۱۰) تجرید اسماء الصحابہ (۲۴۵/۲)\n(2) مسند احمد (الحدیث: ۴۶۱/۶)"}],[9418,"§۱۰۸۰۸ ۔ اسماء انصاریہ\nمسعود بن حکم کی والدہ۔ ابن سکن رحمہ اللہ کہتے ہیں کہ ان کا نام اسماء ہے۔ ابن سکن کے علاوہ علماء کہتے ہیں کہ ان کا نام حبیبہ بنت شریق ہے، کنیتوں میں آ رہا ہے۔"],[9419,"§۱۰۸۰۹ ۔ اسیرہ\n(1) (تصغیر سے) انصاریہ۔ بعض یسیرہ کہتے ہیں۔ ابو عمر(2) نے ان کا مختلف ذکر کیا ہے۔ حرف “یاء” میں دوبارہ ان کا ذکر کیا ہے۔ ابن اثیر اور ذہبی رحمہما اللہ نے اس پر تنبیہ نہیں کی کہ دونوں ایک عورت کے نام ہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۱۲) تجرید (۲۴۵/۲)\n(2) الاستيعاب (۱۷۸۸/۴)"}],[9420,"§۱۰۸۱۰ ۔ اسیرہ بنت عمرو الجمحیہ\nام سعد، ابن سکن رحمہ اللہ نے ذکر کیا ہے، کنیتوں میں آ رہا ہے۔"],[9421,"§۱۰۸۱۱ ۔ امامہ بنت بشر\n(1) بن وقش انصاریہ، عباد بن بشر کی بہن ہیں۔ اسلام لائیں اور بیعت کی، یہ ابن سعد رحمہ اللہ کا بحوالہ واقدی رحمہ اللہ(2) قول ہے۔ فرماتے ہیں: ان کی والدہ فاطمہ بنت بشر بن عدی خزرجیہ ہیں، ان کے خاوند محمود بن مسلمہ ہیں، بعض لوگ کہتے ہیں کہ وہ علی بن اسد بن عبیدہ بن سعید کی والدہ ہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۱۳) تجرید (۲۴۶/۲)\n(2) الطبقات الکبریٰ (۲۳۶/۸)"}],[9422,"§۱۰۸۱۲ ۔ امامہ بنت حارث\nبن عوف، بعض نے کہا ہے کہ وہ برصا ہیں جو شبیب بن برصاء کی والدہ ہیں اور بعض نے کہا ہے کہ ان کا نام قرصافہ ہے۔"],[9423,"§۱۰۸۱۳ ۔ امامہ بنت حمزہ\n(1) بن عبدالمطلب ہاشمیہ، ابو جعفر بن حبیب نے کتاب المخبر میں لکھا ہے: جب رسول اللہ صلی اللہ علیہ وسلم عمرہ سے واپس آئے تو اپنے ساتھ امامہ بنت حمزہ بن عبدالمطلب کو بھی لے لیا، جب مذکورہ امامہ آ گئیں تو اپنے والد کی قبر کے بارے میں پوچھنے لگیں، حسان بن ثابت رضی اللہ عنہ کو اطلاع ملی تو کہا: “وہ ایک بہادر، شریف النسل سردار کے بارے میں پوچھتی ہے جو جنگ کے موقع پر صبح کے وقت حملہ کرنے والا جرات مند انسان تھا۔ میں نے اس سے کہا: اے امامہ! شہادت راحت اور رب غفور کی رضا مندی ہے، اسے مخلوق کے پروردگار، عرش والے نے ایسی جنت کی طرف بلایا ہے جس میں رضا مندی اور خوشی ہے۔” ایسا ہی ابن کلبی رحمہ اللہ نے ان کا نام امامہ لیا ہے۔ جبکہ واقدی رحمہ اللہ نے عمارہ(2) بتایا ہے۔ صحیحین میں براء کی حدیث سے ان کا ذکر ثابت ہے۔ چنانچہ عمرۃ القضاء کے قصے میں ذکر کرتے ہیں۔ جب یہ لوگ نکلے تو سیدنا حمزہ رضی اللہ عنہ کی بیٹی “اے میرے چچا زاد!” پکارتی ہوئی ان کے پیچھے ہوئی۔ سیدنا علی رضی اللہ عنہ نے سیدہ فاطمہ رضی اللہ عنہا سے کہا: اپنے والد کے چچا کی بیٹی کو لے لو، پھر ان کے بارے میں سیدنا علی رضی اللہ عنہ، جعفر بن ابی طالب اور زید بن حارثہ کا نزاع ہوا۔ (الحدیث) اس میں سیدنا جعفر رضی اللہ عنہ کا ارشاد ہے: (یا رسول اللہ صلی اللہ علیہ وسلم) میرے پاس اس کی خالہ ہے، اور نبی علیہ السلام کا ارشاد: خالہ ماں کے درجے میں ہے: اور ان کی والدہ کا نام سلمیٰ بنت عمیس تھا، اور ان کی بہن اسماء بنت عمیس جعفر بن ابی طالب کی اہلیہ تھیں۔ اور ابن سکن رحمہ اللہ نے یہ واقعہ ابو اسحاق رحمہ اللہ کی سند سے نقل کیا ہے۔ انہوں نے ہبیرہ بن مریم اور ہانی بن ہانی سے اور ان سب نے علی رضی اللہ عنہ سے روایت کیا ہے۔ انہوں نے عمرۃ القضاء کا قصہ ذکر کیا ہے۔ فرماتے ہیں: دختر حمزہ رضی اللہ عنہ ان کے پیچھے چل پڑیں۔ تو سیدنا علی رضی اللہ عنہ نے سیدہ فاطمہ رضی اللہ عنہا سے فرمایا: اپنے والد کے چچا کی بیٹی سنبھال لو۔ (الحدیث) خطیب رحمہ اللہ نے بھی “مبہمات” میں ذکر کیا ہے کہ ان کا نام امامہ تھا، البتہ یہ اضافہ کیا ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم نے سلمہ بن ام سلمہ رضی اللہ عنہا سے ان کی شادی کر دی تو فرمایا: کیا میں نے سلمہ کو بدلہ دے دیا؟ جس کی وجہ یہ ہے کہ سلمہ ہی نے ام سلمہ رضی اللہ عنہا کی شادی رسول اللہ صلی اللہ علیہ وسلم سے کی تھی۔ ذیل میں ابو موسیٰ نے صرف خطیب کی طرف سے اسے نقل کیا ہے۔ سلمہ کے سوانح میں سلمہ سے ان کی شادی کا تذکرہ ہو چکا ہے۔ لیکن اس روایت میں ان کا نام نہیں لیا گیا۔ ابن السکن نے روایت کیا ہے کہ بقول بعض ان کا نام فاطمہ ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۱۵) تجرید (۲۴۶/۲)\n(2) الطبقات الکبریٰ (۱۵۸/۸)"}],[9424,"§۱۰۸۱۴ ۔ امامہ بنت خدیج الانصاری\nرافع بن خدیج کی ہمشیرہ، اسلام لانے کے بعد بیعت رسول صلی اللہ علیہ وسلم سے سرفراز ہوئیں اور اسید بن ظہیر سے شادی ہوئی جن سے ثابت، محمد، ام کلثوم اور ام الحسن پیدا ہوئیں۔ ابن سعد(1) نے ان کا ذکر کیا کہ ان کی والدہ حلیمہ بنت عروہ بن مسعود بن عامر بیاضیہ ہیں۔","",{"fn":"(1) الطبقات الکبریٰ (۲۳۹/۸)"}],[9425,"§۱۰۸۱۵ ۔ امامہ بنت ربیعہ\nبن حارث بن عبدالمطلب بن ہاشم، امیمہ میں تذکرہ ہوگا۔"],[9426,"§۱۰۸۱۶ ۔ امامہ بنت سفیان\nامیمہ میں ذکر ہوگا۔"],[9427,"§۱۰۸۱۷ ۔ امامہ بنت سماک\n(1) بن عتیک الاوسیہ الاشہلیہ، حارث بن اوس بن معاذ کی والدہ محترمہ، ابن الاثیر نے بحوالہ ابن حبیب اپنے استدراک میں ان کا تذکرہ کیا ہے۔ ابن سعد رحمہ اللہ(2) لکھتے ہیں: ام حارث وہ ہیں جن کی بہن ہند بنت سماک ہیں۔ رہی امامہ تو وہ شریک بن انس بن رافع بن امرئ القیس کی اہلیہ ہیں جن کے ہاں عبد اللہ، ام صحر، ام سلیمان اور حبیبہ پیدا ہوئے۔ راوی کہتے ہیں کہ وہ اسلام لائیں اور بیعت کی۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۱۶) تجرید اسماء الصحابہ (۲۴۶/۲)\n(2) الطبقات الکبریٰ (۲۳۱/۸)"}],[9428,"§۱۰۸۱۸ ۔ امامہ بنت الصامت الانصاریہ\n(1) عبادہ بن صامت کی بہن ہیں۔ اسلام لائیں اور بیعت کی، یہ محمد بن سعد(2) کا قول ہے۔","",{"fn":"(1) تجرید اسماء الصحابہ (۲۴۶/۲)\n(2) الطبقات الکبریٰ (۲۷۵/۸)"}],[9429,"§۱۰۸۱۹ ۔ امامہ بنت ابی العاص\n(1) بن ربیع بن عبد العزیٰ بن عبد شمس بن عبد مناف العبشمیہ۔ رسول اللہ صلی اللہ علیہ وسلم کی صاحبزادی سیدہ زینب رضی اللہ عنہا کی بیٹی ہیں۔ حضرت زبیر رحمہ اللہ نے کتاب النسب میں لکھا ہے کہ سیدہ زینب رضی اللہ عنہا سیدنا ابوالعاص کی زوجیت میں تھیں، جن سے امامہ اور علی ہوئے۔ صحیحین کی حدیث ابو قتادہ(2) میں ان کا ذکر ثابت ہے۔ آپ صلی اللہ علیہ وسلم سیدہ امامہ بنت زینب رضی اللہ عنہا کو اپنے کندھے پر اٹھا جب سجدہ کرتے تو انہیں اتار دیتے اور جب قیام کرتے تو انہیں اٹھا لیتے۔ بخاری، مسلم دونوں نے اسے مالک کی روایت سے لیا ہے۔ جو انہوں نے عامر بن عبد اللہ بن زبیر سے لی ہے۔ ابن سعد رحمہ اللہ(3) نے اسے لیث کی روایت سے نقل کیا ہے، انہوں نے سعید المقبری اور انہوں نے عمرو بن سلیم سے نقل کیا انہوں نے ابو قتادہ سے فرماتے ہوئے سنا، ہم رسول اللہ صلی اللہ علیہ وسلم کے دروازے پر تھے۔ جب آپ صلی اللہ علیہ وسلم امامہ بنت ابوالعاص بن اکو اٹھائے ہوئے باہر تشریف لائے، اور ان کی والدہ رسول اللہ صلی اللہ علیہ وسلم کی صاحبزادی سیدہ زینب رضی اللہ عنہا تھیں۔ سیدہ امامہ اس چھوٹی بچی تھیں۔ آپ صلی اللہ علیہ وسلم نے نماز ادا فرمائی اور وہ آپ صلی اللہ علیہ وسلم کے کندھے پر ہوتیں جب آپ صلی اللہ علیہ وسلم قیام فرماتے، آپ صلی اللہ علیہ وسلم اٹھا کر نماز ادا فرماتے۔ حماد بن سلمہ کی سند سے روایت ہے، انہوں نے علی بن زید سے، انہوں نے ام محمد اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے نقل کیا کہ رسول اللہ صلی اللہ علیہ وسلم کو ہدیہ دیا گیا جس میں سفید اور سیاہ مہروں کا ہار بھی تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “میں اسے اپنے گھر میں سے سب سے محبوب کو دوں گا۔” عورتیں(4) کہنے لگیں: آپ اسے ابو قحافہ کی بیٹی کو دیں گے۔ رسول اللہ صلی اللہ علیہ وسلم نے امامہ بنت زینب کو بلایا اور ان کے گلے میں ڈال دیا۔ ابن سعد نے اسے حماد بن زید کی روایت سے نقل کیا ہے۔ انہوں نے علی بن زید سے مرسل روایت کیا ہے۔ فرماتے ہیں اس روایت میں ہے: تم میں سے جو زیادہ رشتہ دار ہے، یہ ہار میں اسے دوں گا۔ اسی روایت میں ہے، پھر آپ صلی اللہ علیہ وسلم نے ناص کی بیٹی جو سیدہ زینب رضی اللہ عنہا سے تھی اسے بلایا اور اپنے ہاتھ سے وہ ہار ان کے گلے میں باندھا، البتہ یہ اضافہ کیا ہے ان کی پر آنکھ کا میل تھا آپ صلی اللہ علیہ وسلم نے اسے اپنے ہاتھ سے صاف کر دیا۔ امام احمد رحمہ اللہ نے ابن اسحاق کے طریق سے بحوالہ یحییٰ بن عباد بن عبداللہ بن زبیر، ان کے والد، سیدہ عائشہ رضی اللہ عنہا سے نقل کیا ہے کہ نجاشی نے نبی کریم صلی اللہ علیہ وسلم کی طرف زیور ہدیہ بھیجا، اس میں سونے کی انگوٹھی تھی، اس کا نگینہ حبشہ کا تھا۔ آپ صلی اللہ علیہ وسلم نے وہ امامہ کو عطا کی۔ ابو عمر رحمہ اللہ(5) فرماتے ہیں: ان سے علی بن ابی طالب نے فاطمہ رضی اللہ عنہا کے بعد نکاح کیا، اس کے بعد زبیر بن عوام شادی کرائی، ان کے والد نے ان کے متعلق زبیر کو نکاح کی وصیت کی تھی، جب سیدنا علی رضی اللہ عنہ شہید ہوئے اور امامہ ان سے نا امید ہو گئیں تو ام الہیثم نخعیہ نے کہا: “میری مینڈھیاں سفید اور میرے گھٹنے امامہ نے اس وقت ناکارہ کر دیئے جب (اپنے) جوڑے سے جدا ہوئی۔ وہ اپنی ضرورت کے لیے اس کے ارد گرد چکر لگاتی ہے اور جب نا امید ہوئی تو آواز بلند کر دی۔” فرمایا: جب سیدنا علی رضی اللہ عنہ نے مغیرہ بن نوفل بن الحارث کو حکم دیا تھا کہ وہ امامہ بنت ابی العاص سے نکاح کر لیں، پھر سے مغیرہ نے نکاح کر لیا، جس سے بیٹی پیدا ہوئے، اسی سے ان کی کنیت ہے، وہ مغیرہ کے پاس وفات پا گئیں، بعض نے کہا ہے کہ ان کی سیدنا علی و مغیرہ سے کوئی اولاد نہ ہوئی۔ زبیر کہتے ہیں کہ زینب رضی اللہ عنہا کی اولاد میں سے کوئی زندہ نہ رہا۔ عمر بن شبہ فرماتے ہیں کہ ہم سے علی بن محمد النوفلی نے روایت کیا ہے، انہوں نے اپنے باپ سے اور انہوں نے اپنے گھر والوں سے روایت کیا ہے کہ سیدنا علی رضی اللہ عنہ کا جب وفات کا وقت قریب آیا تو انہوں نے امامہ بنت العاص سے فرمایا: مجھے خوف ہے کہ تمہیں میری موت کے بعد یہ زور آور یعنی معاویہ نکاح کا پیغام دے گا، اگر تم نکاح کرنا چاہو میں اس بات پر راضی ہوں کہ مغیرہ بن نوفل سے نکاح کرو۔ جب ان کی عدت پوری ہو گئی تو معاویہ نے مروان کی طرف لکھا کہ وہ ان کی طرف سے انہیں (امامہ) نکاح کا پیغام دیں، اور ایک لاکھ دینار کی منگنی بھیجنی۔ تو انہوں نے مغیرہ کی طرف پیغام بھیجا کہ اس نے مجھے منگنی بھیجی ہے۔ اگر تمہیں ہماری ضرورت ہو تو رُخ کرو۔ تو انہوں نے حسن رضی اللہ عنہ کی طرف ان سے نکاح کا پیغام بھیجا۔ انہوں نے ان کا نکاح کر دیا۔ میں کہتا ہوں: نوفلی بہت ضعیف ہے۔ اس کی سند منقطع ہے، اور راوی اس میں مجہول ہے۔ لیکن ابو عمر فرماتے ہیں: ہشیم، و داؤد بن ابی ہند سے وہ شعبی سے روایت کرتے ہیں، فرمایا: امامہ علی کی زوجیت میں تھیں، اور اسی مفہوم کی حدیث ذکر کی جو گزر چکی ہے۔ اور ابن سعد رحمہ اللہ نے واقدی سے اسی طرح حدیث روایت کی ہے۔ ابن سعد فرماتے ہیں: ہمیں ابن ابی فدیک نے بحوالہ ابن ابی ذئب خبر دی ہے کہ امامہ بنت ابو العاص نے مغیرہ بن نوفل سے کہا، معاویہ نے مجھے نکاح کا پیغام دیا ہے۔ انہوں نے کہا: کیا تم جگر کھانے والی کے بیٹے سے شادی کرو گی؟ اگر تم پیغام نکاح کو میرے لیے کر دو۔ کہنے لگی: جی ہاں! انہوں نے کہا میں نے تم سے نکاح کیا۔ ابن ابی ذئب کہتے ہیں: ان کا نکاح ہو گیا۔ دار قطنی رحمہ اللہ نے کتاب الاخوہ میں لکھا ہے ان سے سیدنا علی رضی اللہ عنہ کے بعد مغیرہ بن نوفل نے نکاح کیا، بعض نے کہا ہے بلکہ ان سے بعد میں ابو الہیاج بن ابو سفیان بن حارث بن عبدالمطلب نے نکاح کیا۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۱۷) تجرید (۲۴۶/۲)\n(2) بخاری کتاب الادب (الحدیث: ۵۹۹۶) مسلم (الحدیث: ۱۲۱۳)\n(3) الطبقات الکبریٰ (۱۶۸/۸)\n(4) مسند احمد (الحدیث: ۱۰۱/۶)\n(5) الاستيعاب (۱۷۸۸/۴)"}],[9430,"§۱۰۸۲۰ ۔ امامہ بنت عبدالمطلب\n(1) ان کا ایک ضعیف حدیث میں ذکر ملتا ہے۔ اسی طرح تجرید(2) میں ہے۔ اور یہ امیمہ ہیں جن کا ذکر آگے آ رہا ہے۔ اپنے والد کے دادا کی طرف منسوب ہیں، ان کا سلسلہ نسب یوں ہے: بنت ربیعہ بن حارث بن عبدالمطلب۔ ابن فتحون لکھتے ہیں کہ ابو عمر نے عباد بن شیبان اسلام کے حالات میں ذکر کیا ہے کہ امامہ بنت عبدالمطلب ہیں۔ میں کہتا ہوں: ابن عبدالبر کے الفاظ ہیں: عباد بن شیبان نے کہا ہے کہ میں نے امامہ بنت عبدالمطلب کے لیے نبی کریم صلی اللہ علیہ وسلم کی طرف پیغام نکاح بھیجا کہ آپ نے مجھ سے نکاح کر دیا، آپ صلی اللہ علیہ وسلم نے گواہ قائم نہیں کیے۔ بغوی نے اس کو لیا ہے، انہوں نے اس روایت کو حدیث عباد بن شیبان سے نقل کیا ہے۔ ابن فتحون کہتے ہیں کہ ابو عمر نے ان کا ذکر نہیں کیا۔ اگر یہ روایت صحیح ہے تو ابو عمر کا ان کے ذکر سے تغافل برتنا انتہائی تعجب خیز ہے۔","",{"fn":"(1) تجرید اسماء الصحابہ (۲۴۶/۲)\n(2) التجريد (۱۸۰)"}],[9431,"§۱۰۸۲۱ ۔ امامہ بنت عثمان\n(1) بن خالد الانصاریہ زرقیہ، ابن سعد نے ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید اسماء الصحابہ (۲۴۶/۲)"}],[9432,"§۱۰۸۲۲ ۔ امامہ بنت عصام\n(1) بن عامر انصاریہ البیاضیہ۔ ابن سعد رحمہ اللہ(2) نے فرمایا: اسلام لائیں اور بیعت کی۔","",{"fn":"(1) تجرید اسماء الصحابہ (۲۴۶/۲)\n(2) الطبقات الکبریٰ (۲۸۳/۸)"}],[9433,"§۱۰۸۲۳ ۔ امامہ بنت قرط\n(1) بن خنساء بن سنان بن عبید بن عدی بن غنم بن کعب بن سلمہ انصاریہ السلمیہ۔ ابن سعد رحمہ اللہ(2) نے فرمایا: وہ یزید بن نیلی کی زوجہ ہیں، ان کے قبیلے سے تھیں، اسلام لائیں اور بیعت کی۔","",{"fn":"(1) تجرید اسماء الصحابہ (۲۴۶/۲)\n(2) الطبقات الکبریٰ (۲۹۴/۸)"}],[9434,"§۱۰۸۲۴ ۔ امامہ بنت قریبہ\n(1) بن عجلان بن غنم بن عامر بن بیاضہ انصاریہ بیاضیہ۔ ابن اثیر نے ان کا ذکر کیا ہے اور فرمایا کہ ابو عمر کی کتاب پر اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۱۹) تجرید (۲۴۶/۲)"}],[9435,"§۱۰۸۲۵ ۔ امامہ بنت محرث\n(1) بن زید بن ثعلبہ بن عبید بن عدی بن غنم بن کعب بن سلمہ، ابن سعد(2) نے ان کا ذکر کیا ہے۔ اور کہا ہے کہ ان کی والدہ سلمیٰ بنت ابی دحداحہ بن تمیم تھیں۔ ان سے ربیع بن طفیل بن مالک بن خنساء نے نکاح کیا۔ اس کے بعد ان سے ضحاک بن حارثہ بن ثعلبہ بن عبید نے نکاح کیا جو بنو سلمہ سے تھے، فرمایا: امامہ اسلام لائیں اور بیعت کی۔","",{"fn":"(1) تجرید اسماء الصحابہ (۲۴۶/۲)\n(2) الطبقات الکبریٰ (۲۹۵/۸)"}],[9436,"§۱۰۸۲۶ ۔ امامہ المریدیہ\n(1) ابن ہشام نے زیادات السیرۃ النبویہ(2) میں ان کا ذکر کیا ہے کہ انہوں نے عفک کے قصہ میں شعر کہا تھا، عفک عین پر زبر ہے اور فاء پر تخفیف ہے۔ یہ منافق تھا، اور اس کا نفاق ظاہر ہو چکا تھا۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: اس خبیث کے مقابلے میں میرا کون مددگار ہے؟ تو سالم بن عمیر نکلے جو بنی عمرو بن عوف سے تھے اور اسے قتل کر دیا، اس وقت امامہ مریدیہ نے یہ اشعار کہے: “تم اللہ کے دین اور احمد (صلی اللہ علیہ وسلم) کی تکذیب کرتے ہو، جس نے تجھے جنا اس کی زندگی کی قسم کیا ہی برا ہے جو جنا جائے گا، تجھے آخری دور میں حنیف نے نیزہ مارا ابو عفک بڑھاپے کی عمر میں اسے برداشت کر، ابن فتحون نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۲۰) تجرید (۲۴۶/۲)\n(2) السیرۃ النبویہ عن ابن اسحاق (۲۱۴/۴)"}],[9437,"§۱۰۸۲۷ ۔ امامہ غیر منسوبہ\nسنن سعید بن منصور کے آخر میں ان کی حدیث ہے۔ کتاب الکنی میں ابو الجندل کے حالات میں ان کا ذکر ہے۔"],[9438,"§۱۰۸۲۸ ۔ امامہ\n(1) فرقد المجلی کی والدہ ہیں، وہ اپنے بیٹے فرقد کو نبی کریم صلی اللہ علیہ وسلم کے پاس لے گئیں، ان کی زلفیں تھیں، آپ صلی اللہ علیہ وسلم نے ان پر ہاتھ پھیرا اور ان کے لیے برکت کی دعا کی۔ ابو عمر(2) نے ان کے والد کے حالات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۲۴۶/۲)\n(2) الاستيعاب (۱۲۵۹/۳)"}],[9439,"§۱۰۸۲۹ ۔ امۃ اللہ بنت عبد شمس\nبن عبد یالیل اللیثیہ عبداللہ بن ہاشم بن زہرہ قرشی تیمی کی والدہ ہے۔ خلیفہ بن خیاط نے ذکر کیا ہے وہ اپنے بیٹے کو جو اس وقت چھوٹا تھا نبی کریم صلی اللہ علیہ وسلم کے پاس لے گئیں تا کہ وہ آپ صلی اللہ علیہ وسلم سے بیعت کرے، اصل قصہ حاکم کی کتاب مستدرک میں ہے۔ لیکن صحیح بخاری میں ہے کہ ان کا نام زینب بنت حمید ہے۔"],[9440,"§۱۰۸۳۰ ۔ امۃ بنت ابی الحکم\nیا بنت حکم، دوسری قسم میں ان کا ذکر آئے گا۔"],[9441,"§۱۰۸۳۱ ۔ امۃ بنت خالد\n(1) بن سعید بن العاص بن امیہ بن عبد شمس، ان کی کنیت ام خالد ہے اور وہ اپنی کنیت سے مشہور ہیں۔ اپنے والد کے ساتھ حبشہ سے آئیں جنہوں نے اس کی طرف ہجرت کی تھی وہ ان کے ہاں امیمہ سے پیدا ہوئیں۔ اور بعض نے کہا کہ ہمینہ بنت خلف خزاعیہ سے ہوئیں۔ ابن سعد نے کہا ہے کہ خالد بن سعید نے حبشہ کی طرف ہجرت کی تھی اور ان کے ساتھ ان کی اہلیہ ہمینہ بنت خلف تھیں، وہاں ان کے ہاں امہ بنت خالد ہوئیں، اور وہ دو کشتیوں کے ذریعہ واپس ہوئے۔ اس وقت امہ بالغ اور عقلمند ہو چکی تھیں۔ پھر ایک سند جس میں واقدی ان سے روایت کرتے ہیں نقل کی ہے، فرماتی ہیں: میں نے سنا کہ نجاشی دونوں کشتیوں والوں سے کہہ رہے تھے، رسول اللہ صلی اللہ علیہ وسلم کو میری طرف سے سلام دینا۔ امہ فرماتی ہیں میں ان لوگوں میں سے تھی جنہوں نے نجاشی کی طرف سے رسول اللہ صلی اللہ علیہ وسلم کو سلام دیا تھا۔ میں کہتا ہوں: ان کا یہ قول کہ وہ حبشہ میں بالغ ہو گئی تھی، صحیح کی روایت کے اس قول سے رد ہوگا کہ میرے پاس اُم خالد کو لاؤ، چنانچہ مجھے اٹھا کر لایا گیا، تو آپ صلی اللہ علیہ وسلم نے مجھے چادر اوڑھا دی، پھر بھی انہوں نے نبی کریم صلی اللہ علیہ وسلم کی حدیث یاد رکھی ہے۔ ان سے سعید بن عمر اور اشدق بن سعید بن العاص اور وہ ان کے دادا کی چچا زاد تھی، اور موسیٰ اور ابراہیم جو عقبہ مدنیان کے بیٹے تھے، ان سب نے روایت کی ہے۔ ان سے زبیر بن عوام نے نکاح کیا وہ ان کے بیٹوں خالد اور عمرو کی ام ولد تھیں۔ ان کی حدیث صحیح بخاری(2) میں ہے کہ آپ صلی اللہ علیہ وسلم نے جب انہیں حلہ پہنایا تو فرمایا: کہ سنیہ یعنی اچھا اور ان کے لیے فرمایا: پرانا کرو اور بوسیدہ کرو، یہاں تک کہ یاد کیا جائے، یعنی طویل زمانے تک یاد کیا جائے۔ صحیح بخاری کے باب الجہاد کے بعض طرق میں ہے، ابو عبداللہ نے فرمایا: کوئی خاتون ان سے زیادہ زندہ نہ رہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۲۴) تجرید (۲۴۷/۲)\n(2) بخاری، کتاب اللباس، کتاب الادب (۵۸۲۳، ۵۹۹۳)"}],[9442,"§۱۰۸۳۲ ۔ امۃ بنت خلید\nبن عدی بن عمرو بن مالک بن عجلان انصاریہ، ابن اثیر نے ان کا اسی طرح ذکر کیا ہے۔ اور ذہبی رحمہ اللہ(1) نے اس سلسلے میں ان کی خوشہ چینی کی ہے اور فرمایا کہ ان کے حالات نا معلوم ہیں۔","",{"fn":"(1) تجرید (۱۸۱)"}],[9443,"§۱۰۸۳۳ ۔ امۃ بنت سعید\nبن ابی سرح، عبداللہ جو کہ امیر مصر تھے، ان کی بہن ہیں، عمر بن شبہ کی کتاب اخبار المدینہ میں ان کا ذکر ہے۔ یہ ان لوگوں میں سے تھیں جنہوں نے مدینہ میں حویلی بنائی تھی۔"],[9444,"§۱۰۸۳۴ ۔ امۃ بنت ابی الصلت\nاو ابن ابی الصلت۔ دوسری قسم میں ان کا ذکر آئے گا۔"],[9445,"§۱۰۸۳۵ ۔ امۃ بنت نعیم النحام\nیہ وہ خاتون ہیں جن کے لیے ابن عمر رضی اللہ عنہ نے نعیم کی طرف پیغام بھیجا تھا، انہوں نے ان کا نکاح نعمان بن نصلہ سے کر دیا جو ان کی پرورش میں تھے، زبیر نے کتاب النسب میں ان کا نام بتایا ہے۔"],[9446,"§۱۰۸۳۶ ۔ امۃ الفارسیہ\n(1) ابن مندہ نے تاریخ اصبہان میں مبارک بن سعید ثوری، عبید مکتب کی سند سے روایت کیا ہے کہ سلمان فارسی نے فرمایا کہ جب میں مدینہ آیا تو ایک اصبہانی عورت کو دیکھا جو مجھ سے پہلے اسلام لا چکی تھی۔ میں نے اس سے رسول اللہ صلی اللہ علیہ وسلم کی تعلیم کے بارے میں پوچھا۔ اس نے مجھے آپ صلی اللہ علیہ وسلم کا پتہ بتایا۔ ابو موسیٰ کہتے ہیں کہ اسے عبداللہ بن عبد العزیز نے ابو طفیل سے انہوں نے اسی مفہوم کو سلمان سے روایت کیا۔ انہوں نے مدینہ کے بجائے مکہ لکھا ہے، اور عورت کا نام ذکر نہیں کیا۔ پہلی روایت اولیٰ ہے۔ ابو طفیل سے بھی اسی طرح روایت کیا گیا ہے کہ انہوں نے مدینہ بتایا۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۲۶) تجرید (۲۴۷/۲)"}],[9447,"§۱۰۸۳۷ ۔ امیمہ بنت بجاد\nعبداللہ بن عمیر بن حارثہ بن سعد بن تیم بن مرہ القرشیہ التیمیمیہ۔ بعض نے کہا: امیمہ بنت عبداللہ بن نجاء... الخ۔ امیمہ بنت رقیقہ کے حالات میں ان کا ذکر آئے گا۔"],[9448,"§۱۰۸۳۸ ۔ امیمہ بنت بشر\n(1) بنی عمرو بن عوف سے تھیں، حسان بن دحداحہ کی زوجہ تھیں، اس وقت وہ کافر تھے، تو وہ ان کو چھوڑ کر ہجرت کر گئیں، نبی کریم صلی اللہ علیہ وسلم نے ان کا نکاح سہل بن حنیف سے کر دیا جس سے عبداللہ پیدا ہوئے، انہی کے بارے میں یہ آیت نازل ہوئی: “اے ایمان والو! جب تمہارے پاس مومنات مہاجرات آئیں....” (الآیۃ) ابن وہب(2) نے ابن لہیعہ سے اور انہوں نے یزید بن ابی حبیب سے ذکر کیا ہے کہ انہیں یہ بات پہنچی ہے۔ ابن مندہ نے اسے مسند روایت کیا ہے اور ابن اثیر نے اسے بعید سمجھا ہے کہ بنو عمرو بن عوف اہل مدینہ میں سے تھے، اور یہ آیت مہاجرات کے بارے میں نازل ہوئی۔ شاید ان کے شوہر انصار میں سے نہیں تھے۔ پھر وہ مکہ منتقل ہو گئے، ان کا حکم مہاجرات کے حکم کی طرح ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۲۷) تجرید (۲۴۷/۲)\n(2) سورۃ الممتحنۃ الآیۃ (۱۰)"}],[9449,"§۱۰۸۳۹ ۔ امیمہ بنت بشیر\n(1) بن سعد انصاریہ، خزرجیہ، نعمان بن بشیر کی سگی بہن ہیں، ابن سعد نے ان کا ذکر کیا ہے، اور فرمایا: اسلام لائیں اور بیعت کی، انہیں اُبَیَّہ کہا جاتا تھا، ب اور شد سے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۲۸) تجرید (۲۴۷/۲)"}],[9450,"§۱۰۸۴۰ ۔ امیمہ بنت الحارث\n(1) عبدالرحمن بن زبیر کی زوجہ تھیں، انہوں نے تین طلاقیں دیں، پھر ان سے رفاعہ نے نکاح کیا، پھر رفاعہ نے طلاق دی تو انہوں نے کہا: اے رسول اللہ صلی اللہ علیہ وسلم رفاعہ نے مجھے طلاق دے دی ہے، کیا میں عبدالرحمن سے نکاح کر لوں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: کیا وہ تم سے ہم بستر ہوا ہے۔ کہنے لگیں: اس کا عضو کپڑے کے پلو کی طرح ہے۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: یہاں تک کہ تم اس کا مزہ چکھ لو اور وہ تمہارا مزا چکھ لے۔(2) ابن مندہ نے اسے محمد بن مروان السدی کی سند سے نقل کیا ہے، جس میں انہوں نے کلبی، ابو صالح اور ابن عباس سے روایت کی ہے۔ میں کہتا ہوں: محمد بن مروان نے اس کو کذاب قرار دیا ہے اور اس کے شیخ نے اس کے کذب کا اعتراف کیا ہے۔ اصل قصہ صحیحین میں ہے لیکن اس کا سیاق اور ہے۔ ان میں خاتون کا نام نہیں ہے اور عنقریب آئے گا کہ ان کا نام سہیمہ ہے اور بعض نے کہا: اس کے علاوہ ہیں۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۲۹) تجرید (۲۴۷/۲)\n(2) بخاری کتاب الطلاق (الحدیث: ۵۲۶۵) ابوداؤد (الحدیث: ۴۴۱۹) احمد (الحدیث: ۲۱۷/۵)"}],[9451,"§۱۰۸۴۱ ۔ امیمہ بنت ابی حثمہ\n(1) اور ان کا نام عبد اللہ بن ساعدہ بن عامر بن عدی بن جشم بن مجدعہ بن حارثہ الساعدیہ ہے، جمیلہ اور عمیرہ کی بہن ہیں۔ ابن سعد(2) نے صحابیات میں ان کا ذکر کیا ہے۔ اور فرمایا کہ ان کی والدہ حجتہ بنت عمیر بن عقبہ بن عمرو بن عدی بن زید بن جشم ہیں۔ کہتے ہیں کہ ان سے ہلال بن حارث بن ربیعہ بن منقذ نے نکاح کیا، اس کے بعد ابو سندر بن حصین بن بجاد نے نکاح کیا، اسلام لائیں اور بیعت کی۔","",{"fn":"(1) تجرید (۲۴۷/۲)\n(2) الطبقات الکبریٰ (۲۴۱/۸)"}],[9452,"§۱۰۸۴۲ ۔ امیمہ بنت خلف\n(1) بن اسعد بن عامر بن سبیع خزاعیہ، طلحہ الطلحات جو مشہور فیاض ہیں، ان کی پھوپھی ہیں۔ خالد بن سعید بن العاص کی زوجہ تھیں۔ اسلام کے ابتدائی دور میں ایمان لائیں اور ان کے ساتھ حبشہ ہجرت کی، اور بعض نے کہا کہ ان کا نام امینہ، میم کے بجائے نون کے ساتھ ہے۔ بعض نے کہا: ہمینہ الف کے بجائے ہاء کے ساتھ ہے۔ جس سے اُم خالد پیدا ہوئیں جو خالد کی بیٹی تھیں، اس کا نام آمنہ رکھا جو اپنی کنیت(2) کے ساتھ مشہور ہو گئیں۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۳۰) تجرید (۲۴۷/۲)\n(2) ابن اسحاق فی السیر والمغازی (۱۴۴)"}],[9453,"§۱۰۸۴۳ ۔ امیمہ بنت الخطاب\nسیدنا عمر رضی اللہ عنہ کی بہن ہیں، ان کا ذکر فاطمہ کے حالات میں آئے گا۔"],[9454,"§۱۰۸۴۴ ۔ امیمہ بنت ابی الخیار\n(1) مطیع بن اسود عدوی کی زوجہ ہیں، تجرید(2) میں ان کا ذکر ہے۔","",{"fn":"(1) تجرید اسماء الصحابہ (۲۴۷/۲)\n(2) ذہبی فی التجريد (۱۸۱)"}],[9455,"§۱۰۸۴۵ ۔ امیمہ بنت ربیعہ\n(1) بن حارث بن عبدالمطلب، بعض نے کہا کہ ان کا نام امامہ ہے۔ گویا جس نے انہیں ان کا یہ نام تصغیر قرار دیا انہیں یہ لقب دے دیا۔ تجرید میں ہے انہیں شرف صحابیت(2) حاصل ہے۔","",{"fn":"(1) تجرید (۲۴۷/۲)\n(2) التجريد (۱۸۱)"}],[9456,"§۱۰۸۴۶ ۔ امیمہ بنت رقیقہ\n(1) دو قافوں کے ساتھ، تصغیر ہے۔ وہ بنت بجاد ہیں جن کا ذکر پہلے گزر چکا ہے۔ اور ان کی والدہ رقیقہ بنت خویلد بن اسد ہیں جو خدیجہ رضی اللہ عنہا کی بہن ہیں۔ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی ہے اور ان سے محمد بن المنکدر نے اور ان کی بیٹی حکیمہ بنت رقیقہ نے روایت کی ہے۔ حکیمہ تصغیر کے ساتھ ہے۔ ابو عمر رحمہ اللہ(2) فرماتے ہیں کہ وہ بیعت کرنے والی صحابیات میں شامل تھیں، اور فرمایا وہ فاطمہ الزہراء کی خالہ ہیں۔ ابن الاثیر(3) نے درج کیا ہے کہ وہ ان کی خالہ کی بیٹی ہیں، کیونکہ خویلد خدیجہ اور رقیقہ کے والد ہیں، امیمہ کے والد نہیں۔ میں کہتا ہوں: یہ اس شخص کے قول سے صحیح ہے جس نے کہا کہ یہ رقیقہ بنت خویلد بن اسد بن عبد العزیٰ ہیں، ابن سعد(4) نے کہا اور مصعب زبیری نے کہا کہ وہ رقیقہ بنت اسد بن عبد العزیٰ ہیں، اسی وجہ سے مستغفری نے کہا کہ وہ سیدہ خدیجہ رضی اللہ عنہا بنت خویلد کی پھوپھی ہیں۔ ان کی حدیث ترمذی(5) وغیرہ میں ابن عیینہ کے طریق سے ہے جو انہوں نے محمد بن منکدر سے روایت کی کہ انہوں نے امیمہ بنت رقیقہ سے فرماتے ہوئے سنا: میں نے خواتین میں رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی آپ صلی اللہ علیہ وسلم نے ہم سے فرمایا: “جتنی تم استطاعت اور طاقت رکھتی ہو”۔ ہم نے کہا: اللہ اور اس کا رسول صلی اللہ علیہ وسلم ہم پر ہماری جانوں سے زیادہ مہربان ہیں۔ مالک نے اسے ابن منکدر سے طویل نقل کیا ہے۔ ابن حبان نے اپنے طریق سے اس کو صحیح قرار دیا ہے۔ اور اس کے الفاظ یوں ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس، خواتین کے ساتھ، بیعت کرنے کے لیے آئی۔ ہم نے کہا: “اے اللہ کے رسول صلی اللہ علیہ وسلم کیا ہم آپ صلی اللہ علیہ وسلم سے اس بات پر بیعت کرتی ہیں کہ ہم اللہ کے ساتھ کسی کو شریک نہ ٹھہرائیں گی، نہ چوری کریں گی، نہ زنا کریں گی، نہ اپنی اولادوں کو قتل کریں گی، نہ اپنے ہاتھوں اور پاؤں پر بہتان گھڑیں گی، اور بھلائی کے کاموں میں آپ صلی اللہ علیہ وسلم کی نافرمانی نہ کریں گی۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “جتنی تم استطاعت اور طاقت رکھو”۔ ہم نے کہا: اللہ اور اس کا رسول صلی اللہ علیہ وسلم ہم پر ہماری جانوں سے زیادہ مہربان ہیں، یا رسول اللہ! ہاتھ بڑھائیے ہم آپ سے بیعت کریں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “میں عورتوں سے مصافحہ نہیں کرتا، میری بات سو عورتوں کے لیے ایسی ہے جیسے ایک عورت کے لیے۔”(6) اسے دار قطنی(7) نے دوسری سند سے نقل کیا ہے۔ بحوالہ ابن منکدر، ابن سعد(8) نے فرمایا: امیمہ نے قبیلے سے باہر حبیب بن کعب بن عتیر ثقفی سے شادی کی، جس سے اولاد ہوئی۔ ابو احمد عسال فرماتے ہیں: مجھے معلوم نہیں کہ ان سے ابن منکدر کے علاوہ کسی نے روایت کی ہو۔ مصعب زبیری فرماتے ہیں کہ وہ محمد بن منکدر کی پھوپھی ہیں، گویا ان کی مراد یہ ہے کہ وہ ان کے خاندان سے ہیں۔ کہتے ہیں کہ معاویہ نے انہیں شام منتقل کیا اور ان کے لیے گھر بنایا، زبیر بن بکار نے بھی یہی کہا ہے۔ اور یہ اضافہ کیا ہے کہ ان کا دمشق میں گھر اور غلام تھے۔ پھر ثابت بن عبداللہ بن زبیر کے طریق سے مسند نقل کیا ہے کہ رقیقہ کی بیٹی، معاویہ کے پاس اس وقت آئیں جب وہ مرض وفات میں تھے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۳۲) تجرید (۲۴۸/۲)\n(2) الاستيعاب (۱۷۹۱/۴)\n(3) اسد الغابہ (۲۲۱/۵)\n(4) الطبقات الکبریٰ (۱۸۹/۸)\n(5) ترمذی (الحدیث: ۱۵۹۷)\n(6) ترمذی (الحدیث: ۱۵۹۷) نسائی (الحدیث: ۴۲۰۱) ابن ماجہ (الحدیث: ۲۸۷۴)\n(7) سنن دارقطنی الحدیث (۱۴۷/۴)\n(8) الطبقات الکبریٰ (۲۴۱/۸)"}],[9457,"§۱۰۸۴۷ ۔ امیمہ بنت رقیقہ\n(1) بنت ابی صیفی بن ہاشم بن عبد مناف۔ یہ مخرمہ بن نوفل کی ماں شریک بہن ہیں اور ان کی والدہ رقیقہ ہیں، جنہوں نے خواب دیکھا جب عبد المطلب نے پانی مانگا، ابو نعیم نے طبرانی(2) کی پیروی کرتے ہوئے اس روایت اور جو اس سے پہلے ہے ان کے درمیان فرق کیا ہے۔ اور ان کے حالات میں حدیث ابن جریج نقل کی ہے جو حکیمہ بنت امیمہ سے بحوالہ ان کے والد امیمہ بنت رقیقہ روایت ہے۔ فرماتی ہیں کہ نبی کریم صلی اللہ علیہ وسلم کے لیے لکڑی کا ایک برتن (Pat) تھا جس میں پیشاب کرتے تھے۔ اور فرمایا کہ(3) حکیمہ کے والد حکیم ہیں، اور حکیمہ سے ابن جریج کے علاوہ کسی نے روایت نہیں کیا۔ میں کہتا ہوں: عنقریب آئے گا کہ ان کے والد انصاری ہیں، اس سے ان کے قول کی تائید ہوتی ہے جس نے ان میں فرق کیا ہے اور ابن سکن نے انہیں ایک قرار دیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۳۳) تجرید (۲۴۸/۲)\n(2) المعجم الکبیر (۴۷۷/۲۴)\n(3) ابوداؤد (الحدیث: ۲۴)"}],[9458,"§۱۰۸۴۸ ۔ امیمہ بنت سفیان\n(1) بن وہب بن اشیم، بنو حارث بن عبد مناۃ بن کنانہ کنانیہ سے ہیں۔ ابو سفیان حرب کی زوجہ ہیں۔ فتح کے بعد اسلام لائیں اور بیعت کی۔ ابن سعد(2) نے اس کا ذکر کیا ہے اور فرمایا ہے کہ وہ ام عبداللہ ہیں فرماتے ہیں۔ بعض نے کہا کہ ان کا اسلام فتح کے بعد ہے۔","",{"fn":"(1) تجرید (۲۴۸/۲)\n(2) الطبقات الکبریٰ (۲۴۱/۸)"}],[9459,"§۱۰۸۴۹ ۔ امیمہ بنت ابی سفیان\nبن حرب بن امیہ، صفوان بن امیہ کی زوجہ ہیں، ان کا ذکر عاتکہ بنت ولید بن مغیرہ کے حالات میں آئے گا۔"],[9460,"§۱۰۸۵۰ ۔ امیمہ بنت شراحیل\nیہ نعمان بن شراحیل کی صاحبزادی ہیں، ان کا ذکر آگے آئے گا۔"],[9461,"§۱۰۸۵۱ ۔ امیمہ بنت صبیح\n(1) یا صفیح (با کے ساتھ یا “ف” کے ساتھ) ابن حارث، ابو ہریرہ رضی اللہ عنہ کی والدہ ہیں، ان کے نام میں اختلاف ہے، ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ وہ امیمہ کے بیٹے ہیں، طبرانی نے خواتین کے حالات میں لکھا ہے میمونہ بنت صبیح والدہ ابو ہریرہ رضی اللہ عنہ اور ان کے اسلام لانے کا قصہ بھی بیان کیا ہے، لیکن اس روایت میں ان کا نام نہیں لیا۔ رہے ان کے والد محمد بن قتیبہ، فرماتے ہیں اور سعید بن صبیح ابو ہریرہ رضی اللہ عنہ کے ماموں تھے، لوگوں میں مضبوط ترین آدمی تھے۔ ان کے امیمہ نام رکھنے کی وجہ ہم نے اسحاق بن ابراہیم بن شاذان کے رسالہ میں روایت کی ہے اور ابو موسیٰ نے اسے ذیل میں اپنی سند سے نقل کیا ہے، فرماتے ہیں: ہمیں سعد الصلت نے خبر دی، یحییٰ بن علاء نے حدیث بحوالہ ایوب، محمد بن سیرین بیان کی کہ سیدنا ابو ہریرہ رضی اللہ عنہ فرماتے ہیں کہ سیدنا عمر فاروق رضی اللہ عنہ نے انہیں عامل بنانے کے لیے بلایا، انہوں نے عامل بننے سے انکار کر دیا۔ تو انہوں نے فرمایا: کیا تم گورنری سے انکار کرتے ہو جبکہ ایسے شخص نے اس کا مطالبہ کیا ہے جو تم سے بہتر تھا، فرمایا: وہ کون ہے؟ انہوں نے فرمایا: یوسف بن یعقوب علیہ السلام۔ سیدنا ابو ہریرہ رضی اللہ عنہ نے فرمایا: یوسف نبی ہیں اور نبی کے بیٹے ہیں اور میں ابو ہریرہ، امیمہ کا بیٹا ہوں۔ میں تین اور دو سے ڈرتا ہوں۔ سیدنا عمر رضی اللہ عنہ نے فرمایا: تم نے پانچ کیوں نہیں کہا؟ فرمایا: میں بغیر علم کے کوئی بات کہنے سے ڈرتا ہوں یا ناحق فیصلہ کروں اور مجھے کوڑے لگائے جائیں۔ اور مجھے برا بھلا کہا جائے اور میرا مال چھین لیا جائے۔ میں کہتا ہوں: اس کی سند بہت ضعیف ہے، لیکن اسے عبد الرزاق نے معمر سے بحوالہ ایوب نقل کیا ہے، اس لیے قوی ہے۔ اور عمر رضی اللہ عنہ نے ابو ہریرہ رضی اللہ عنہ کو بحرین کا عامل بنایا ہے۔ رہا قصہ ام ابو ہریرہ رضی اللہ عنہا کے اسلام لانے کا تو احمد نے اسے اپنی مسند میں بحوالہ عبدالرحمن اور وہ ابن مہدی ہیں، انہوں نے عکرمہ بن عمار سے روایت کیا ہے۔ وہ فرماتے ہیں کہ مجھ سے ابو کثیر نے روایت کیا، اور وہ فرماتے ہیں کہ مجھ سے ابو ہریرہ رضی اللہ عنہ نے روایت کیا، فرماتے ہیں: اللہ تعالیٰ نے جو مومن بھی پیدا کیا ہے جو میرے بارے میں سنتا ہے، اور مجھے نہیں دیکھتا مجھ سے محبت کرتا ہے۔ میں نے کہا: اے ابو ہریرہ! آپ کو اس کا علم کیسے ہوا؟ فرمایا: میری والدہ مشرکہ تھیں اور میں انہیں اسلام کی دعوت دیتا تھا، تو وہ انکار کر دیتی تھیں، میں نے انہیں ایک دن دعوت دی۔ اور مسلم(2) نے یونس بن محمد کی سند سے بحوالہ عکرمہ بن عمار، ابو کثیر (جو یزید بن عبدالرحمن ہیں) روایت کیا ہے فرماتے ہیں: مجھ سے ابو ہریرہ رضی اللہ عنہ نے روایت کیا، فرمایا: میں اپنی والدہ کو اسلام کی طرف دعوت دیتا تھا اور وہ مشرکہ تھیں، میں نے انہیں ایک دن دعوت دی، انہوں نے مجھے رسول اللہ صلی اللہ علیہ وسلم کے متعلق ایسی بات کہی جسے میں نا پسند کرتا ہوں، پس میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور میں رو رہا تھا، میں نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم میں اپنی والدہ کو اسلام کی دعوت دیتا تھا، تو وہ انکار کر دیتی تھیں۔ میں نے آج انہیں دعوت دی تو انہوں نے آپ صلی اللہ علیہ وسلم کے بارے میں ایسی بات کہی جو میں ناپسند کرتا ہوں (یعنی برا بھلا کہا)۔ اللہ تعالیٰ سے دعا کیجئے کہ ام ابو ہریرہ کو ہدایت دے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “اے اللہ! ابو ہریرہ کی والدہ کو ہدایت دے۔” میں رسول اللہ صلی اللہ علیہ وسلم کی دعا سے خوش ہو کر نکلا، جب میں نے دروازے سے اندر جانے کا ارادہ کیا تو وہ بند تھا۔ جب میری ماں نے میرے قدموں کی آواز سنی تو فرمایا: ابو ہریرہ! ٹھہرے رہو، اور میں نے پانی گرنے کی آواز سنی۔ فرمایا: انہوں نے کپڑے پہنے اور جلدی سے چادر لی، اور دروازہ کھولا اور کہا: اے ابو ہریرہ! میں گواہی دیتی ہوں کہ اللہ کے سوا کوئی معبود نہیں اور محمد (صلی اللہ علیہ وسلم) اللہ کے رسول ہیں۔ فرماتے ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کی طرف گیا اور آپ صلی اللہ علیہ وسلم کو خبر دی، آپ صلی اللہ علیہ وسلم نے اللہ کی حمد بیان کی، اور اچھے کلمات کہے، ابو ہریرہ رضی اللہ عنہ کے حالات میں اس واقعہ کا کچھ حصہ گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۳۹) تجرید (۲۴۸/۲)\n(2) مسلم (الحدیث: ۶۳۴۶)"}],[9462,"§۱۰۸۵۲ ۔ امیمہ بنت عبداللہ\nبن بجاد بن عمیر بن الحارث بن خارجہ بن سعد بن تیم بن مرہ، یہ رقیقہ کی بیٹی ہیں، ان کے حالات گزر چکے ہیں۔ ابو علی بن سکن نے ان کا نسب بیان کیا ہے۔"],[9463,"§۱۰۸۵۳ ۔ امیمہ بنت عبداللہ\nبن ساعدہ، ان کا ذکر امیمہ بنت ابو حثمہ کے حالات میں گزر چکا ہے۔"],[9464,"§۱۰۸۵۴ ۔ امیمہ بنت عبدالمطلب\nوہ بنت ربیعہ بن حارث بن عبدالمطلب ہیں، اپنے جد اعلیٰ کی طرف منسوب ہیں، ان کے حالات گزر چکے ہیں۔"],[9465,"§۱۰۸۵۵ ۔ امیمہ بنت عبدالمطلب\nبن ہاشم بن عبد مناف ہاشمیہ، رسول اللہ صلی اللہ علیہ وسلم کی پھوپھی ہیں۔ ان کے اسلام لانے میں اختلاف ہے۔ محمد بن اسحاق نے اس کی نفی کی ہے۔ محمد بن سعد کے علاوہ ان کا کسی نے ذکر نہیں کیا، اور انہوں نے نبی صلی اللہ علیہ وسلم کے چچیری رشتوں کے باب میں طبقات النساء کے حصوں میں لکھا ہے۔ ان کی والدہ فاطمہ بنت عمرو بن عائذ بن عمران بن مخزوم ہیں۔ جاہلیت میں حجیر بن رئاب اسدی جو حرب بن امیہ کے حلیف تھے، ان سے عبداللہ اور عبید اللہ اور ابو احمد، زینب اور حمنہ پیدا ہوئے۔ خیبر کی کھجوروں میں سے چالیس وسق آپ صلی اللہ علیہ وسلم نے امیمہ بنت عبدالمطلب کو کھانے کے لیے دیئے۔ میں کہتا ہوں: اس بناء پر وہ اس وقت موجود تھیں جب آپ صلی اللہ علیہ وسلم نے ان کی بیٹی زینب رضی اللہ عنہا سے شادی کی۔"],[9466,"§۱۰۸۵۶ ۔ امیمہ بنت عدی\nبن قیس بن حذافہ سہمیہ، ابی عتیق کی والدہ ہیں، جو محمد بن عبد الرحمن بن ابو بکر صدیق رضی اللہ عنہ ہیں، زبیر بن بکار کا قول ہے: عبد الرحمن بن ابو بکر رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم کی حیات میں ہی ان سے شادی کی تھی، وہی (ابو عتیق) موسیٰ بن عقبہ کے قول کا قضیہ ہیں: کہ ابو عتیق محمد بن عبد الرحمن بن ابو بکر کو روایت کا شرف حاصل ہے، ان چاروں کو ایک سلسلے میں صحابہ کرام رضی اللہ عنہم کے زمرے میں شمار کیا ہے، جنہوں نے نبی صلی اللہ علیہ وسلم کو دیکھا ہے اور وہ یہ ہیں: محمد بن عبد الرحمن بن ابو بکر بن ابو قحافہ، مردوں کے ناموں میں محمد نامی لوگوں کے سلسلے میں ابو عتیق کے سوانح میں اس کا کچھ بیان پہلے گزر چکا ہے۔"],[9467,"§۱۰۸۵۷ ۔ امیمہ بنت عقبہ\n(1) بن عمرو بن عدی بن زید بن جشم انصاریہ۔ ابن سعد(2) نے بیعت کرنے والی خواتین میں ان کا ذکر کیا ہے۔ اور فرمایا کہ ان کی والدہ ام عمیر بنت عمرو حنظلیہ ہیں، ان کا نکاح سہل بن حنیف سے ہوا۔","",{"fn":"(1) تجرید (۲۴۸/۲)\n(2) الطبقات الکبریٰ (۲۴۱/۸)"}],[9468,"§۱۰۸۵۸ ۔ امیمہ بنت عمرو\n(1) بن سہل بن معبد بن مخرمہ انصاریہ اشہلیہ۔ ابن سعد(2) نے فرمایا: اسلام لائیں اور بیعت کی جیسا کہ واقدی کی روایت میں ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۳۶) تجرید (۲۴۸/۲)\n(2) الطبقات الکبریٰ (۲۳۷/۸)"}],[9469,"§۱۰۸۵۹ ۔ امیمہ بنت قیس\n(1) بن ابو صلت غفاریہ، ابن سعد(2) نے ان کا ذکر کیا ہے۔ اور فرمایا: اسلام لائیں اور ہجرت کے بعد بیعت کی، نبی کریم صلی اللہ علیہ وسلم کے ساتھ خیبر میں موجود تھیں، اور ان کی حیض کے بارے میں حدیث ذکر کی، عنقریب میں قسم رابع میں ذکر کروں گا کہ اس میں کیا اختلاف ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۴۰) تجرید (۲۴۸/۲)\n(2) الطبقات الکبریٰ (۲۳۷/۸)"}],[9470,"§۱۰۸۶۰ ۔ امیمہ بنت قیس\n(1) بن عبد اللہ اسدیہ تجرید(2) میں ان کا ذکر ہے۔ یہ وہی ہیں جو ام حبیبہ کے ساتھ حبشہ کی سرزمین میں تھیں، اور ان کے والدین ام حبیبہ کے رضاعی والدین ہیں، اور بنو اسد جاہلیت میں بنو امیہ کے حلیف تھے۔","",{"fn":"(1) تجرید (۲۴۸/۲)\n(2) تجرید (۱۸۱)"}],[9471,"§۱۰۸۶۱ ۔ امیمہ بنت النجار الانصاریہ\n(1) عقیلی نے ان کا ذکر صحابیات میں کیا ہے۔ اور ابن جریج کی سند سے نقل کیا ہے کہ حکیمہ بنت ابی حکیم اپنی والدہ امیمہ سے روایت کرتی ہیں کہ ازواج النبی صلی اللہ علیہ وسلم کی اوڑھنیاں تھیں جس میں ورس اور زعفران لگی ہوئی تھیں، جن سے وہ احرام سے پہلے اپنے سر کا زیریں حصہ ڈھانپتی تھیں اور احرام کے بعد بھی اسی طرح کرتی تھیں۔ ابو عمر رحمہ اللہ(2) فرماتے ہیں کہ میرا گمان ہے کہ یہ حدیث امیمہ بنت رقیقہ کی ہے جو لکڑی کے پیالے والی حدیث کی راویہ ہیں۔ میں کہتا ہوں: یہ گمان بعید ہے جبکہ ابن سعد(3) نے ان کا ذکر اُن عورتوں میں کیا ہے جنہوں نے ازواج النبی صلی اللہ علیہ وسلم سے روایت کی ہے اور ان عورتوں نے آپ صلی اللہ علیہ وسلم سے روایت نہیں کی۔ اور ابن جریج کے طریق سے اس حدیث کی سند بیان کی ہے۔","",{"fn":"(1) تجرید (۲۴۸/۲)\n(2) الاستيعاب (۱۷۹۱/۴)\n(3) الطبقات الکبریٰ (۳۵۴/۸)"}],[9472,"§۱۰۸۶۲ ۔ امیمہ بنت النعمان\n(1) بن حارث کندیہ، ان صحابیات میں ان کا ذکر گزر چکا ہے جن کا نام اسماء ہے۔","",{"fn":"(1) تجرید (۲۴۸/۲)"}],[9473,"§۱۰۸۶۳ ۔ امیمہ بنت النعمان\n(1) بن شراحیل جونیہ۔ بخاری(2) نے کتاب النکاح میں تعلیقاً حمزہ بن ابو اسید ساعدی کی سند سے نقل کیا ہے جس میں انہوں نے اپنے والد سے روایت کی ہے۔ اور عباس بن سہل بن سعد الساعدی کی سند سے بحوالہ ان کے والد نقل کیا ہے۔ دونوں فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے امیمہ بنت نعمان بن شراحیل سے نکاح کیا، جب ان کے پاس آئے اور ہاتھ بڑھایا تو انہوں نے ناپسند کیا۔ آپ صلی اللہ علیہ وسلم نے ابو اسید کو حکم دیا کہ ان کا سامان تیار کریں، اور پہننے کے لیے کتان کے دو سفید کپڑے دے دو۔ اسے موصولاً دوسری روایت سے نقل کیا ہے۔ فرمایا: ہم سے عبدالرحمن بن غسیل انہوں نے حمزہ بن ابی اسید، انہوں نے ابو اسید سے نقل کیا ہے، فرماتے ہیں: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نکلے یہاں تک کہ ہم ایک باغ کی طرف چلے جسے الشوط کہا جاتا تھا، جونیہ کو لایا جا چکا تھا، امیمہ بنت نعمان بن شراحیل کے گھر میں، میں اُترا، اس کے ساتھ اس کی ماما تھی۔ جب نبی صلی اللہ علیہ وسلم اس کے پاس آئے تو اس سے فرمایا: “مجھے اپنی جان بخش دو۔” وہ کہنے لگی: “بھلا ملکہ کسی بازاری کو اپنی جان بخشتی ہے؟” راوی فرماتے ہیں: آپ صلی اللہ علیہ وسلم نے اس کا غصہ ٹھنڈا کرنے کے لیے اپنا ہاتھ اس پر رکھنا چاہا تو وہ بولی: “تم سے اللہ کی پناہ!” آپ صلی اللہ علیہ وسلم نے فرمایا: “تو نے ایسی ذات کی پناہ مانگی ہے جو پناہ کی جگہ ہے۔ پھر آپ صلی اللہ علیہ وسلم باہر تشریف لائے اور فرمایا: “ابو اسید! اسے کتان کے سفید کپڑے پہناؤ اور اسے گھر والوں کے پاس چھوڑ آؤ۔” علم بیہقی(3) رحمہ اللہ نے اس صحیح حدیث کی وجہ سے یہ راجح قرار دیا ہے کہ پناہ طلب کرنے والی وہی تھیں۔ اسماء بنت نعمان بن جون کے حالات میں اس سے ملتا جلتا قصہ گزر چکا ہے۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (ت: ۶۷۳۴) تجرید (۲۴۸/۲)\n(2) بخاری (الحدیث: ۵۲۵۶)\n(3) احمد (الحدیث: ۴۹۸/۳) (۳۹۹/۵)"}],[9474,"§۱۰۸۶۴ ۔ امیمہ بنت ابی الہیثم\n(1) بن تیہان انصاریہ، ان کے والد کا ذکر گزر چکا ہے۔ ابو جعفر بن حبیب نے ان کا ذکر انصار کی بیعت کرنے والی خواتین میں کیا ہے۔ ابن سعد(2) کا قول ہے: ان کی والدہ ملیکہ بنت سہل ہیں، محمد بن عمر(3) کی روایت ہے کہ وہ اسلام لائیں اور بیعت کی۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۳۸) تجرید (۲۴۸/۲)\n(2) الطبقات الکبریٰ (۲۳۸/۸)\n(3) الاستيعاب (۱۷۹۱/۴)"}],[9475,"§۱۰۸۶۵ ۔ امیمہ (مولاۃ رسول اللہ صلی اللہ علیہ وسلم)\n(1) رسول اللہ صلی اللہ علیہ وسلم کی خدمت کرتی تھیں ان کی حدیث اہل شام کے پاس ہے۔ میں کہتا ہوں: محمد بن نصر نے تعظیم قدر الصلوۃ نامی کتاب میں اور ابو علی بن سکن اور حسن بن سفیان وغیرہ نے اپنی سند میں نقل کیا ہے۔ اور اس کی طرف ترمذی نے کتاب السیر میں ابو فروہ جو یزید بن سنان رہاوی ہیں کی سند سے اشارہ کیا ہے۔ فرماتے ہیں مجھ سے ابو یحییٰ کلاعی نے اور وہ سلیم بن عامر ہیں انہوں نے بیان کیا کہ انہوں نے جبیر بن نفیر سے، انہوں نے امیمہ خادمہ رسول اللہ صلی اللہ علیہ وسلم سے روایت کیا کہ وہ رسول اللہ صلی اللہ علیہ وسلم کو وضو کراتی تھیں، انہوں نے نبی کریم صلی اللہ علیہ وسلم کے ہاتھوں پر پانی ڈالا، اس وقت ایک شخص آیا اور کہا، یا رسول اللہ صلی اللہ علیہ وسلم میں اپنے گھر والوں سے ملنا چاہتا ہوں، مجھے وصیت کیجئے، آپ صلی اللہ علیہ وسلم نے فرمایا: “اللہ کے ساتھ شرک نہ کرو اگر چہ تمہارے ٹکڑے کر دیئے جائیں یا تمہیں جلا دیا جائے....” پھر پوری حدیث روایت کی۔ ابن سکن فرماتے ہیں کہ اسے سعید بن عبد العزیز نے بحوالہ مکحول، ام ایمن اسی طرح روایت کیا ہے۔ پھر ام ایمن کے حالات میں اس روایت کو مکمل طور پر سند کے ساتھ ذکر کیا ہے۔ اور فرمایا، وہ مرسل ہے کیونکہ مکحول نے ام ایمن کو نہیں پایا۔ میں کہتا ہوں: ہمیں یہ روایت مسند عبد بن حمید عالی سند سے ملی ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۳۱) تجرید (۲۴۷/۲)"}],[9476,"§۱۰۸۶۶ ۔ امیمہ\n(1) عبداللہ بن ابی بن سلول کی باندی ہیں۔ صحیح مسلم میں ابو سفیان بحوالہ جابر کی سند سے ان کا ذکر کیا ہے کہ عبداللہ بن ابی کی ایک لونڈی مسیکہ اور دوسری امیمہ تھی، وہ ان سے زنا کرانا چاہتا تھا۔ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے شکایت کی، پس اللہ تعالیٰ نے یہ آیت نازل کی: “اپنی لونڈیوں کو بدکاری پر مجبور نہ کرو۔”(2) اس آیت تک بخشنے والا، مہربان ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۳۵)\n(2) سورۃ نور (الآیۃ: ۳۳)"}],[9477,"§۱۰۸۶۷ ۔ امیمہ\nابو ہریرہ رضی اللہ عنہ کی والدہ ہیں، بعض نے کہا کہ ان کا نام میمونہ ہے۔ ابو موسیٰ نے یحییٰ بن العلاء کی سند سے بحوالہ ایوب، ابن سیرین، ابو ہریرہ رضی اللہ عنہ نقل کیا ہے کہ عمر بن خطاب رضی اللہ عنہ نے انہیں گورنری کے لیے بلایا، انہوں نے گورنر بننے سے انکار کر دیا۔ تو انہوں نے کہا: کیا تم گورنری کو ناپسند کرتے ہو؟ اس کو تم سے بہتر شخص نے طلب کیا تھا۔ انہوں نے پوچھا: وہ کون تھے؟ فرمایا: یوسف بن یعقوب۔ فرمایا: “یوسف علیہ السلام نبی ہیں نبی کے بیٹے ہیں اور میں ابو ہریرہ امیمہ کا بیٹا، پھر پورا قصہ ذکر کیا۔ مستدرک حاکم میں تفسیر یوسف میں اس کا ذکر ہے۔(1) اور ہم نے اسے جزء تاسع میں ابو یعلیٰ بن صابونی کے فوائد سے روایت کیا ہے۔","",{"fn":"(1) بیاض فی الاصل"}],[9478,"§۱۰۸۶۸ ۔ امینہ\nمیم کے بجائے نون کے ساتھ ہے، اور بعض نے کہا ہمینہ ہیں۔ ہمزہ کے بجائے ہاء کے ساتھ ہے۔ بنت خلف بن اسعد بن عامر بن بیاضہ بن سبیع خزاعیہ، طلحہ بن عبد اللہ بن خلف کی پھوپھی ہیں، جو طلحہ الطلحات کے نام سے مشہور ہیں، ابن اسحاق رحمہ اللہ(1) نے ان عورتوں میں ان کا ذکر کیا ہے جنہوں نے حبشہ کی طرف اپنے مسلمان خاوندوں کے ساتھ ہجرت کی۔ ان کے ساتھ ان کے خاوند خالد بن سعید بن العاص تھے، جن سے وہاں سعید اور ام خالد جن کا نام امہ بغیر اضافت کے ساتھ ہے، پیدا ہوئے۔","",{"fn":"(1) السیرۃ النبویۃ (۲۶۵/۳)"}],[9479,"§۱۰۸۶۹ ۔ امیہ\n(1) بعض نے کہا: ان کا نام ہمیہ، ہمزہ کے بجائے ہاء کے ساتھ ہے۔ ابو سفیان بن حرب امویہ کی صاحبزادی ہیں۔ حویطب بن عبد العزیٰ کی زوجہ ہیں پھر صفوان بن امیہ سے شادی ہوئی۔ ابن سعد(2) نے ان کا ذکر کیا ہے اور فرمایا کہ ان کی والدہ صفیہ بنت ابو العاص بن امیہ ہیں، فرمایا: سہیلی نے ذکر کیا ہے کہ امیہ، امینہ کے علاوہ ہیں، اور پہلی سے عروہ بن مسعود کے ہاں اولاد ہوئی، اور بعض نے کہا: ان کا نام میمونہ ہے۔ ان کے بطن سے صفوان کا عبدالرحمن بیٹا پیدا ہوا۔","",{"fn":"(1) تجرید (۲۴۹/۲)\n(2) الطبقات الکبریٰ (۱۷۴/۸)"}],[9480,"§۱۰۸۷۰ ۔ امیہ بنت قیس الخزرجیہ\nابو موسیٰ نے ان کا ذکر کیا ہے۔ اسی طرح تجرید(1) میں بھی ذکر ہے۔ ابو موسیٰ کی کتاب میں میں نے ان کا ذکر نہیں پایا۔ انہوں نے آمنہ بنت قیس بن ابو الصلت الغفاریہ کا عنوان قائم کیا ہے۔ جن کا ذکر میں انشاء اللہ قسم رابع میں کروں گا۔","",{"fn":"(1) تجرید (۱۸۱)"}],[9481,"§۱۰۸۷۱ ۔ امیہ بنت ابو الصلت الغفاریہ\n(1) ان کا ذکر آخری قسم میں امامہ بنت ابو الحکم کے حالات میں آئے گا۔","",{"fn":"(1) الاستيعاب (ت: ۳۲۸۷)"}],[9482,"§۱۰۸۷۲ ۔ امیہ بنت ابی قیس الغفاریہ\nابن سعد(1) کی کتاب میں صفیہ بنت حیی کے حالات میں ان کا ذکر ہے۔ فرماتے ہیں: ہمیں واقدی نے بتایا کہ ہم نے محمد بن موسیٰ نے عمارہ بن مہاجر، امیہ بنت ابو قیس الغفاریہ بیان کیا، فرماتی ہیں کہ ہمیں ان خواتین میں سے ایک نے بتایا جنہوں نے صفیہ بنت حیی کو شب زفاف میں نبی کریم صلی اللہ علیہ وسلم کی طرف بھیجا تھا، وہ کہتی ہیں کہ میں نے انہیں فرماتے سنا: میری عمر ابھی سترہ سال نہیں ہوئی تھی۔(2) پھر سارا قصہ بیان کیا۔","",{"fn":"(1) الطبقات الکبریٰ (۲۱۴/۸)\n(2) السیرۃ النبویۃ (۲۶۵/۳)"}],[9483,"§۱۰۸۷۳ ۔ انیسہ بنت ثعلبہ\n(1) بن زید بن قیس انصاریہ خزرجیہ، جو بنو حارث بن خزرج سے ہیں، ابن حبیب نے فرمایا: انہیں شرف صحابیت حاصل ہے، ابن اثیر نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۴۱) تجرید (۲۴۹/۲)"}],[9484,"§۱۰۸۷۴ ۔ انیسہ بنت ابی حارثہ\n(1) بن صعصعہ انصاریہ۔ قتادہ بن نعمان اور ابو سعید جو سعد بن مالک خدری ہیں، ان کی والدہ ہیں۔ ابن حبیب نے انہیں ان لوگوں میں ذکر کیا ہے جنہوں نے رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۴۲)"}],[9485,"§۱۰۸۷۵ ۔ انیسہ بنت حبیب\n(1) خ اور ب کے ساتھ تصغیر ہے۔ ابن یساف بن عتبہ بن عمرو بن خدیج بن عامر بن جشم بن حارث بن خزرج انصاریہ۔ نبی کریم صلی اللہ علیہ وسلم سے روایت کی، ان سے ان کے بھائی کے بیٹے حبیب بن عبد الرحمن بن حبیب بن یساف نے روایت کی۔ ابن سعد(2) رحمہ اللہ فرماتے ہیں: اسلام لائیں اور نبی کریم صلی اللہ علیہ وسلم سے بیعت ہوئیں اور آپ صلی اللہ علیہ وسلم کے ساتھ حج کیا، اور ابن حبان نے کہا کہ انہیں شرف صحابیت حاصل ہے۔ اور ابن سکن اور ابو عمر(3) فرماتے ہیں: ان کا شمار اہل بصرہ میں ہے۔ میں کہتا ہوں: ان کی حدیث مسند احمد، نسائی اور صحیح ابن خزیمہ میں ہے، یہ روایت ہمیں مسند طیالسی میں عالی سند سے لکھی ہوئی ملی ہے، جو یہ ہے: سیدنا بلال اور ابن ام مکتوم نبی کریم صلی اللہ علیہ وسلم کے مؤذن تھے.... (الحدیث) اور اس کے بعد طرق میں ہے: جب ابن ام مکتوم اذان دیں تو کھایا پیا کرو اور جب بلال اذان دیں تو کھانا پینا بند کر دو۔ اگر ہم میں سے کسی عورت کی سحری میں سے کوئی چیز بچ جاتی تو وہ بلال سے کہتی: ذرا ٹھہرنا! میں سحری سے فارغ ہو لوں۔ ابن سعد نے اسے صحیح سند سے ذکر کیا ہے۔ بحوالہ خبیب بن عبد الرحمن جو اپنی پھوپھی انیسہ سے روایت کرتے ہیں، فرماتی ہیں: قبیلے کی لڑکیاں اپنی بکریاں لے کر سیدنا ابوبکر صدیق رضی اللہ عنہ کے پاس جائیں تو وہ ان سے کہتے: کیا تمہیں پسند ہے کہ میں تمہارے لیے ابن عفراء کی طرح دودھ دوہوں؟ اور تہذیب الکمال میں لکھا ہے، بعض نے کہا: ان کو شرف صحابیت حاصل ہے۔ جس نے صحابہ رضی اللہ عنہم کے بارے میں کتابیں لکھی ہیں، انہوں نے ان کا شمار عام صحابہ رضی اللہ عنہم میں کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۴۳) تجرید (۲۴۹/۲)\n(2) الطبقات الکبریٰ (۲۶۵/۸)\n(3) الاستيعاب (۱۷۹۱/۴)"}],[9486,"§۱۰۸۷۶ ۔ انیسہ بنت رافع\n(1) بن المعلیٰ بن لوذان انصاریہ، بنو بیاضہ سے ہیں، نبی کریم صلی اللہ علیہ وسلم سے بیعت کی، یہ ابن حبیب کا قول ہے اور ابن اثیر نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۴۴)"}],[9487,"§۱۰۸۷۷ ۔ انیسہ بنت رہم\n(1) بعض نے کہا: رقیم انصاریہ ہیں، اور بنو ظلمہ سے تعلق رکھتی ہیں، ابن حبیب کے قول کے مطابق نبی کریم صلی اللہ علیہ وسلم سے بیعت کی، ابن اثیر(2) نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۴۵) تجرید (۲۴۹/۲)\n(2) الطبقات (۲۶۱/۸)"}],[9488,"§۱۰۸۷۸ ۔ انیسہ بنت ساعدہ\n(1) بنو عمرو بن عوف سے ہیں، ابن حبیب کا قول ہے کہ نبی کریم صلی اللہ علیہ وسلم سے بیعت کی، ابن اثیر نے ان کا اپنے استدراک میں ذکر کیا ہے۔ ذہبی رحمہ اللہ(2) فرماتے ہیں: وہ عویم بن ساعدہ کی بہن ہیں، یہ ان صحابیات میں سے ہیں جن کا ابن اثیر نے اپنے استدراک میں ذکر کیا ہے، ابن حبیب سے روایت ہے کہ ابن سعد(3) نے ان کا طبقات میں ذکر کیا ہے۔ انہی سے ابن حبیب نے لیا ہے، لگتا ہے ابن اثیر کو، طبقات ابن سعد دیکھنے کا موقع نہیں ملا۔ میں کہتا ہوں: ایسا ہی ہے جیسا انہوں نے کہا، بہت سے لوگوں نے طبقات کے رجال کو چھوڑ دیا ہے۔ اللہ تعالیٰ نے مجھ پر ان لوگوں کو شامل کرنے کا احسان کیا ہے۔ ذہبی رحمہ اللہ نے جیسا کہ اپنے مختصر میں لکھا، انہوں نے بہت سی خواتین کو شامل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۴۶) تجرید (۲۴۹/۲)\n(2) تجرید (۱۸۱)\n(3) الطبقات الکبریٰ (۲۵۴/۸)"}],[9489,"§۱۰۸۷۹ ۔ انیسہ بنت ابی طلحہ\n(1) بن عصمہ بن زید انصاریہ، بنو ظلمہ سے ہیں، ابن حبیب کا قول ہے کہ نبی کریم صلی اللہ علیہ وسلم سے بیعت کی، ابن اثیر نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۴۷) تجرید (۲۴۹/۲)"}],[9490,"§۱۰۸۸۰ ۔ انیسہ بنت عبداللہ\n(1) بن عمرو انصاریہ بیاضیہ، ابن سعد(2) نے ان کا ذکر کیا ہے۔ ذہبی رحمہ اللہ نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۲۴۹/۲)\n(2) الطبقات الکبریٰ (۲۸۳/۸)"}],[9491,"§۱۰۸۸۱ ۔ انیسہ بنت عدی الانصاریہ\n(1) بلی قبیلے کی خاتون ہیں، انصار میں ان کے حلیف ہیں، یہ ابو عمر رحمہ اللہ(2) کا قول ہے، اور فرمایا: انہیں شرف صحابیت حاصل ہے۔ ان سے سعید بن عثمان بلوی نے روایت کیا، وہ ان کی دادی اور عبداللہ بن سلمہ عجلانی جو اُحد میں شہید ہوئے، ان کی والدہ ہیں۔ ابن مندہ نے کہا کہ انیسہ بنت عدی انصاریہ نے اُحد میں شہید اپنے بیٹے عبداللہ بن سلمہ البدری کو لے جانے کی اجازت طلب کی، ان سے عیسیٰ بن یونس نے بحوالہ سعید بن عثمان روایت کی ہے اور انہوں نے اپنی دادی انیسہ سے نقل کیا ہے۔ میں کہتا ہوں: ابو بکر بن ابو عاصم، ابو زرعہ رازی، ابو علی بن سکن وغیرہ نے عیسیٰ بن یونس کی روایت سے ان کی حدیث کو مسند نقل کیا ہے۔ اور اس کے الفاظ یہ ہیں کہ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور کہنے لگیں: یا رسول اللہ! میرا بیٹا عبداللہ بن سلمہ جو بدر میں حاضر تھا، اُحد کے غزوہ میں شہید ہو گیا، میں اس کی نعش کو اپنی طرف منتقل کرنا چاہتی ہوں تا کہ میں اس کے قرب سے مانوس ہو سکوں تو رسول اللہ صلی اللہ علیہ وسلم نے انہیں منتقل کرنے کی اجازت دے دی، جنہیں انہوں نے مجذر بن زیاد کے ذریعے ایک عباء میں اپنے اونٹ پر منتقل کیا، وہ انہیں لے کر چل پڑیں۔ آپ صلی اللہ علیہ وسلم نے دیکھ کر فرمایا: ان کے عمل میں موازنہ نہ کرو۔(3) مجذر ہلکے پھلکے تھے جبکہ عبداللہ بھاری جسم والے تھے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۴۸) تجرید (۲۴۹/۲)\n(2) الاستيعاب (۱۷۹۲/۴)\n(3) الاحاد والمثانی (۲۲۴/۶)"}],[9492,"§۱۰۸۸۲ ۔ انیسہ بنت عدی\nبن نصلہ قرشیہ عدویہ، نعمان بن عدی کی بہن ہیں، زبیر بن بکار نے ان کا ذکر کیا ہے، جو ان کے بھائی نعمان کے حالات میں ہے۔ اور نعمان کا ذکر اپنے مقام پر گزر چکا ہے۔"],[9493,"§۱۰۸۸۳ ۔ انیسہ بنت عروہ\n(1) بن مسعود بن سنان بن عامر بن امیہ انصاریہ، بنو بیاضہ سے ہیں۔ نبی کریم صلی اللہ علیہ وسلم سے بیعت کی،(2) یہ ابن حبیب کا قول ہے۔ اور ابن اثیر نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۴۹) تجرید (۲۴۹/۲)\n(2) الطبقات الکبریٰ (۲۸۰/۸)"}],[9494,"§۱۰۸۸۴ ۔ انیسہ بنت عمرو بن عنمہ\n(1) عین اور نون کے زبر کے ساتھ، یہ ثعلبہ بن عمرو شقیقہ کی بہن ہیں اور ان کی والدہ جھیر بنت تین بن کعب ہیں، جو بنو سلمہ انصاریہ سے ہیں، جو بنو سواد کی شاخ ہے۔ ابن حبیب نے فرمایا کہ انہیں شرف صحابیت حاصل ہے اور نبی کریم صلی اللہ علیہ وسلم سے بیعت کی، ابن اثیر نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (ت: ۶۷۵۰) تجرید (۲۴۹/۲)"}],[9495,"§۱۰۸۸۵ ۔ انیسہ بنت عمرو\n(1) بن قیس بن مالک بن عدی بن نجار، ابو سلیط جو اسیرہ بن عمرو ہیں، ان کی بہن ہیں، ان کی والدہ امیہ بنت اوس بن عجرہ ہیں، ان کا نعمان سے نکاح ہوا جس سے قتادہ اور ام سہل پیدا ہوئے۔ اس کے بعد مالک بن سنان سے نکاح ہوا جس سے ابو سعید پیدا ہوئے۔","",{"fn":"(1) تجرید (۲۴۹/۲)"}],[9496,"§۱۰۸۸۶ ۔ انیسہ بنت عنمہ\nگزشتہ کی طرح ہیں، ابن عدی بن سنان بن نابی بن عمرو بن سواد۔ ابن سعد(1) نے ان کا ذکر کیا ہے، اور فرمایا: ان سے عبداللہ بن عمرو بن حزام نے نکاح کیا، اور شریک بن اسود بن قیس کی سند سے بحوالہ نبیع عنزی، جابر بن عبد اللہ نقل کیا ہے۔ فرماتے ہیں: میرے والد اور ماموں اُحد کے دن شہید ہو گئے۔ میری والدہ ان دونوں کو لے کر آئیں، انہوں نے دونوں کو اونٹنی پر رکھا تھا، نبی کریم صلی اللہ علیہ وسلم کے منادی نے پکارا، شہداء کو ان کے مقتل میں دفن کرو، پس وہ لوٹائے گئے۔ ترمذی نے شعبہ بن اسود کے طریق سے نقل کیا ہے کہ وہ فرماتے ہیں کہ میری دو پھوپھیاں آئیں اور اگر یہ روایت محفوظ ہے تو احتمال ہے کہ دونوں شہداء کے لانے، لے جانے میں شریک تھیں۔","",{"fn":"(1) الطبقات الکبریٰ (۲۹۸/۸)"}],[9497,"§۱۰۸۸۷ ۔ انیسہ بنت قیس الخزرجیہ\n(1) تجرید(2) میں اسی طرح ہے۔ ابن حبیب نے ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۲۴۹/۲)\n(2) التجريد (۱۸۱)"}],[9498,"§۱۰۸۸۸ ۔ انیسہ بنت معاذ\n(1) بن ماعص بن قیس بن خلدہ بن مخلد انصاریہ زرقیہ، ابو عبادہ کی بہن ہیں، ابن حبیب نے ان کا ذکر کیا ہے۔ اور ابن اثیر نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۵۲) تجرید اسماء الصحابہ (۲۴۹/۲)"}],[9499,"§۱۰۸۸۹ ۔ انیسہ بنت ہلال\n(1) بن معلیٰ بن لوذان انصاریہ، بنو بیاضہ سے ہیں، ابن حبیب کا قول ہے کہ نبی کریم صلی اللہ علیہ وسلم سے بیعت کی، ابن اثیر نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۵۴) تجرید اسماء الصحابہ (۲۵۰/۲)"}],[9500,"§۱۰۸۹۰ ۔ آمنہ بنت العباس\nبن عبد المطلب بن ہاشم ہاشمیہ، دار قطنی نے اخوۃ میں ان کا ذکر کیا ہے، اور فرمایا ان سے عباس بن عتبہ بن ابو لہب نے نکاح کیا جس سے فضل بن عباس مشہور شاعر پیدا ہوئے۔"],[9501,"§۱۰۸۹۱ ۔ اسماء بنت زید\n(1) بن خطاب عدویہ۔ ابن مندہ نے فرمایا کہ انہیں دیدار حاصل ہے۔ ان سے محمد بن اسحاق نے بحوالہ محمد بن یحییٰ بن حبان، عبد اللہ بن عمر اور انہوں نے اسماء سے حدیث روایت کی ہے۔ میں کہتا ہوں: اس روایت میں ایسی کوئی شے نہیں جو رؤیت پر دلالت کرے، حدیث یہ ہے کہ اسماء بنت زید انہوں نے عبد اللہ بن عمر رضی اللہ عنہ سے روایت کیا، جنہوں نے عبد اللہ بن حنظلہ سے سنا: نبی کریم صلی اللہ علیہ وسلم نے ہر نماز کے وقت وضو کرنے کا حکم دیا جو ان پر گراں گزرا تو نبی کریم صلی اللہ علیہ وسلم نے مسواک کرنے کا حکم دیا.... (الحدیث) اسے ابو داؤد(2) نے نقل کیا ہے۔ ہاں! البتہ اس سے پتہ چلتا ہے کہ ان کا تعلق اس قسم سے ہے کیونکہ ان کے والد یمامہ میں نبی علیہ السلام کے کچھ ہی عرصہ بعد شہید ہوئے۔ صحابہ رضی اللہ عنہم کے ہاں اپنی اولادوں کو نبی علیہ السلام کے پاس ولادت کے وقت برکت کی دعا کے لیے لانے کے کئی اسباب تھے۔","",{"fn":"(1) اسد الغابہ (۶۷۰۰) تجرید اسماء الصحابہ (۲۴۴/۲)\n(2) ابوداؤد (الحدیث: ۴۸)"}],[9502,"§۱۰۸۹۲ ۔ امۃ اللہ بنت ابی بکرہ الثقفی\n(1) ابو عمر رحمہ اللہ(2) نے فرمایا: صحابہ رضی اللہ عنہم کا ان میں ذکر ہے۔ ان سے عطاء بن ابو میمونہ نے روایت کیا ہے۔ اہل بصرہ میں ان کا شمار ہے۔ ذہبی رحمہ اللہ(3) نے تجرید میں لکھا ہے کہ انہوں نے بیعت کی۔ میں کہتا ہوں: بعید نہیں کہ وہ اس قسم سے ہوں۔","",{"fn":"(1) اسد الغابہ (۶۷۲۱) تجرید اسماء الصحابہ (۲۴۶/۲)\n(2) الاستيعاب (۱۷۹۰/۴)\n(3) التجريد (۱۸۱)"}],[9503,"§۱۰۸۹۳ ۔ امۃ اللہ بنت حمزہ\n(1) بن عبد المطلب، ان کی کنیت ام فضل ہے۔ بعض نے کہا: یہ وہی امامہ ہیں جن کا ذکر پہلے ہو چکا ہے۔ بعض نے کہا: ان کی بہن ہیں، اگر یہ کوئی اور ہیں تو ہو سکتا ہے بچپن میں فوت ہو گئی ہوں، مجھے کتاب النسب میں ان کا ذکر نہیں ملا، میں نے اس لیے اس قسم میں ان کا ذکر کیا۔","",{"fn":"(1) تجرید اسماء الصحابہ (۲۴۶/۲)"}],[9504,"§۱۰۸۹۴ ۔ امامہ بنت الاشجع العبدی\nالاشجع عبدی کے بھتیجے عمرو بن عبد قیس کی اہلیہ ہیں۔ جب عمرو نبی کریم صلی اللہ علیہ وسلم کے پاس مسلمان ہو کر آئے تو ان کی زوجہ بھی اسلام لائیں، اس کا ذکر صحار بن عباس کے حالات میں گزر چکا ہے۔"],[9505,"§۱۰۸۹۵ ۔ امامہ بنت الحطیئہ الشاعر\nمحمد بن سلام الجمحی نے بحوالہ یونس بن عبید ایک قصہ میں ان کا ذکر کیا ہے، جو دلالت کرتا ہے کہ جاہلیت میں وہ اپنے والدین کے ساتھ تھیں، ان کا اونٹ چوری ہو گیا تو انہوں نے کہا: “ہم تین تھے اور تین ہمارے اونٹ تھے، زمانے نے میرے عیال پر ظلم کیا۔”"],[9506,"§۱۰۸۹۶ ۔ انیسہ النخعیہ\n(1)(2) انہوں نے معاذ بن جبل کا یمن میں بطور قاصد رسول اللہ صلی اللہ علیہ وسلم آنے کا ذکر کیا، فرمایا: ہمیں معاذ نے کہا، میں تمہاری طرف رسول اللہ صلی اللہ علیہ وسلم کا قاصد ہوں، پانچ وقت کی نماز پڑھو، رمضان کے روزے رکھو، اور بیت اللہ کا جو تم میں سے استطاعت رکھتا ہو حج کرو۔ فرماتی ہیں: وہ اس وقت اٹھارہ سال کے تھے۔ ابو عمر(3)(4) نے اسی طرح ان کا ذکر کیا ہے۔ ابن الاثیر فرماتے ہیں: ان کی عمر کے بارے میں تامل ہے کہ ان کا قاصد بنا کر بھیجا جانا ۹ ہجری میں تھا، اس سے یہ لازم آتا ہے کہ وہ نو سال کے اسلام لائے ہوں۔ جبکہ ایسا نہیں، جب انہوں نے بیعت کی تو وہ آدمی تھے۔ میں کہتا ہوں: صحیح یہ ہے کہ وہ اٹھائیس(۲۸) سال کے تھے، معاذ کی عمر کے بارے میں دوسری روایت بھی ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۵۳)\n(2) تجرید (۲۵۰/۲)\n(3) الاستيعاب (۳۲۹۱)\n(4) الاستيعاب (۱۷۹۲/۴)"}],[9507,"§۱۰۸۹۷ ۔ آمنہ بنت قیس\nبن عبد اللہ بنو اسد بن خزیمہ۔ وہ اور ان کے والد حبشہ میں ام حبیبہ کے ساتھ تھے، مستغفری نے ابن اسحاق(1) کے حوالہ سے ان کا ذکر کیا ہے۔ ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔ ابن الاثیر نے فرمایا: میرا خیال ہے وہ آمنہ بنت رقیش (شروع میں راء بغیر نقطوں والی اور شین نقطے والی) ہیں، ان کا ذکر گزر چکا ہے، ابو موسیٰ نے دو ترجمے لکھے ہیں، اور ان کی نسبت ابن اسحاق کی طرف کی ہے، یہ گمان کرتے ہوئے کہ وہ دو ہیں۔ میں کہتا ہوں: وہ ایسا ہی ہے جیسا ابن اثیر نے گمان کیا۔","",{"fn":"(1) السیرۃ النبویۃ (۶/۴)"}],[9508,"§۱۰۸۹۸ ۔ اسماء بنت الصلت\n(1) قتادہ ان کا نام لینے میں منفرد ہیں، اور وہ سنا بنت اسماء ہیں، جیسا کہ بغیر نقطے والی سین میں ان کا ذکر آئے گا۔","",{"fn":"(1) اسد الغابہ (۶۷۰۳) تجرید (۲۴۴/۲)"}],[9509,"§۱۰۸۹۹ ۔ اسماء\n(1) سیدہ عائشہ رضی اللہ عنہا کی شعر سنانے والی ہیں، یہ اسماء بنت یزید بن سکن ہیں، ابو موسیٰ نے ان کا علیحدہ ذکر کیا ہے۔ امام احمد رحمہ اللہ نے دوسری سند میں جن اسماء بنت یزید سے اسے نقل کیا ہے، وہ یہی ہیں۔","",{"fn":"(1) اسد الغابہ (۶۷۰۴) تجرید (۲۴۵/۲)"}],[9510,"§۱۰۹۰۰ ۔ اسماء بنت یزید الانصاریہ\n(1)(2)(3) بنو عبد الاشہل سے ہیں۔ ابن مندہ نے بحوالہ بنت یزید بن سکن ان کا علیحدہ ذکر کیا ہے۔ اور وہ دونوں ایک ہیں، بنت یزید بن سکن بنو عبد الاشہل سے ہیں، جیسا کہ میں نے ان کے حالات میں وضاحت کر دی ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۱۱)\n(2) الاستيعاب (۳۲۷۳)\n(3) تجرید (۲۴۵/۲)"}],[9511,"§۱۰۹۰۱ ۔ امامہ بنت الحارث\n(1)(2) بن حزن الہلالیہ، میمونہ بنت حارث کی بہن ہیں، جو نبی کریم صلی اللہ علیہ وسلم کی زوجہ ہیں۔ ابو عمر(3)(4) نے ان کا ذکر کیا ہے، لیکن فرمایا: اسی طرح بعض راویوں نے لکھا ہے لیکن انہیں وہم ہوا ہے اور لفظی غلطی کی ہے، مجھے معلوم نہیں کہ میمونہ کی کوئی اور باپ شریک بہن ہو، یا یہ کہ ان کی والدہ کا نام امامہ ہو، ان کی باپ شریک بہن لبابہ کبریٰ جو عباس کی زوجہ ہیں اور دوسری لبابہ صغریٰ جو ولید بن مغیرہ کی زوجہ ہیں، اور ماں شریک تین بہنیں ہیں، یہ سب چھ ہیں جن کا کتاب میں اپنی اپنی جگہ پر ذکر ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۱۴)\n(2) تجرید (۲۴۶/۲)\n(3) الاستيعاب (۳۲۷۸)\n(4) الاستيعاب (۱۷۸۸/۴)"}],[9512,"§۱۰۹۰۲ ۔ امامہ بنت ابی الحکم الغفاریہ\n(1) بعض نے کہا: آمنہ ہیں، ان سے ان کے بیٹے حکیم نے روایت کیا۔ تجرید(2) میں اسی طرح ہے۔ ان کے اصول میں اُمہ بنت ابو الحکم کے علاوہ میں نے کوئی اور نہیں دیکھے۔ اسد الغابہ میں ابن عبد البر اور ابو موسیٰ سے اسی طرح منقول ہے۔ رہے ابو عمر تو وہ کہتے ہیں: امتہ بنت ابو الحکم الغفاریہ، بعض نے کہا: یہ امیہ ہیں اور ان کے بیٹے سلیمان بن حکیم نے ان سے نبی کریم صلی اللہ علیہ وسلم سے قضا و قدر کے بارے میں حدیث روایت کی، رہے ابو موسیٰ تو انہوں نے مستغفری کے حوالے سے وہی کہا جو ترجمہ میں مذکور ہے، لیکن انہوں نے یہ نہیں کہا کہ انہیں امیہ کہا جاتا ہے۔ اور یہ زیادہ کیا ہے کہ خطیب نے فرمایا: امیہ بنت ابو الصلت یعنی ہمزہ کی پیش اور ی کی تصغیر کے ساتھ ہے۔ فرماتے ہیں: ابو عبد اللہ یعنی ابن مندہ نے تاریخ میں فرمایا: آمنہ بنت ابو الصلت، مد اور نون کے ساتھ۔ اسی طرح عبد الغنی نے المشتبه میں فرمایا، فرماتے ہیں: طبرانی وغیرہ نے ان کی مخالفت کی ہے، انہوں نے ان کا شمار بے نام لوگوں میں کیا ہے۔ پھر طبرانی کی روایت سے بحوالہ حجاج بن عمران السدونی، یحییٰ بن خلف، عبد الاعلیٰ محمد بن اسحاق، سلیمان بن حکیم، امتہ بنت ابو الحکم الغفاریہ حدیث روایت کی ہے۔ فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: ایک شخص جنت کے اتنا قریب ہو جائے گا کہ اس میں اور جنت کے درمیان ایک ہاتھ کا فاصلہ رہ جائے گا پھر وہ اس سے صنعاء جتنا دور ہو جائے گا۔ میں کہتا ہوں: یہ وہی حدیث ہے جس کی طرف ابو عمر نے اشارہ کیا ہے کہ وہ باب القدر میں ہے۔ لیکن ابو موسیٰ کے کلام سے ظاہر ہے کہ ابو عمر نے لفظ امہ کی تحریف کی ہے اور اسے امۃ دو زبروں اور تخفیف کے ساتھ پڑھا ہے۔ ان کا گمان ہے کہ وہ اسم ہے جبکہ وہ صفت ہے، اور الف کے پیش اور میم کی تشدید کے ساتھ ہے۔ سلیمان فرماتے ہیں کہ مجھ سے میری والدہ نے بیان کیا پھر ان کی نسبت ان کے والد کی طرف کی جبکہ ان کا نام نہیں لکھا، عنقریب واقدی کی روایت سے آئے گا کہ وہ ام علی ہیں، ابو موسیٰ کے کلام کا تقاضا یہ ہے کہ بنت ابی الحکم اور بنت ابی الصلت ایک ہوں، عبد الاعلیٰ کی روایت کے علاوہ ظاہر ہو چکا ہے کہ ان کے قول: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، اس میں وہم ہے کہ سند میں بنت ابی الحکم کے بعد صحابیہ کا لفظ رہ گیا ہے۔ ابو موسیٰ کو اس کا دھیان ہوا، انہوں نے ذکر کیا کہ ابو داؤد نے ابن اسحاق کی سند سے بحوالہ سلیمان بن نحیم، ان کی والدہ بنت ابی الصلت، قبیلہ غفار کی ایک عورت دوسری حدیث نقل کی ہے۔ اور یہ غفاریہ عورت سہیلی نے ذکر کی کہ اس کا نام لیلیٰ ہے۔ اور یہ ابوذر غفاری کی زوجہ ہیں، اور حرف لام میں آئے گا کہ ابو عمر نے لیلیٰ غفاریہ کا عنوان قائم کیا ہے۔ اسی طرح سہیلی نے ابو دلید سے نقل کیا ہے کہ ابو الصلت کا نام الحکم ہے۔ لگتا ہے کہ بعض راویوں نے اس میں قلب کر دیا ہے، اور یوں کہہ دیا: بنت ابو الحکم اور وہ الصلت ہیں۔ میں کہتا ہوں: اس بیان کردہ نسب کے مطابق روایت لیلیٰ غفاریہ سے ہے جو صحابیہ ہیں، خواہ ان کا نام امتہ ہو یا اُمیہ یا امامہ ہو یا آمنہ ہو، اور چاہے ان کے والد کا نام حکم ہو یا صلت ہو یا ابو حکم یا ابو صلت، گویا بعض راویوں کو صحابیہ لفظ کے ساقط کرنے میں وہم ہوا ہے۔ اور سند یوں بن گئی کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا جو غلطی سے تابعیہ کی طرف منسوب ہو گیا، میں نے یہ بات اس لیے کی ہے کہ حدیث کا مخرج ایک ہے۔ میں نے امیمہ بنت قیس بن ابی الصلت اور ان کی حدیث کا ایک اور قصہ میں ذکر کیا ہے۔ اگر چہ ان کی سند میں سلیمان بن حکیم ہے، اسی طرح میں نے اُمیہ بنت ابی قیس اور ان کی حدیث کا دوسرے قصہ میں ذکر کیا ہے۔ اگر چہ سند میں سلیمان بن حکیم نہیں ہیں، ان دونوں میں تعدد کا احتمال قریب ہے۔ ان کے برعکس جن کا ذکر پہلے گزر چکا ہے۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (۶۷۲۳) تجرید (۲۴۶/۲)\n(2) التجريد (۱۸۱)"}],[9513,"§۱۰۹۰۳ ۔ امیمہ بنت خلف الخزاعیہ\n(1) طلحہ بن عبد اللہ بن خلف کی پھوپھی ہیں، جو طلحہ الطلحات کے نام سے مشہور ہیں، ابو عمر نے ان صحابیات میں ان کا ذکر کیا ہے جن کا نام امیمہ ہے، انہوں نے اس میں لفظی غلطی کر دی ہے۔ ابن مندہ نے اسی طرح ان کا ذکر کیا ہے۔ لیکن کہا کہ امیمہ بنت خالد ہیں، انہوں نے ان کے نام میں لفظی غلطی کی ہے۔ اور صحیح امینہ دوسری میم کے بدلے ن کے ساتھ ہے۔ ان کے بارے میں کہا گیا ہے: ہمینہ ہمزہ کے بدلے ھاء کے ساتھ ہیں، اور صحیح گزر چکا ہے۔ امیمہ بنت خالد خزاعیہ، اسی طرح ابن مندہ نے ان کے والد کا نام لیا ہے۔ ابن اثیر نے فرمایا کہ اس میں وہم ہے۔ صحیح نام گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۳۰) تجرید (۲۴۷/۲)"}],[9514,"§۱۰۹۰۴ ۔ انیسہ بنت کعب\n(1) ام عمارہ ہیں، کہتی ہیں: ہمیں کیا ہے کہ ہمارا ذکر خیر نہیں کیا جاتا، اللہ تعالیٰ نے یہ آیت نازل فرمائی: “بے شک مسلمان مرد اور مسلمان عورتیں....” (الآیۃ)(2) ابو الوفا بغدادی نے تفسیر میں بحوالہ مقاتل ان کا یہی نام لیا ہے اور وہ وہم ہے ان کا نام نسیبہ (شروع میں نون اور ب کی تصغیر کے ساتھ ہے۔ یہ ابو موسیٰ کا قول ہے۔ میں کہتا ہوں: ام عمارہ کی حدیث مشہور ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۵۱) تجرید (۲۴۹/۲)\n(2) سورۃ الاحزاب الآیۃ (۳۵)"}],[9515,"§۱۰۹۰۵ ۔ بادیہ بنت غیلان\n(1) بن سلمہ الثقفیہ۔ یہ وہی ہیں مخنث نے جن کی بیت بیان کی تھی کہ وہ چار کے ساتھ آتی ہیں اور آٹھ کے ساتھ واپس ہوتی ہیں۔(2) حدیث صحیح بخاری میں ہے، اس میں ان کا نام نہیں ہے، جب ان کے والد اسلام لائے تو یہ اسلام لائیں اور روایت کی، ابن مندہ نے احمد بن خالد وہبی کی سند سے بحوالہ محمد بن اسحاق، زہری، قاسم بن محمد نقل کیا ہے، فرمایا: بادیہ بنت غیلان الثقفیہ کا ذکر سیدہ عائشہ رضی اللہ عنہا کی حدیث میں ہے کہ نبی کریم صلی اللہ علیہ وسلم نے انہیں استحاضہ میں ہر نماز کے وقت وضو کا حکم دیا۔ ابو نعیم فرماتے ہیں: اس روایت میں ان کا نام نہیں، ابن مندہ نے احمد بن خالد وہبی کی سند سے ان کا نام لیا ہے۔ ابن مندہ نے اسے دو طرح سے لکھا ہے۔ “ب” کے بدلے ن کے ساتھ، فرمایا: یہ وہم ہے، ان کے علاوہ نے بیان کیا ہے کہ اس کے شروع میں “ب” ہے۔ پھر دال کے بعد نون ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۵۵) تجرید (۲۵۰/۲)\n(2) بخاری (الحدیث: ۳۰۶) مسلم (الحدیث: ۳۳۴)"}],[9516,"§۱۰۹۰۶ ۔ بثینہ بنت النعمان\n(1)(2) بن خلف بن عمرو بن امیہ بن بیاضہ انصاریہ، بنو بیاضہ سے ہیں۔ ابن سعد(3) نے بیعت کرنے والیوں میں ان کا ذکر کیا ہے، کہتے ہیں: اسلام لائیں اور بیعت کی، محمد بن عمرو بن حزم نے اس کے بعد ان سے نکاح کیا، ان کی والدہ حبیبہ بنت قیس ہیں۔","",{"fn":"(1) اسد الغابہ (۶۷۵۸)\n(2) تجرید (۲۵۰/۲)\n(3) الطبقات الکبریٰ (۲۹۲/۸)"}],[9517,"§۱۰۹۰۷ ۔ بحینہ\n(1)(2) حاء سے بے نقطی، نون کی تصغیر کے ساتھ۔ بنت الحارث، ابن اسحاق(3) نے ان کا ان لوگوں میں ذکر کیا ہے جن میں نبی کریم صلی اللہ علیہ وسلم نے خیبر کی تیس وسق کھجوریں تقسیم کیں، اور ابو موسیٰ مستغفری نے اسے نقل کیا ہے۔ ابن اثیر فرماتے ہیں کہ وہ عبداللہ بن بحینہ کی والدہ ہیں۔ ابن سعد(4) نے اس کا ذکر کیا ہے، اور ان کے لیے علیحدہ عنوان قائم کیا ہے۔ کہتے ہیں: ان کا نام عبدہ بنت حارث ہے اور وہ الاکرت بن مطلب ہیں، ان سے مالک اُزدی نے نکاح کیا جو ان کے حلیف تھے، ان سے عبداللہ بن بحینہ پیدا ہوئے، ان دونوں کو شرف صحابیت حاصل ہے۔ ان کی والدہ اسلام لائیں اور رسول اللہ صلی اللہ علیہ وسلم سے بیعت ہوئیں۔ آپ صلی اللہ علیہ وسلم نے انہیں خیبر کی تیس وسق کھجوریں کھانے کے لیے دیں۔","",{"fn":"(1) الاستيعاب (۳۲۹۲)\n(2) تجرید (۲۵۰/۲)\n(3) السیرۃ النبویۃ (۲۷۲/۳)\n(4) الطبقات الکبریٰ (۱۶۵/۸)"}],[9518,"§۱۰۹۰۸ ۔ برزہ بنت الحارث الہلالیہ\nیزید بن الاصم کی والدہ ہیں۔ ان کی والدہ بنت عامر بن معتب ثقفی ہیں۔ ان کی سگی بہن عزہ بنت حارث کے حالات میں ان کا ذکر آئے گا۔"],[9519,"§۱۰۹۰۹ ۔ برزہ بنت مسعود\n(1) بن عمرو بن عمیر ثقفی، صفوان بن امیہ کی زوجہ ہیں۔ ان کے ساتھ اسلام لائیں اور ان کے بیٹے عبداللہ بن صفوان کی والدہ ہیں۔ جب صفوان اسلام لائے تو یہ ان کے پاس تھیں، اس وقت ان کی چھ بیویاں تھیں۔ اس کا بیان عاتکہ بنت ولید کے حالات میں آئے گا۔","",{"fn":"(1) اسد الغابہ (۶۷۶۰) تجرید (۲۵۰/۲)"}],[9520,"§۱۰۹۱۰ ۔ البرصاء\n(1) عبدالرحمن کی دادی ہیں، یہ کبشہ ہیں، ان کا ذکر حرف کاف میں آئے گا۔","",{"fn":"(1) اسد الغابہ (۶۷۶۱) تجرید (۲۵۰/۲)"}],[9521,"§۱۰۹۱۱ ۔ البرصاء\nشبیب بن برصاء کی والدہ ہیں، یہ وہی ہیں کہ ان کے والد کو آپ صلی اللہ علیہ وسلم نے نکاح کا پیغام دیا تھا، انہوں نے کہا: انہیں برص کا مرض ہے، حالانکہ ایسا نہیں تھا، ان کے والد لوٹے تو دیکھا انہیں برص کا مرض ہو چکا ہے، ان کا نام امامہ ہے، بعض نے کہا: قرصافہ ہے۔"],[9522,"§۱۰۹۱۲ ۔ برکہ\nام ایمن ہیں، کنیت کے باب میں ان کا ذکر آئے گا۔"],[9523,"§۱۰۹۱۳ ۔ برکہ الحبشیہ\n(1) ام حبیبہ بنت ابوسفیان کے ساتھ تھیں، وہاں ان کی خدمت کرتی تھیں، انہیں کے ساتھ واپس آئیں، یہ وہی ہیں جنہوں نے نبی کریم صلی اللہ علیہ وسلم کا پیشاب پی لیا تھا، جیسا کہ حدیث امیمہ بنت رقیقہ کی حدیث میں آتا ہے۔ ابو عمر(2) نے انہیں ام ایمن کے ساتھ ملا دیا ہے۔ ان کے حالات میں ابن جریج کی سند سے نقل کیا ہے، فرماتے ہیں: مجھے حکیمہ بنت امیمہ نے بحوالہ اپنی والدہ امیمہ بنت رقیقہ خبر دی ہے کہ نبی کریم صلی اللہ علیہ وسلم (سردیوں میں) لکڑی کے پیالے میں پیشاب کرتے تھے جو چار پائی کے نیچے رکھا جاتا تھا، ایک رات آپ صلی اللہ علیہ وسلم تشریف لائے تو پیالے میں کچھ نہ تھا، آپ صلی اللہ علیہ وسلم نے برکہ سے کہا جو ام حبیبہ کی خدمت کرتی تھیں اور ان کے ساتھ حبشہ کی سرزمین سے آئی تھیں، اس پیالے میں جو پیشاب تھا اس کا کیا ہوا؟ کہنے لگیں: یا رسول اللہ صلی اللہ علیہ وسلم میں نے اسے پی لیا ہے۔(3) عبدالرزاق نے اپنی مصنف میں بحوالہ ابن جریج کہا ہے: مجھے بتایا گیا کہ نبی کریم صلی اللہ علیہ وسلم لکڑی کے پیالے میں پیشاب فرماتے تھے جو چار پائی کے نیچے رکھا جاتا ہے۔ پس آپ صلی اللہ علیہ وسلم آئے اور ارادہ کیا تو پیالے میں کچھ نہ تھا۔ آپ کی اہلیہ نے ایک عورت سے جنہیں برکہ کہا جاتا تھا، اور سیدہ ام حبیبہ رضی اللہ عنہا کی خادمہ تھیں جو حبشہ کی سرزمین سے ان کے ساتھ آئی تھیں، فرمایا: پیشاب کہاں ہے؟ ابو عمر فرماتے ہیں: میرا گمان ہے کہ یہ برکہ ہی ام ایمن ہیں۔ انہیں یہ بات کہنے پر ان حالات نے آمادہ کیا جو ان کے ترجمہ برکہ ام ایمن کے شروع میں ہیں کہ انہوں نے دو ہجرتیں کیں، ایک حبشہ کی سرزمین اور دوسری مدینہ کی طرف ہجرت کی۔ ام ایمن نے حبشہ کی سرزمین کی طرف ہجرت کی، اس میں تامل ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم کی خدمت کرتی تھیں اور ان کے شوہر زید بن حارثہ نبی کریم صلی اللہ علیہ وسلم کے آزاد کردہ غلام تھے، اور زید نے حبشہ ہجرت نہیں کی، اور ان دنوں نبی کریم صلی اللہ علیہ وسلم کی خدمت میں کوئی نہ تھا، اس سے ظاہر ہوا کہ یہ حبشیہ ام ایمن کے علاوہ کوئی اور ہیں، اگر چہ ان کے نام میں موافقت ہو۔ ام ایمن کے حالات میں عنقریب آئے گا جیسا کہ ابن سکن نے بیان کیا کہ ان دونوں کی کنیت ام ایمن تھی اور نام برکہ تھا۔ اس کی تائید اس سے بھی ہوتی ہے کہ بول کا قصہ دوسری سند سے بھی مذکور ہے، جس کی رادیہ ام ایمن ہیں، جیسا کہ ان کے حالات میں ان شاء اللہ میں ذکر کروں گا۔","",{"fn":"(1) اسد الغابہ (۶۷۶۳) الاستيعاب (۳۲۹۸) تجرید (۲۵۱/۲)\n(2) الاستيعاب (۱۷۹۱/۴)\n(3) ابوداؤد (الحديث: ۲۴) النسائی (الحديث: ۳۲) طبرانی (الحديث: ۴۷۷/۲۴) حاکم (۱۶۷/۱)"}],[9524,"§۱۰۹۱۴ ۔ برکہ بنت یسار\n(1) ابوسفیان بن حرب کی باندی ہیں، اپنے شوہر قیس بن عبد اللہ اسدی کے ساتھ حبشہ کی طرف ہجرت کی، ابن ہشام نے بحوالہ ابن اسحاق(2) ان کا ذکر کیا ہے کہ یہ ان لوگوں میں سے تھیں جنہوں نے حبشہ کی طرف ہجرت کی۔ اسی طرح ابن سعد(3) نے ان کا ذکر کیا ہے جو قیس بن عبداللہ کے حالات میں گزر چکا ہے۔ بعض اہل مغرب نے یہ جواز بیان کیا ہے یہ برکہ حبشیہ جن کا ذکر ہوا ہے، وہی پہلے والی ہیں۔ جیسا انہوں نے گمان کیا، ویسا نہیں۔ برکہ بنت یسار بنو عبدالدار کے حلیفوں میں سے تھیں اور ابو تجراۃ کی بہن ہیں، ان کی اصل کندہ ہے اور حبشیہ نہیں ہیں۔ اگر چہ دونوں مہاجرین کے ساتھ حبشہ کی سرزمین میں موجود ہونے میں شریک تھیں۔","",{"fn":"(1) اسد الغابہ (۶۷۶۴) تجرید (۲۵۱/۲)\n(2) السیرۃ النبویۃ (۶/۴)\n(3) الطبقات الکبریٰ (۱۷۹/۸)"}],[9525,"§۱۰۹۱۵ ۔ برہ بنت ابی تجراۃ\n(1) بن ابی علیہہ اور ان کا نام یسار تھا۔ ابن سعد(2) نے کہا کہ وہ ازد سے تھے، پھر بنوعبدالدار کے حلیف ہوئے، ابن سعد فرماتے ہیں کہ ان کے والد یسار کی کنیت ابو ٹکیہ تھی۔ ٹکیہ کا ذکر آگے آئے گا۔ بعض نے کہا: یہ ان لوگوں میں تھے جن کا ذکر زبیر بن بکار نے کندہ والوں سے کیا ہے۔ وہ مکہ میں بنو عبدالدار کے حلیف بن گئے، نبی کریم صلی اللہ علیہ وسلم سے روایت کی، اور ان سے صفیہ بنت شیبہ نے سعی کے بارے میں روایت کی۔ ان سے عمیرہ بنت عبد اللہ بن کعب بن مالک نے ثویبہ کے رسول اللہ صلی اللہ علیہ وسلم کو دودھ پلانے کا قصہ روایت کیا ہے۔ اس میں طلیب بن عمیر کا نبی کریم صلی اللہ علیہ وسلم کی مدد کا قصہ ہے۔ اور اَرویٰ بنت عبدالمطلب کے حالات میں گزر چکا ہے۔ واقدی نے اسے نقل کیا ہے۔ اسی طرح صفیہ بنت شیبہ کی سند سے بحوالہ ان کے کسی اور نے بھی نقل کیا ہے، حدیث سعی میں صفیہ کے آگے اختلاف ہے۔ چنانچہ اسے بحوالہ برہ روایت کیا ہے۔ ابن مندہ وغیرہ نے اسے نقل کیا ہے۔ اور عطاء بن ابی رباح نے صفیہ سے اور انہوں نے حبیبہ سے اسے روایت کیا ہے۔ حرف حاء میں ان کا ذکر آئے گا۔","",{"fn":"(1) اسد الغابہ (۶۷۶۶) تجرید (۲۵۱/۲)\n(2) الطبقات الکبریٰ (۱۷۹/۸)"}],[9526,"§۱۰۹۱۶ ۔ برہ بنت الحارث الہلالیہ\nیہ میمونہ ام المومنین ہیں، ان کا نام پہلے برہ تھا نبی کریم صلی اللہ علیہ وسلم نے جب ان سے شادی کی تو اسے بدل دیا، ابن ابو خیثمہ نے اسے عمدہ سندوں سے روایت کیا ہے۔"],[9527,"§۱۰۹۱۷ ۔ برہ بنت الحارث المصطلقیہ\nام المومنین جویریہ رضی اللہ عنہا ہیں، ان کا نام پہلے برہ تھا، نبی کریم صلی اللہ علیہ وسلم نے جب ان سے نکاح کیا تو اسے بدل دیا۔ یہ ابن عباس اور قتادہ سے مروی ہے، مسلم نے اسے دوسرے طریق سے نقل کیا ہے۔"],[9528,"§۱۰۹۱۸ ۔ برہ بنت سفیان السلمیہ\nابواعور سلمی کی بہن ہیں، ان سے حارث بن طلحہ نے نکاح کیا جو حالت کفر میں اُحد کے دن مارا گیا۔ پھر ان سے عبداللہ بن عمر نے نکاح کیا، جس سے دو بچے پیدا ہوئے: عبداللہ اور صفیہ وغیرہ۔ ان کے بعد بھی زندہ رہیں، زبیر بن بکار نے اس کا ذکر کیا ہے۔"],[9529,"§۱۰۹۱۹ ۔ برہ بنت ابی سلمہ\n(1) بن عبدالاسد، یہ زینب رسول اللہ صلی اللہ علیہ وسلم کی پروردہ ہیں، ان کا نام برہ تھا، نبی کریم صلی اللہ علیہ وسلم نے جب ان کی والدہ سے نکاح کیا تو اسے بدل دیا، اور ان کا نام زینب رکھا۔ ان کے حالات حرف زاء میں آئیں گے۔ ان شاء اللہ تعالیٰ۔","",{"fn":"(1) اسد الغابہ (۶۷۶۷) تجرید (۲۵۱/۲)"}],[9530,"§۱۰۹۲۰ ۔ برہ بنت عامرہ\n(1) بن حارث بن سباق بن عبدالدار بن قصی، قرشیہ عبدریہ۔ ابو عمر(2) نے فرمایا: ابو اسرائیل کی زوجہ تھیں جو بنو حارث سے تھے، جس کا قصہ نذر کی حدیث میں آیا ہے۔ ان سے اسرائیل پیدا ہوئے، جو جنگ جمل میں شہید ہوئے۔ سیدہ برہ کا تعلق مہاجر صحابیات سے تھا۔","",{"fn":"(1) اسد الغابہ (۶۷۶۸) تجرید (۲۵۱/۲)\n(2) الاستيعاب (۱۷۹۳/۴)"}],[9531,"§۱۰۹۲۱ ۔ برہ (بے نسبت)\nطبرانی نے اوسط میں لکھا ہے۔ ہم سے محمد بن العباس المؤدب نے ان سے عبید بن اسحاق العطار نے، وہ فرماتے ہیں کہ ہم سے قاسم بن محمد بن عبد اللہ بن عقیل نے اور وہ فرماتے ہیں کہ مجھ سے ابو عبد اللہ نے اور میں اپنے دادا کو باپ کہہ کر پکارتا تھا، وہ فرماتے ہیں کہ ہم سے جابر بن عبداللہ نے حدیث بیان کی، فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی خادمہ تھیں جو ان کی خدمت کرتی تھیں، انہیں برہ کہا جاتا تھا، ان سے ایک آدمی ملا اور کہا: اے برہ! اپنی پنڈلیاں ڈھانپ لو، بے شک محمد اللہ کے سامنے تمہارے کچھ کام نہ آئیں گے، اس نے نبی کریم صلی اللہ علیہ وسلم کو بتا دیا، پس نبی کریم صلی اللہ علیہ وسلم اپنی چادر کو گھسیٹتے ہوئے باہر تشریف لائے اور آپ کے رخسار غصے سے سُرخ ہو رہے تھے.... (الحدیث) عبید اور اس کا شیخ دونوں متروک ہیں۔ واللہ اعلم!"],[9532,"§۱۰۹۲۲ ۔ بروع بنت واشق الرؤاسیہ\n(1) کلابیہ، یا اشجعیہ۔ ہلال بن مرہ کی زوجہ ہیں۔ معقل اشجعی وغیرہ کی حدیث میں ان کا ذکر ہے۔ ان کی حدیث ابن ابو عاصم نے ان سے روایت کی ہے، جو شنی بن صباح کی سند سے مروی ہے۔ بحوالہ عمرو بن شعیب جو سعید بن مسیب سے اور وہ بروع بنت واشق سے روایت کرتے ہیں کہ انہوں نے ایک آدمی سے نکاح کیا اور اپنے نفس کو اس کے سپرد کر دیا، وہ اس سے صحبت کرنے سے پہلے فوت ہو گیا تو نبی کریم صلی اللہ علیہ وسلم نے اس کے لیے مہر مثل کا فیصلہ کیا، معقل کی حدیث سنن میں ہے، نسائی نے اس کے طرق کی تخریج اور اس کے راویوں کے بیان اختلاف کو عبد اللہ بن مسعدہ کے حصہ میں بیان کیا ہے۔ امام احمد رحمہ اللہ نے زائدہ کے طریق سے بحوالہ منصور نقل کیا ہے۔ انہوں نے ابراہیم سے، انہوں نے علقمہ اور الاسود سے نقل کیا ہے۔ (الحدیث) اس میں ہے: اشجع سے ایک آدمی کھڑا ہوا، میرا خیال ہے وہ سلمہ بن یزید ہے اس نے کہا ہم میں سے ایک آدمی نے بنو رؤاس کی ایک خاتون بروع سے نکاح کیا.... (الحدیث)","",{"fn":"(1) اسد الغابہ (۶۷۶۵) الاستيعاب (۳۳۰۰)"}],[9533,"§۱۰۹۲۳ ۔ بریدہ بنت بشر\n(1) بن حارث بن عمرو بن حارثہ، جو عباد بن سہل بن اساف کی بیوی تھیں۔ ان سے ابراہیم بن عباد پیدا ہوئے، محمد بن حبیب نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کرنے والی خواتین میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۶۹) تجرید (۲۵۱/۲)"}],[9534,"§۱۰۹۲۴ ۔ بریرہ\nرسول اللہ صلی اللہ علیہ وسلم کی باندی تھیں، ابن ابو شیبہ کہتے ہیں ہم سے وکیع نے بحوالہ منذر بن ثعلبہ، انہوں نے عبداللہ بن بُریرہ روایت کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم جب رات کے وقت بیدار ہوتے تو خادمہ بریرہ کو مسواک کے لیے بلاتے، احتمال ہے کہ یہ وہی ہیں جن کا ذکر آگے آئے گا، اور مجازاً رسول اللہ صلی اللہ علیہ وسلم کے موالی میں شمار ہونے لگیں۔"],[9535,"§۱۰۹۲۵ ۔ بریرہ\n(1) سیدہ عائشہ رضی اللہ عنہا کی باندی ہیں، بعض نے کہا: انصار کی کسی قوم کی باندی ہیں، بعض نے کہا: عقبہ بن ابو اسرائیل کی، بقول بعض: ابو ہلال کی، کسی کا یہ قول ہے: ابو احمد بن جحش اور اس قول میں تامل ہے۔ اس کے شوہر مغیث کے حالات میں گزر چکا ہے کہ وہ ابو احمد بن جحش کے غلام تھے، دوسرا قول غلط ہے مولیٰ عتبہ نے سیدہ عائشہ رضی اللہ عنہا سے اس مسئلے کا حکم دریافت فرمایا، انہوں نے بریرہ کا قصہ ذکر کیا۔ ابن سعد رحمہ اللہ نے اسے نقل کیا ہے اس کی اصل بخاری میں ہے۔ سیدہ عائشہ رضی اللہ عنہا نے انہیں خریدا اور آزاد کر دیا۔ سیدہ عائشہ رضی اللہ عنہا کے خریدنے سے پہلے وہ ان کی خدمت کرتی تھیں، ان کا قصہ صحیحین میں ہے۔(2) دونوں میں سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ بریرہ کے قصے میں تین مسائل ہیں.... (الحدیث) اس میں ہے، وراثت آزاد کرنے والے کے لیے ہے۔ بعض ائمہ نے اس حدیث کے فوائد جمع کئے ہیں، وہ تین سو سے زیادہ ہیں، فتح الباری میں میں نے ان کی تلخیص کر دی ہے۔ نسائی نے یزید بن رومان کے طریق سے بحوالہ عروہ سیدہ بریرہ سے روایت کیا ہے۔ فرماتی ہیں: میرے بارے میں تین سنتیں ہیں۔ (الحدیث) اور اس کے رجال ثقہ ہیں، لیکن نسائی نے کہا: وہ خطا ہے، یعنی صحیح یہ ہے: عروہ، عائشہ رضی اللہ عنہا سے روایت کرتی ہیں۔ ابو عمر(3) نے اس کا ذکر عبد الخالق بن زید بن واقد کے طریق سے بحوالہ ان کے والد کیا ہے کہ عبدالملک بن مروان فرماتے ہیں: میں بریرہ کے پاس مدینہ میں بیٹھا کرتا تھا وہ مجھ سے فرماتی تھیں: اے عبدالملک! مجھے تم میں کچھ (شاہانہ) خصلتیں نظر آتی ہیں، اور تم واقعی اس کے اہل ہو کہ یہ ذمہ داری تمہیں سونپی جائے۔ اگر تم والی بن گئے تو خون بہانے سے بچنا، کیونکہ میں نے نبی علیہ السلام کو فرماتے سنا ہے: “آدمی کو جنت کے دروازے سے ہٹا دیا جائے گا، جبکہ وہ اس کی طرف دیکھ چکا ہوگا، اس ناحق خون کے گھاؤ کی وجہ سے جو کسی مسلمان کا بہایا ہوگا۔”(4)","",{"fn":"(1) اسد الغابہ (۶۷۷۰) تجرید (۲۵۱/۱)\n(2) بخاری (الحديث: ۲۱۶۹) مسلم (الحديث: ۳۷۵۵)\n(3) الاستيعاب (۱۷۹۵/۴)\n(4) الطبرانی (الحديث: ۵۲۶/۲۴) الہیثمی (الحدیث: ۲۹۸/۷)"}],[9536,"§۱۰۹۲۶ ۔ بریعہ بنت ابی حارثہ\n(1) بن اوس بن دخیش انصاریہ، بنو عوف بن خزرج سے ہیں۔ ابن حبیب نے رسول اللہ صلی اللہ علیہ وسلم سے بیعت کرنے والی خواتین میں ان کا ذکر کیا ہے۔ ابن اثیر(2) نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۷۱) تجرید (۲۵۱/۲)\n(2) الطبقات الکبریٰ (۲۷۸/۸)"}],[9537,"§۱۰۹۲۷ ۔ بریعہ بنت ابی خارجہ\n(1) بن اوس۔ ابن سعد(2) نے ان کا ذکر کیا ہے۔ تجرید میں بھی ان کا ذکر ہے۔ میرا گمان ہے کہ یہ اور جو ان سے پہلے ہیں ایک ہی ہیں، ان کے نام اور ان کے والد کے نام میں لفظی غلطی ہے اسے صحیح کر کے لکھ لیا جائے۔","",{"fn":"(1) تجرید (۲۵۱/۲)\n(2) الطبقات الکبریٰ (۲۷۸/۸)"}],[9538,"§۱۰۹۲۸ ۔ بسرہ بنت صفوان\n(1) بن نوفل بن اسد بن عبد العزیٰ بن قصی قرشیہ اسدیہ، ورقہ بن نوفل کی بھتیجی ہیں۔ بعض نے کہا: صفوان بن امیہ بن محرث کی صاحبزادی ہیں، بنو مالک بن کنانہ۔ ابن اثیر(2) کا قول ہے: اول صحیح ہے، ان کی والدہ سالمہ بنت امیہ بن حارثہ بن اوقص سلمیہ ہیں، عقبہ بن ابو معیط کی ماں شریک بہن تھیں، بسرہ مغیرہ بن ابو العاص کی زوجہ تھیں۔ ان سے عائشہ رضی اللہ عنہا پیدا ہوئیں، جن کی شادی مروان بن حکم(3) سے ہوئی جس سے عبدالملک پیدا ہوئے، اسی طرح ان کا قول ہے جو غلط ہے۔ ام عبد الملک معاویہ کی بیٹی اور مغیرہ کی بہن ہیں۔ زبیر بن بکار کا یہ قول ہے اور وہ اپنی قوم کے نسب کو سب سے زیادہ جانتے تھے۔ بسرہ نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی ہے اور ان سے مروان بن حکم، عروہ بن زبیر، سعید بن مسیب، ام کلثوم بنت عقبہ اور محمد بن عبدالرحمن نے روایت کی۔ امام شافعی رحمہ اللہ فرماتے ہیں: سابقین اولین میں سے ہیں اور ہجرت کی سعادت حاصل ہے۔ ابن حبان فرماتے ہیں: ہجرت کرنے والی خواتین میں سے تھیں، مصعب فرماتے ہیں: بیعت کرنے والی صحابیات میں شامل تھیں، اسحاق نے اپنی مسند میں عمرو بن شعیب کے طریق سے نقل کیا ہے۔ فرماتے ہیں: میں سعید بن مسیب کے پاس تھا۔ فرمانے لگے: بُسرہ بنت صفوان میری خالاؤں میں سے ایک ہیں، پھر مس ذکر کی حدیث(4) ذکر کی۔ ابن کلبی نے ذکر کیا کہ وہ کنگھی کرنے والی تھیں اور مکہ میں عورتوں کی خدمت کرتی تھیں۔","",{"fn":"(1) اسد الغابہ (۶۷۷۲) تجرید (۲۵۱/۲)\n(2) اسد الغابہ (۲۲۹/۵)\n(3) الطبقات الکبریٰ (۱۷۸/۸)\n(4) ترمذی (الحدیث: ۸۲)"}],[9539,"§۱۰۹۲۹ ۔ بسرہ بنت غزوان\n(1) یہ وہی ہیں، ابو ہریرہ رضی اللہ عنہ نے جن کی مزدوری کی تھی۔ پھر ان سے نکاح کر لیا۔ میں نے نہیں دیکھا کہ کسی نے ان کا ذکر کیا ہو۔ تجرید میں اسی طرح ہے۔ میں کہتا ہوں: عتبہ بن غزوان المازنی جو مشہور صحابی ہیں، ان کی بہن ہیں۔ وہ بصرہ کے امیر تھے۔ سیدنا ابو ہریرہ رضی اللہ عنہ کا قصہ ان کے ساتھ صحیح ہے، نبی کریم صلی اللہ علیہ وسلم کے عہد میں ان کی مزدوری کی، پھر اس کے بعد ان سے نکاح کر لیا، مروان مدینہ کی حکومت میں انہیں نائب بناتے تھے۔","",{"fn":"(1) تجرید (۳۲/۲)"}],[9540,"§۱۰۹۳۰ ۔ بشرہ\n(1) ب کی زیر اور شین نقطوں والے کے ساتھ، بنت ملیل، دو لام کے ساتھ تصغیر ہے۔ ابن وبرہ انصاریہ، حبیبہ جن کے حالات آگے آئیں گے ان کی بہن ہیں۔ ابن سعد(2) نے ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۲۵۲/۲)\n(2) الطبقات الکبریٰ (۲۴۷/۸)"}],[9541,"§۱۰۹۳۱ ۔ بشیرہ\n(1) عظیمہ کے وزن پر ہے، بنت حارث بن عبد رزاح بن ظفر انصاریہ ظفریہ۔ ابن حبیب نے ان کا ذکر ان خواتین میں کیا ہے جنہوں نے رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی۔(2)","",{"fn":"(1) اسد الغابہ (۶۷۷۳) تجرید (۲۵۲/۲)\n(2) الطبقات الکبریٰ (۲۴۸/۸)"}],[9542,"§۱۰۹۳۲ ۔ بشیرہ بنت ثابت\n(1) بن نعمان بن حارث انصاریہ۔ ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۲۵۲/۲)\n(2) الطبقات الکبریٰ (۲۴۹/۸)"}],[9543,"§۱۰۹۳۳ ۔ بشیرہ بنت النعمان\nبن حارث انصاریہ، ابن سعد نے ان کا ذکر بھی بیعت کرنے والی خواتین میں کیا ہے۔"],[9544,"§۱۰۹۳۴ ۔ البغوم\n(1) اس کے شروع میں زبر ہے اور غین کے پیش کے ساتھ، بنت معذل۔ ان کا نام خالد بن عمرو بن سفیان بن حارث بن زبان بن عبدیالیل کنانیہ، بنو حارث بن عبد مناة بن کنانہ سے ہیں، صفوان بن امیہ بن خلف کی زوجہ ہیں، اور ان کی اولاد عبداللہ اصغر، صفوان، عمرو کی ام ولد ہیں، فتح کے دن اسلام لائیں۔ یہ واقدی(2) کا قول ہے، ابوعلی جیانی کی کتاب پر ابن اثیر(3) نے اپنے استدراک میں ان کا ذکر کیا ہے۔ میں کہتا ہوں: واقدی نے موسیٰ بن عقبہ کے طریق سے بحوالہ ابو حبیب مولیٰ زبیر، اور انہوں نے ابن زبیر سے اسے مسند ذکر کیا ہے۔ فرماتے ہیں: بغوم بنت معذل کنانیہ، صفوان بن امیہ کی زوجہ اسلام لائیں اور صفوان بھاگ گئے یہاں تک کہ کشتی تک پہنچ گئے، پھر ان کے خوف کا قصہ حنین کے واقعہ کے بعد اسلام لانے کا ذکر کیا۔ ابن سعد(4) فرماتے ہیں: اسلام لائیں اور حجتہ الوداع کے موقع پر بیعت ہوئیں۔ بعض نے کہا: فتح کے دن اسلام لائیں پھر اسے واقدی سے مسنداً ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۷۴) الاستيعاب (۳۳۰۳) تجرید (۲۵۲/۲)\n(2) الطبقات الکبریٰ (۲۱۸/۸)\n(3) اسد الغابہ (۴۱۰/۵)\n(4) الطبقات الکبریٰ (۲۱۸/۸)"}],[9545,"§۱۰۹۳۵ ۔ بقیرہ\n(1) قعقاع بن ابوحدرد اسلمی کی زوجہ ہیں، ابن ابو خیثمہ نے ان کا ذکر کیا ہے۔ فرماتے ہیں: مجھے معلوم نہیں اسلام لائیں یا نہیں، اور امام احمد(2) نے سند میں محمد بن اسحاق کے طریق سے بحوالہ محمد بن ابراہیم بن حارث تیمی نقل کیا ہے۔ فرماتے ہیں: میں نے بقیرہ، جو قعقاع کی زوجہ ہیں، سے سنا وہ فرماتی ہیں کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: “اے لوگو! جب تم سنو کہ ایک لشکر قریب ہی دھنسا دیا گیا ہے تو قیامت آگئی۔” اسے ابن سکن نے اس طریق سے نقل کیا ہے۔ بقیرہ سے اس حدیث اور اس سند کے علاوہ اور کوئی روایت نہیں۔","",{"fn":"(1) اسد الغابہ (۶۷۷۵) تجرید (۲۵۲/۲)\n(2) مسند احمد (۳۷۸/۶)"}],[9546,"§۱۰۹۳۶ ۔ بُقیلہ\nسماک خیبری کی زوجہ ہے، جن کے ترجمے میں ان کا ذکر گزر چکا ہے۔"],[9547,"§۱۰۹۳۷ ۔ بھیسہ بنت عامر\nبن خالدہ بن عامر بن مخلد انصاریہ زرقیہ۔ ابن سعد رحمہ اللہ نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔"],[9548,"§۱۰۹۳۸ ۔ بھیسہ الفزاریہ\n(1) ابن حبان نے فرمایا: انہیں شرف صحابیت حاصل ہے۔ ان کے والد ابو ٹھیہ کے سوانح میں کنیتوں کے بیان میں جو حدیث روایت کی ہے، اس کے اختلاف کا بیان گزر چکا ہے۔ اگر ابن حبان کا قول نہ ہوتا کہ انہیں شرف صحابیت حاصل ہے تو روایت میں ایسی کوئی بات نہیں جو ان کے صحابی ہونے پر دلالت کرے۔ ابن مندہ کی حدیث کا سیاق بتاتا ہے کہ ان کے والد نے اجازت طلب کی تھی۔ ابوداؤد اور نسائی کی حدیث میں ان کے والد سے روایت ہے کہ انہوں نے اجازت طلب کی تھی، اور وہی قابل اعتماد ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۷۶) تجرید (۲۵۲/۲)"}],[9549,"§۱۰۹۳۹ ۔ بُھَیمہ\n(1) تشدید کے ساتھ تصغیر ہے۔ بعض نے کہا: بھیمہ، میم کے ساتھ ہے، بنت بشر مازنیہ۔ ابوزرعہ دمشقی فرماتے ہیں: مجھ سے دُحیم نے کہا: “ایک گھرانے کے چار افراد کو شرف صحابیت حاصل ہے۔ بشر اور اس کے دونوں بیٹوں عبداللہ اور عطیہ کو اور ان کی بہن صماء کو۔” دارقطنی رحمہ اللہ نے فرمایا: صماء ان کا نام بُھیمہ ہے۔ ابو عمر نے ان کا ذکر کیا ہے اور فرمایا: انہوں نے نبی کریم صلی اللہ علیہ وسلم سے سوائے فرض روزوں کے ہفتے کے دن (نفل) روزے کی ممانعت کی حدیث روایت کی ہے، ان کے بھائی عبداللہ نے ان سے روایت کی، پھر ان سے ابوزرعہ دمشقی نے دو طریق سے مسند ذکر کی ہے، جو انہوں نے یحییٰ بن صالح سے اور انہوں نے محمد بن قاسم طائی سے روایت کی ہے۔ فرماتے ہیں: عبداللہ بن بشر کی بہن کا نام ایک روایت میں کھیمہ اور دوسری روایت میں ٹھیہ ہے۔ میں کہتا ہوں: ان کی حدیث نسائی نے نقل کی ہے، اور اپنی مسند میں راویوں کے اختلاف کے بیان میں دقت نظر سے کام لیا ہے۔ ان سب روایات میں ان کا نام صماء ہے، اور بعض طرق میں ان کی پھوپھی سے، اور بعض میں جن میں ان کی خالہ سے روایت ہے، ان کا نام نہیں لیا، بعض کے نزدیک ان کا نام جھیمہ یا ھجیمہ ہے، اور وہ غلط ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۷۷) تجرید (۲۵۲/۲)"}],[9550,"§۱۰۹۴۰ ۔ بُھیہ بنت عبداللہ\n(1) البکریہ۔ بکر بن وائل سے ہیں، اپنے والد کے ساتھ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں۔ فرماتی ہیں: آپ صلی اللہ علیہ وسلم نے مردوں سے بیعت لی اور ان سے مصافحہ کیا اور عورتوں سے بھی بیعت لی، لیکن ان سے مصافحہ نہیں کیا۔ فرماتی ہیں: آپ صلی اللہ علیہ وسلم نے مجھے دیکھا تو بلایا اور میرے سر پر ہاتھ پھیرا، اور میرے لیے اور میرے والدین کے لیے دعا کی، ان کی ساٹھ اولادیں ہوئیں جن میں سے چالیس مرد اور بیس عورتیں تھیں۔ ابو عمر(2) نے اسی طرح بغیر سند کے ذکر کیا ہے۔ باوردی نے عبدالرحمن بن عمرو بن جبلہ جو ایک متروک راوی ہیں، ان کی سند سے بحوالہ حبہ بنت متماخ مسند نقل کیا ہے۔ فرماتی ہیں: مجھ سے بُھیہ بنت عبداللہ بکریہ نے حدیث بیان کی، فرماتی ہیں: میں اپنے والد کے ساتھ آئی.... پھر حدیث ذکر کی اور اس کے آخر میں اضافہ کیا: ان میں سے بیس شہید ہو گئے ہیں۔ ابن مندہ(3) نے اسے بحوالہ باوردی نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۷۳) تجرید (۲۵۲/۲)\n(2) الاستيعاب (۱۷۹۸/۴)\n(3) جامع المسانيد والسنن (۳۲۷/۵۱)"}],[9551,"§۱۰۹۴۱ ۔ البیضاء الفہریہ\n(1) سہیل اور صفوان کی والدہ ہیں۔ یہ دونوں بیضاء کے بیٹے ہیں، ان کا نام دعد ہے۔ جیسا کہ بغیر نقطوں والے حرف دال میں آئے گا۔","",{"fn":"(1) اسد الغابہ (۶۷۷۹) تجرید (۲۵۲/۲)"}],[9552,"§۱۰۹۴۲ ۔ برکہ بنت النبی\nجس نے حافظ عبد الغنی کی کتاب رجال العمدۃ کو جمع کیا ہے، انہوں نے ان کا ذکر کیا ہے۔ پس کتاب کے شروع میں نبی کریم صلی اللہ علیہ وسلم کے سوانح میں ان کا کچھ تذکرہ ہے۔ پھر فرمایا: سیدہ خدیجہ رضی اللہ عنہا سے آپ کا بیٹا قاسم پیدا ہوا پھر برکتہ، پھر زینب، اس کے بعد رقیہ، پھر فاطمہ، پھر ام کلثوم پیدا ہوئیں۔ پھر فرمایا: ابن سعد نے اسی طرح ان کا ذکر کیا ہے۔ لیکن برکتہ کا ذکر نہیں کیا، جس نے اس بات کا ذکر کیا ہے اسے کسی کی طرف منسوب نہیں کیا، نہ ہی وہ مشہور ائمہ کی مشہور کتابوں میں سے کسی میں مذکور ہے۔ اللہ ہی کی توفیق سے سب کام ہوتے ہیں، احتمال ہے کہ اس میں بُھیہ بکریہ اور ٹھیہ فزاریہ کا ذکر کیا جائے۔"],[9553,"§۱۰۹۴۳ ۔ برزہ بنت رافع\nابن سعد(1) نے زینب بنت جحش کے حالات میں فرمایا: ہمیں یزید بن ہارون اور عبدالوہاب بن عطاء نے بحوالہ محمد بن عمرو خبر دی کہ مجھ سے یزید بن خصیفہ نے بحوالہ عبداللہ بن رافع حدیث بیان کی، انہوں نے برزہ بن رافع سے، انہوں نے عبداللہ بن رافع سے روایت کیا، فرماتے ہیں: جب حکومتی وظیفہ تقسیم ہوا تو سیدنا عمر رضی اللہ عنہ نے زینب بنت جحش کی طرف ان کا حصہ بنتا بھیجا، جب ان کے پاس لایا گیا، فرمانے لگیں: اللہ تعالیٰ عمر کی مغفرت کرے، میرے سوا دوسری بہنیں اس تقسیم کی مجھ سے زیادہ حقدار ہیں۔ انہوں نے کہا: یہ سارا آپ کے لیے ہے۔ فرمایا: “سبحان اللہ (اللہ پاک ہے؟) اور اس میں سے کچھ کپڑے سے ڈھانپ لیا، اور فرمایا: اس کو رکھ دو اور اس پر کپڑا ڈال دو پھر مجھ سے کہنے لگیں: اس میں اپنا ہاتھ ڈالو اور مٹھی بھر کر بنو فلاں کے پاس لے جاؤ اور بنو فلاں کے پاس جو ان کے رشتہ دار اور یتیم تھے، یہاں تک کہ اس میں سے کچھ کپڑے کے نیچے باقی رہ گیا، ان سے برزہ نے عرض کیا: اے ام المومنین! اللہ آپ کی مغفرت کرے، اللہ کی قسم! اس میں ہمارا حق بھی ہے۔ انہوں نے فرمایا: جو کچھ کپڑے کے نیچے ہے تمہارا ہے۔ ہم نے اس کے نیچے پچاسی درہم پائے، پھر انہوں نے آسمان کی طرف اپنے ہاتھ بلند کیے اور کہنے لگیں: اے اللہ! اس سال کے بعد عمر کا وظیفہ مجھے نہ ملے، پس وہ وفات پا گئیں۔","",{"fn":"(1) الطبقات الکبریٰ (۷۷/۸)"}],[9554,"§۱۰۹۴۴ ۔ بُثینہ\n(1) ث اور نون کی تصغیر کے ساتھ، بنت ضحاک۔ ابو نعیم نے ان کا ذکر حرف ب میں کیا ہے، ابو موسیٰ نے ان کا تعاقب کیا ہے کہ اکثر نے ان کا ذکر شروع میں ث کے ساتھ کیا ہے، جیسا کہ آگے آ رہا ہے۔ ابن اثیر(2) نے ابو موسیٰ کی پیروی کرتے ہوئے کہا ہے کہ حدیث میں ان کے صحابی ہونے کا ذکر نہیں ہے۔ میں کہتا ہوں: ابو عمر کو اعتماد ہے کہ انہیں دیدار حاصل ہے۔ جیسا کہ حرف ث کے بیان میں آئے گا۔","",{"fn":"(1) اسد الغابہ (۶۷۵۶) تجرید (۲۵۰/۲)\n(2) اسد الغابہ (۲۲۶/۵)"}],[9555,"§۱۰۹۴۵ ۔ بُجیدہ\n(1)(2) جیم کی تصغیر کے ساتھ، ابو عمر(3) فرماتے ہیں: ابن ابی خیثمہ نے اپنی سند کے ساتھ بحوالہ ابن ابو ذئب، انہوں نے مقبری سے، انہوں نے عبدالرحمن بن بحیدہ انہوں نے اپنی والدہ بحیرہ سے ذکر کیا ہے، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “سائل کو دو اگر چہ جلا ہوا کھر کیوں نہ ہو۔”(4) اسی طرح فرمایا: وہ ام بحیدہ ہیں۔ اور صحیح یوں ہے، بحوالہ عبدالرحمن بن ام بحیدہ، جو اپنی والدہ بحیرہ سے روایت کرتے ہیں جیسا کہ درست نام کنیتوں کے بیان میں آ رہا ہے۔","",{"fn":"(1) الاستيعاب (۱۷۴۳/۴)\n(2) اسد الغابہ (۶۷۵۷) تجرید (۲۵۰/۲)\n(3) الاستيعاب (۱۷۹۲/۴)\n(4) مسند احمد (۳۸۲/۶) جامع المسانيد والسنن (۳۱۵/۱۵)"}],[9556,"§۱۰۹۴۶ ۔ بدیلہ بنت مسلم\n(1) بعض نے کہا: اسلم، جعفر بن محمود بن محمد بن سلمہ، بدیلہ سے جو ان کی نانی فرماتی ہیں: ہمارے پاس عباد بن بشر آئے اور کہا: قبلہ تبدیل کر دیا گیا ہے۔ واقدی(2) نے اس کا ذکر کیا ہے۔ ابن مندہ نے اسے نقل کیا ہے اور ان کے نام میں غلطی کی ہے، جو تویلہ ت اور واؤ کے ساتھ آئے گا۔ بعض نے کہا: ان کے نام کے شروع میں نون ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۵۹) تجرید (۲۵۰/۲)\n(2) جامع المسانيد والسنن (۳۱۶/۱۵)"}],[9557,"§۱۰۹۴۷ ۔ برکہ بنت النبی\nدوسری قسم میں ان کا ذکر گزر چکا ہے، پھر مجھے پتہ چلا کہ وہ غلطی ہے جو تحریف سے پیدا ہوئی۔ برکہ نبی کریم صلی اللہ علیہ وسلم کی باندی تھیں جو سیدہ خدیجہ رضی اللہ عنہا سے آپ صلی اللہ علیہ وسلم کی اولاد کی پرورش کرتی تھیں۔ جب قاسم پیدا ہوئے تو ان کی آپ نے پرورش کی، گویا اس بارے میں جس مصنف نے نقل کیا ہے اسی طرح لکھ دیا ہے۔ یوں یہ لفظ اس کے سامنے تبدیل ہو گیا، اور اسے ان کی سگی بہن برکتہ سمجھ لیا۔ واللہ اعلم!"],[9558,"§۱۰۹۴۸ ۔ تُماضر بنت الاصبغ\nبن عمرو بن ثعلبہ کلبیہ۔ ان کے والد کے حالات میں ان کا نسب گزر چکا ہے جو صرف الف کی تیسری قسم میں ہے۔ بعض نے کہا: وہ تماضر بنت زبان بن اصبغ ہیں۔ ابن سعد(1) نے واقدی سے ذکر کیا ہے کہ ہم سے عبداللہ بن جعفر نے بحوالہ ابن عدی، انہوں نے صالح بن ابراہیم بن عبد الرحمن بن عوف سے بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم نے عبد الرحمن بن عوف کو بنو کلب کی طرف بھیجا اور فرمایا: “اگر وہ تمہاری دعوت کو قبول کر کے اسلام لے آئیں تو ان کے بادشاہ یا ان کے سردار کی بیٹی سے نکاح کر لینا۔” جب عبد الرحمن آئے تو انہیں اسلام کی طرف بلایا، انہوں نے اسے قبول کر لیا، اور جو جزیہ دینے پر راضی ہوا، اسے اس کے دین پر قائم رکھا، پس عبد الرحمن بن عوف نے تماضر بنت اصبغ بن عمرو جو ان کے بادشاہ کی بیٹی تھی، ان سے نکاح کر لیا، پھر انہیں مدینہ لے آئے، اور وہ ابی سلمہ بن عبد الرحمن بن عوف کی والدہ ہیں۔ ابن سعد رحمہ اللہ نے بحوالہ حماد بن زید، انہوں نے ایوب سے، اور انہوں نے سعد بن ابراہیم سے نقل کیا ہے، فرماتے ہیں: ابوسلمہ بن عبد الرحمن کی والدہ تماضر بنت اصبغ ہیں۔ عمر بن ابوسلمہ بن عبد الرحمن اپنے والد سے وہ اپنی دادی تماضر بنت زبان بن اصبغ سے روایت کرتے ہیں کہ جب عبد الرحمن بن عوف کی وفات کے بعد زبیر نے انہیں طلاق دے دی، وہ ان کے ساتھ سات سال رہا، پھر انہیں طلاق دے دی، وہ عورتوں سے کہتی تھیں: جب تم میں سے کوئی نکاح کرے تو سات سال کے بعد دھوکے میں نہ رہے، جیسا کہ زبیر نے میرے ساتھ کیا۔ محمد بن عمر فرماتے ہیں: وہ پہلی کلبی عورت ہیں جن کا نکاح قریشی سے ہوا، عبدالرحمن کی ان سے ابو سلمہ کے علاوہ اولاد نہ ہوئی۔ محمد بن سعد فرماتے ہیں کہ ہم سے یزید بن ہارون نے حدیث بیان کی، وہ فرماتے ہیں کہ ہم سے ابراہیم بن سعد نے بحوالہ اپنے والد اور وہ اپنے دادا سے روایت کرتے ہیں، فرماتے ہیں کہ تماضر میں کچھ برا اخلاق تھا اور انہیں دو طلاق ملی تھیں، جب عبدالرحمن بیمار ہوئے تو ان دونوں کے درمیان کچھ رنجش ہوگئی تھی، تو انہوں نے ان سے کہا: اللہ کی قسم! اگر تم مجھ سے طلاق مانگو تو میں تمہیں طلاق دے دوں گا۔ وہ کہنے لگی: اللہ کی قسم! میں آپ سے اس کا سوال کرتی ہوں۔ انہوں نے کہا: ابھی نہیں، جب تمہیں حیض آئے اور پھر پاک ہو جاؤ تو مجھے بتانا۔ جب انہیں حیض آیا اور پاک ہوئیں تو ان کو بتانے کے لیے پیغام بھیجا، فرماتے ہیں، ان کا قاصد ان کے کسی رشتہ دار کے پاس سے گزرا تو اس نے پوچھا: کہاں جا رہے ہو؟ قاصد نے کہا: مجھے تماضر نے عبدالرحمن کے پاس بھیجا ہے تا کہ میں انہیں بتاؤں کہ انہیں حیض آیا پھر پاک ہوگئی ہیں۔ انہوں نے کہا: ان کے پاس واپس جاؤ اور کہو ایسا نہ کریں، اللہ کی قسم! وہ اپنی قسم کو رد نہیں کرتے۔ تو انہوں نے کہا: اللہ کی قسم! میں اپنی قسم کو رد نہیں کروں گی۔ فرماتے ہیں: انہوں نے انہیں بتایا تو انہیں طلاق دے دی۔ ابن نمیر نے محمد بن اسحاق سے، انہوں نے سعد بن ابراہیم سے، انہوں نے اپنے والد سے، انہوں نے اپنی دادی ام کلثوم سے روایت کی ہے، فرماتی ہیں: جب عبدالرحمن نے اپنی بیوی تماضر جو قبیلہ بنو کلب سے تھیں طلاق دی تو انہیں حبشی باندی نفع اٹھانے کے لیے دی۔ محمد بن مصعب رحمہ اللہ، اوزاعی رحمہ اللہ سے، اور وہ زہری رحمہ اللہ سے، وہ طلحہ بن عبد اللہ سے روایت کرتے ہیں کہ سیدنا عثمان رضی اللہ عنہ نے تماضر بنت اصبغ کو عبد الرحمن کا وارث قرار دیا، انہوں نے مرض وفات میں انہیں طلاق دی تھی، جو ان کی آخری طلاق تھی۔ ایوب کی سند سے جس میں انہوں نے نافع اور سعد بن ابراہیم سے روایت کیا ہے۔ مروی ہے کہ انہوں نے انہیں تین طلاق دیں، عدت پوری ہونے کے بعد سیدنا عثمان رضی اللہ عنہ نے انہیں وارث قرار دیا۔","",{"fn":"(1) الطبقات الکبریٰ (۲۱۸/۸)"}],[9559,"§۱۰۹۴۹ ۔ تماضر بنت عمرو\n(1) بن شرید سلمیہ، یہ خنساء شاعرہ ہیں۔ ان کا ذکر حرف خاء نقطہ والے میں آئے گا۔","",{"fn":"(1) اسد الغابہ (۶۷۸۰) تجرید (۲۵۲/۲)"}],[9560,"§۱۰۹۵۰ ۔ تماضر العبدریہ الشیبیہ\n(1) بنو شیبہ بن عثمان سے ہیں، ان کا شمار اہل مکہ میں ہے۔ صفیہ بنت شیبہ نے ان سے سعی کی حدیث نقل کی، یہ ابو عمر کا قول ہے۔ ابن ابو عاصم، عقیلی اور ابن مندہ نے ان کی حدیث مثنی بن عمرو کے طریق سے نقل کی ہے۔ روایت کرتی ہیں کہ نبی کریم صلی اللہ علیہ وسلم صفا و مروہ کے درمیان سعی کر رہے تھے اور کہہ رہے تھے: “اے لوگو! اللہ تعالیٰ نے تم پر سعی لازم کی ہے پس سعی کرو۔(2)” امام ابن مندہ فرماتے ہیں کہ اسے عطاء نے صفیہ سے بحوالہ حبیبہ روایت کیا ہے۔ میں کہتا ہوں: اس کا ذکر حبیبہ بنت ابو تجراۃ میں ان شاء اللہ تعالیٰ آئے گا۔","",{"fn":"(1) اسد الغابہ (۶۷۸۱) تجرید (۲۵۳/۲)\n(2) الاحاد والمثانی (۲۲۲/۶)"}],[9561,"§۱۰۹۵۱ ۔ تمیمہ بنت ابی سفیان\n(1) بن قیس اشہلیہ۔ ابن سعد(2) اور ابن حبیب نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ لیلیٰ بنت تعلیم کے حالات میں ان کا ذکر آئے گا۔","",{"fn":"(1) اسد الغابہ (۶۷۸۲) تجرید (۲۵۳/۲)\n(2) الطبقات الکبریٰ (۲۵۳/۸)"}],[9562,"§۱۰۹۵۲ ۔ تمیمہ بنت وہب\n(1) رفاعہ بن سموال کے ساتھ ان کا قصہ جو حدیث عسیلہ(2) میں ہے، موطا مالک(3) کی روایت سے ہے، میں اس کے علاوہ نہیں جانتا۔ ابن عبدالبر نے اسی طرح کہا ہے۔ ابن مندہ فرماتے ہیں: تمیمہ بنت ابوعبید رفاعہ القرظی کی خاتون ہیں، پھر سفیان کے طریق سے بحوالہ زہری، انہوں نے عروہ سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے حدیث روایت کی ہے کہ رفاعہ قرظی کی خاتون عبد الرحمن بن زبیر کی زوجہ تھی، اور ان کا نام نہیں لیا، جبکہ قتادہ نے ان کا نام لیا ہے، پھر سعید بن ابوعروبہ بحوالہ قتادہ حدیث روایت کی ہے کہ تمیمہ بنت ابوعبید قرظیہ رفاعہ یا رافع قرظی کی بیوی تھی، انہوں نے اسے طلاق دی، پھر قصہ ذکر کیا۔ رہی مالک کی وہ روایت جس کی طرف ابو عمر(4) نے اشارہ کیا، فرماتے ہیں: مسور بن رفاعہ روایت کرتے ہیں کہ انہوں نے زبیر بن عبد الرحمن بن زبیر سے سنا کہ رفاعہ بن سموال نے اپنی بیوی تمیمہ بنت وہب کو طلاق دی.... پھر ساری حدیث ذکر کی۔ رفاعہ کے سوانح میں اس پر بحث گزر چکی ہے۔ محمد بن اسحاق نے اس کی مخالفت کی ہے۔ اور اسے ہشام بن عروہ سے بحوالہ ان کے والد روایت کیا ہے اور اسے پلٹ دیا ہے۔ فرماتے ہیں: بنوقریظہ کی خاتون جسے تمیمہ کہا جاتا تھا عبدالرحمن بن زبیر کی بیوی تھی، انہوں نے ان کو طلاق دے دی، پھر رفاعہ نے ان سے نکاح کر لیا، پھر ان کو طلاق دے دی، تو انہوں نے عبدالرحمن کے پاس لوٹنا چاہا.... (الحدیث) ابو نعیم نے اسے نقل کیا ہے، بعض نے کہا کہ ان کا نام تحکیمہ ہے، جیسا کہ آگے آئے گا۔ بعض کا قول ہے: عائشہ ہے، اور رفاعہ کے سوانح میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۸۳) تجرید (۲۵۳/۲)\n(2) بخاری (الحديث: ۵۲۵۶)\n(3) موطا مالک (الحدیث: ۱۷، ۱۸)\n(4) الاستيعاب (۱۷۹۸/۴)"}],[9563,"§۱۰۹۵۳ ۔ ثَہناۃ\nہمزہ زبر والا اور اس کے بعد نون، بنت کلیب حضرمیہ، ان کے والد کلیب بن اسد کے سوانح میں ان کا ذکر گزر چکا ہے۔"],[9564,"§۱۰۹۵۴ ۔ التوأمہ\n(1) جو ان سے پہلے نام ہے اس کے وزن پر ہے۔ بنت امیہ بن خلف جمحیہ، صالح بن ابوصالح کی باندی ہیں جو توأمہ کے غلام ہیں، بعض نے کہا: ان کا یہ نام اس وجہ سے ہے کہ وہ اپنی بہن کے ساتھ جڑواں پیدا ہوئیں۔ باوردی نے فرمایا: ہم سے مُطیّن نے بیان کیا وہ فرماتے ہیں کہ میں عبداللہ بن حکم بن ابوزید کو فرماتے ہوئے سنا: صالح توأمہ بنت امیہ بن خلف جمحیہ کا غلام تھا۔ (توأمہ نے) نبی کریم صلی اللہ علیہ وسلم سے بیعت کی۔ ابن سعد(2) فرماتے ہیں: ان کی والدہ لیلیٰ بنت حبیب تمیمیہ تھیں۔ توأمہ نے خاندان سے باہر عاصم بن جعد فزاری سے شادی کی۔ پھر جید سند سے نقل کیا ہے، لیکن اس میں واقدی ہیں، پھر سلیمان بن یسار سے روایت کرتے ہیں کہ توأمہ کو طلاق مغلظہ دی گئی، انہوں نے سیدنا عمر رضی اللہ عنہ سے اس بارے میں پوچھا تو انہوں نے اسے ایک طلاق قرار دیا۔","",{"fn":"(1) اسد الغابہ (۶۷۸۴) تجرید (۲۵۳/۲)\n(2) الطبقات الکبریٰ (۱۹۷/۸)"}],[9565,"§۱۰۹۵۵ ۔ تویلہ\n(1) تصغیر کے ساتھ ہے۔ بنت اسلم، طبرانی(2) میں ان کی حدیث ابراہیم بن حمزہ زبیری کے طریق سے مروی ہے بحوالہ ابراہیم بن جعفر بن محمود بن محمد بن سلمہ وہ اپنے والد سے اور وہ اپنی دادی سے جو ان کی والدہ ہیں، روایت کرتے ہیں: تویلہ بنت اسلم، اور وہ بیعت کرنے والی خواتین میں سے تھیں، فرماتی ہیں: اسی اثناء میں کہ میں بنو حارثہ میں تھی، عباد بن بشر بن قیظی نے کہا: نبی کریم صلی اللہ علیہ وسلم نے بیت الحرام کو قبلہ بنا لیا ہے۔ تو مرد عورتوں کی جگہ اور عورتیں مردوں کی جگہ آگئیں، انہوں نے باقی دو سجدے کعبہ کی طرف ادا کیے۔ ابو عمر نے ذکر کیا ہے: وہ ظہر کی نماز تھی، اور ان کے بارے میں بعض کا قول ہے: تولیہ بغیر تصغیر کے ہے۔ اور بعض نے کہا: اس کے شروع میں نون ہے، عنقریب اس کا ذکر آئے گا۔","",{"fn":"(1) اسد الغابہ (۶۷۸۵) تجرید (۲۵۳/۲)\n(2) المعجم الکبیر (۵۳۰/۲۴)"}],[9566,"§۱۰۹۵۶ ۔ ثبیتہ\n(1) ث کے ساتھ، پھر ب پھر ت، تصغیر ہے۔ بنت ربیع بن عمرو بن عدی بن زید بن جشم بن حارثہ انصاریہ۔ ابو قیس بن جبر کی والدہ ہیں۔ ابن حبیب کا قول ہے کہ نبی کریم صلی اللہ علیہ وسلم سے بیعت کی، ابن سعد نے فرمایا: ان کی والدہ سہلہ بنت امرئ القیس بن کعب ہیں، اور ان سے اوس بن قیظی نے نکاح کیا جس سے عرابہ، عبداللہ اور کہانہ(2) پیدا ہوئے۔","",{"fn":"(1) اسد الغابہ (۶۷۸۶) تجرید (۲۵۳/۲)\n(2) الطبقات الکبریٰ (۲۴۰/۸)"}],[9567,"§۱۰۹۵۷ ۔ ثبیتہ بنت سلیط\n(1) بن قیس بن عمرو بن عبید انصاریہ نجاریہ، ابن سعد(2) نے بیعت کرنے والی خواتین میں ان کا ذکر کیا ہے اور فرمایا ان کی والدہ نخیلہ بنت صمہ ہیں، اور وہ عبد الرحمن بن عبد اللہ بن ابو صعصعہ کی والدہ ہیں اور قتیلہ اور میمونہ کی بہن ہیں۔","",{"fn":"(1) اسد الغابہ (۶۷۸۷) تجرید (۲۵۳/۲)\n(2) الطبقات الکبریٰ (۳۰۹/۸)"}],[9568,"§۱۰۹۵۸ ۔ ثبیتہ بنت النعمان\n(1) بن عمرو بن خلدہ بن عمرو بن امیہ بن عامر بن بیاضہ انصاریہ بیاضیہ، ابن سعد رحمہ اللہ(2) فرماتے ہیں: اسلام لائیں اور بیعت کی، انہیں ان کے والد اور ان کے دادا کو شرف صحابیت حاصل ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۸۹) تجرید (۲۵۳/۲)\n(2) الطبقات الکبریٰ (۲۸۲/۸)"}],[9569,"§۱۰۹۵۹ ۔ ثبیتہ بنت النعمان الانصاریہ\nبنو تجھی سے ہیں، ابن حبیب کا قول ہے کہ اسلام لائیں اور بیعت کی۔ انہوں نے ان کا ذکر ان سے پہلی صحابیہ سے ملا دیا ہے۔ اور بنو تجھی بنو بیاضہ سے نہیں ہیں۔"],[9570,"§۱۰۹۶۰ ۔ ثبیتہ بن یعار\n(1) نیچے دو نقطے ہیں، اس کے بعد عین بغیر نقطوں کے بغیر شد کے۔ بن زید بن عبید بن زید بن مالک بن عوف بن عمرو بن عوف انصاریہ اوسیہ، ابو حذیفہ بن عتبہ بن ربیعہ کی بیوی ہیں، یہ وہی ہیں جنہوں نے سالم کو جو ابو حذیفہ کا غلام تھا، آزاد کیا۔ ابو حذیفہ کے سوانح میں ان کا ذکر گزر چکا ہے۔ مصعب زبیری اور ایک جماعت نے ان کا یہ نام لیا ہے۔ جبکہ موسیٰ بن عقبہ نے بحوالہ ابن شہاب زہری ان کا نام سُہیلیٰ لیا ہے، اسی طرح ابن اسحاق نے اپنی روایت میں فرمایا، اور ابوطوالہ نے ان کا نام عمرہ لیا ہے۔ رہے ان کے والد تو موسیٰ بن عقبہ کے قول کے مطابق اوپر دو نقطوں کے ساتھ ہے۔ ابراہیم بن منذر نے پہلے قول کو صحیح قرار دیا ہے۔ یہ سب ابو عمر(2) رحمہ اللہ سے مروی ہے۔ ان کے نام کے بارے میں دو اور قول گزر چکے ہیں۔ لیلیٰ اور فاطمہ، ابو عمر کا قول ہے: اولین ہجرت کرنے والیوں میں سے تھیں، اور صحابہ کی عورتوں میں سے علم و فضل والی تھیں۔ میں کہتا ہوں: اس قول میں کہ وہ مہاجرات میں سے ہیں، تامل ہے، کیونکہ ان کا نسب انصار میں ہے۔ اور اس قول میں کہ وہ ابو حذیفہ کی زوجہ ہیں، دوسرا تردد ہے۔ ابو حذیفہ کے سوانح میں گزر چکا ہے کہ ان کی زوجہ جنہیں دودھ پلانے کا کہا گیا تھا، وہ بڑی عمر کی تھیں اور ان کا نام سہلہ بنت سہیل انصاریہ تھا، مگر اس صورت میں کہ کہا جائے کہ ان کی دو بیویاں تھیں، ایک جنہوں نے سالم کو آزاد کیا اور دوسری جنہیں دودھ پلانے کا حکم دیا گیا، اور یہ احتمال بعید ہے۔ اللہ کو ہی اس کا علم ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۹۰) تجرید (۲۵۳/۲)\n(2) الاستيعاب (۱۷۹۹/۴)"}],[9571,"§۱۰۹۶۱ ۔ ثویبہ\n(1) یہ وہی ہیں جنہوں نے نبی کریم صلی اللہ علیہ وسلم کو دودھ پلایا تھا، ابولہب کی باندی ہیں۔ ابن مندہ نے ان کا ذکر کیا ہے، اور فرمایا: ان کے اسلام میں اختلاف ہے۔ ابو نعیم فرماتے ہیں: مجھے معلوم نہیں کہ کسی نے ان کا اسلام لانا ثابت کیا ہو۔ طبقات ابن سعد(2) کے باب من ارضع النبی صلی اللہ علیہ وسلم میں ایسی روایت ہے جو اس پر دلیل ہے کہ وہ اسلام نہیں لائیں، لیکن اس سے ابن مندہ کے قول کو رد نہیں کیا جا سکتا۔ ابن سعد نے برہ بنت ابو تجراۃ کے طریق سے نقل کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم کو سب سے پہلے ثویبہ نے اپنے بیٹے کے ساتھ دودھ پلایا، اس کا نام مسروح ہے۔ یہ حلیمہ رضی اللہ عنہا کے آنے سے چند روز قبل کا قصہ ہے۔ آپ صلی اللہ علیہ وسلم سے پہلے حمزہ کو اور بعد میں ابو سلمہ بن عبدالاسد کو دودھ پلایا۔ ابن سعد فرماتے ہیں کہ ہمیں واقدی نے کئی ایک اہل علم سے روایت کی، وہ کہتے ہیں کہ ثویبہ نے نبی کریم صلی اللہ علیہ وسلم کو دودھ پلایا۔ آپ صلی اللہ علیہ وسلم ان کے لیے تحفہ عطیہ بھیجتے تھے، وہ اس وقت مکہ میں ہی تھیں۔ سیدہ خدیجہ رضی اللہ عنہا ان کی عزت کرتی تھیں، اور اس وقت وہ ابو لہب کی باندی تھیں۔ سیدہ خدیجہ رضی اللہ عنہا نے کہا کہ وہ اسے ان کے ہاتھ بیچ دیں، لیکن اس نے انکار کر دیا، جب رسول اللہ صلی اللہ علیہ وسلم نے ہجرت کی تو ابولہب نے انہیں آزاد کر دیا۔ نبی کریم صلی اللہ علیہ وسلم انہیں عطیہ اور کپڑے بھیجتے تھے۔ یہاں تک کہ سات ہجری میں جب خیبر سے واپس آئے تو اطلاع ملی کہ وہ فوت ہوگئی ہیں۔ ان کا بیٹا مسروح اس سے پہلے ہی فوت ہو چکا تھا۔ میں کہتا ہوں: میں روایات میں سے کسی ایسی شے سے واقف نہیں جس سے پتہ چلتا ہو کہ ان کا بیٹا مسروح اسلام لایا تھا، اور اس کا احتمال ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۹۱) تجرید (۲۵۳/۲)\n(2) الطبقات الکبریٰ (۲۵۵/۸)"}],[9572,"§۱۰۹۶۲ ۔ ثبیتہ بنت الضحاک\nبن خلیفہ ابو عمر فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں پیدا ہوئیں، قاضی اسماعیل بن اسحاق نے جو علی بن مدینی سے نقل کیا ہے اس میں وہ فرماتے ہیں: ابو جبیرہ اور ثابت جو دونوں الضحاک کے بیٹے اور انصاری ہیں، ان کی بہن ہیں۔ ابو عمر فرماتے ہیں: ب کے بجائے ان کے ساتھ ان کا نام لکھا ہے۔ اس میں متفرد ہیں۔ میں کہتا ہوں: ابو نعیم نے نقطے والی ب میں ان کا ذکر کیا ہے، اور ھاء سے پہلے نون ہے۔ ابو موسیٰ نے بیان کیا ہے کہ انہوں نے اس بارے میں ابن مندہ کا تاریخ میں اتباع کیا ہے۔ اور ان کا صحابہ رضی اللہ عنہم میں ذکر نہیں کیا۔ اور مشہور ہے کہ وہ ث کے ساتھ ہے۔ یہ ابو موسیٰ کا قول ہے۔ محمد بن سلیمان بن ابو حثمہ اپنے چچا سہل بن ابو حثمہ سے روایت کرتے ہیں، فرماتے ہیں: میں محمد بن سلمہ کے پاس بیٹھا ہوا تھا۔ وہ اپنی چھت پر تھے، ثبیتہ بنت ضحاک کو کنکھیوں سے دیکھ رہے تھے، وہ اس کی طرف دیکھنے لگے۔ میں نے کہا: سبحان اللہ، آپ ایسا کر رہے ہیں حالانکہ آپ رسول اللہ صلی اللہ علیہ وسلم کے ساتھی ہیں۔ کہنے لگے، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: “جب اللہ تعالیٰ کسی آدمی کے دل میں کسی عورت کو پیغام دینے کا خیال ڈال دے تو اسے دیکھ لینے میں کوئی حرج نہیں ہے۔” میں کہتا ہوں: ترمذی(1) نے اسے نقل کیا ہے اور ابو موسیٰ نے اس کے طرق کی تخریج اور اس کے اختلاف کے بیان میں دقت نظر سے کام لیا ہے، اور جو کچھ یہاں ذکر ہوا اسے ترجیح دی ہے، ابو موسیٰ ذیل میں فرماتے ہیں: ان کا ذکر محمد بن مسلمہ کی حدیث میں ہوا لیکن اس میں ان کے صحابیہ ہونے کا ذکر نہیں ہیں۔ میں کہتا ہوں: میں نے ابو عمر کے قول پر اعتماد کرتے ہوئے یہاں ان کا ذکر کیا ہے۔","",{"fn":"(1) ترمذی (۱۰۸۷)"}],[9573,"§۱۰۹۶۳ ۔ جثامہ\n(1) ث مشدد ہے۔ نبی کریم صلی اللہ علیہ وسلم نے ان کا نام تبدیل کر دیا اور ان کا نام خنساء رکھا، ان کا ذکر حاء بغیر نقطوں والی میں آئے گا۔","",{"fn":"(1) اسد الغابہ (۶۷۹۲) تجرید (۲۵۴/۲)"}],[9574,"§۱۰۹۶۴ ۔ جدامہ بنت جندل\n(1) ابن اسحاق(2) نے ان کا ذکر بنو غنم بن دودان بن اسد بن خزیمہ کی ہجرت کرنے والی خواتین میں ذکر کیا ہے۔ اہل مکہ سے ہیں، جو بنو عبد الشمس کے حلیف ہیں۔ طبرانی نے ذیل میں ذکر کیا ہے کہ یہ بنت وہب ہیں جن کا ذکر آ رہا ہے۔ محدثین جو عرب ہیں، فرماتے ہیں: یہ بنت وہب ہیں۔ ابن سعد(3) فرماتے ہیں: مکہ میں بہت پہلے اسلام لے آئیں۔ بیعت کی اور مدینہ کی طرف ہجرت کی، انیس بن قتادہ انصاری کی زوجہ تھیں، جو اوسی تھے، بدری صحابی ہیں جو اُحد میں شہید ہوئے۔ ابن عبدالبر نے ان کی پیروی کی ہے۔ بعض کا قول ہے: انیس بن قتادہ کی زوجہ خنساء بنت خدام تھیں، ہو سکتا ہے کہ وہ دونوں ان کی بیویاں ہوں۔","",{"fn":"(1) اسد الغابہ (۶۷۹۴) تجرید (۲۵۴/۲)\n(2) السیرۃ النبویۃ (۸۸/۲)\n(3) الطبقات الکبریٰ (۱۷۷/۸)"}],[9575,"§۱۰۹۶۵ ۔ جدامہ بنت الحارث\n(1) حلیمہ جو نبی کریم صلی اللہ علیہ وسلم کو دودھ پلاتی تھیں، ان کی بہن ہیں۔ ان کا لقب شیماء ہے۔ ان کی کوئی روایت معلوم نہیں۔ ابن مندہ نے ان کا ذکر کیا ہے۔ اور ابن اثیر نے ان کا تعارف کیا ہے کہ شیماء بنت حلیمہ ان کی بہن نہیں ہیں، جیسا کہ ان کے ذکر میں آئے گا، وہ نبی کریم صلی اللہ علیہ وسلم کی بہن ہیں، خالہ نہیں۔ میں کہتا ہوں: جو کچھ ابن مندہ نے ذکر کیا ہے اگر وہ محفوظ ہے تو احتمال ہے کہ حلیمہ کی بیٹی کا نام ان کی خالہ کے نام پر رکھا جائے اور ان کا لقب اس جیسا ہو، ان کا اس پر اتفاق نہیں کہ شیماء کا نام جدامہ (جیم اور میم سے) ہے۔ ابو عمر نے اس پر یقین دہانی کی ہے کہ وہ حذافہ (ہائے بے نقطی اور ف سے) ہیں، اور ابن سعد نے پہلے قول پر اعتماد کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۹۵) تجرید (۲۵۴/۲)"}],[9576,"§۱۰۹۶۶ ۔ جدامہ بنت وہب الاسدیہ\n(1) بعض نے کہا: نقطے والی خاء کے ساتھ، نبی کریم صلی اللہ علیہ وسلم سے حاملہ کے دودھ پلانے کے بارے میں حدیث روایت کی، ان سے ام المومنین سیدہ عائشہ رضی اللہ عنہا نے روایت کی، ان کی حدیث موطا میں ہے۔ اور اس کے الفاظ یہ ہیں: جُدامہ اسدیہ سے روایت ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کو فرماتے سنا: \"میں نے لوگوں کو غیلہ (دودھ پلانے کے دوران صحبت) سے منع کرنے کا ارادہ کر لیا تھا۔۔۔۔۔\" (الحدیث) مسلم(2) کے بعض طرق میں ہے: سیدہ جُدامہ بنت وہب جو عکاشہ بن وہب کی بہن ہیں، فرماتی ہیں: میں کچھ لوگوں کے ساتھ نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی، اور آپ صلی اللہ علیہ وسلم فرما رہے تھے۔۔۔۔۔۔ پھر انہوں نے حدیث ذکر کی، اس میں عزل کا ذکر کیا، یہ خفیہ دختر کشی ہے۔ ابن مندہ نے موطا کے الفاظ کے ساتھ جو جدامہ بنت جندل سے مروی ہے نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۹۶) تجرید (۲۵۴/۲)\n(2) مسلم (الحدیث: ۳۵۲۹)"}],[9577,"§۱۰۹۶۷ ۔ الجرباء بنت قسامہ\n(1) بن قیس بن عبید بن طریف بن مالک۔ حنظلہ کی بہن ہیں۔ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں، آپ صلی اللہ علیہ وسلم نے طلحہ بن عبید اللہ سے ان کا نکاح کیا۔ ام اسحاق بنت طلحہ کی والدہ ہیں۔ ان کا ذکر ان کی بہن زینب(2) کے حالات میں آئے گا۔","",{"fn":"(1) اسد الغابہ (۶۷۹۷) تجرید (۲۵۴/۲)\n(2) الاستيعاب (۱۸۵۲/۴)"}],[9578,"§۱۰۹۶۸ ۔ جعدہ بنت عبید\n(1) بن ثعلبہ بن غنم بن مالک بن نجار انصاریہ۔ ابو علی جیانی نے ابو عمر کی کتاب میں اپنے استدراک میں ان کا ذکر کیا ہے۔ عدوی کی کتاب نسب الانصار سے منقول ہے کہ نبی کریم صلی اللہ علیہ وسلم ان کے گھر تشریف لاتے تھے، اور ان کے پاس کھانا کھاتے تھے۔(2) یہ ام حارثہ بن نعمان ہیں، جن کے بھائی حارث بن حباب بن ارقم ہیں، جعدہ کے بھائی عمرو بن عبید بن ثعلبہ کو شرف صحابیت حاصل ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۹۹) تجرید (۲۵۴/۲)\n(2) الطبقات الکبریٰ (۳۲۴/۸)"}],[9579,"§۱۰۹۶۹ ۔ جعدہ بنت عبید\n(1) بن ثعلبہ بن سواد بن غنم بن حارثہ انصاریہ۔ ابن حبیب کا قول ہے کہ نبی کریم صلی اللہ علیہ وسلم سے بیعت کی، ابن اثیر نے اپنے استدراک میں ان کا ذکر کیا ہے۔(2) میں کہتا ہوں: ابن سعد نے ان کا ذکر کیا ہے،(3) اور کہا ہے ان کی والدہ رعاة بنت عدی بن سواد ہیں، ان سے نعمان بن شفیع نے نکاح کیا جن سے مشہور صحابی حارثہ پیدا ہوئے، اس کے بعد حباب بن ارقم نے ان سے نکاح کیا، جس سے حارث پیدا ہوئے، جعدہ اسلام لائیں اور بیعت کی۔","",{"fn":"(1) اسد الغابہ (۶۷۹۹) تجرید (۲۵۴/۲)\n(2) اسد الغابہ (۴۱۵/۵)\n(3) الطبقات الکبریٰ (۳۲۲/۸)"}],[9580,"§۱۰۹۷۰ ۔ جلیلہ بنت عبد الجلیل\nابوسعید نیشاپوری نے شرف مصطفیٰ نامی کتاب میں ان کا ذکر کیا ہے اور ان کی حدیث کو نقل کیا ہے۔ فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا۔ ہم نے چھوٹا کنواں کھودا تو اس میں حشرات اور کیڑے مکوڑے تھے، انہیں پانی کا برتن دیا گیا، آپ صلی اللہ علیہ وسلم نے فرمایا: پانی اس میں ڈال دو، فرماتی ہیں: ہم نے پانی کنوئیں میں ڈال دیا، کیڑے مکوڑے مر گئے اور جو بچ گئے وہ چلے گئے، اس سند میں کلام ہے۔"],[9581,"§۱۰۹۷۱ ۔ جُمانہ\n(1) اس کے شروع میں پیش اور میم کی تخفیف کے ساتھ ہے، اور الف کے بعد نون ہے۔ ابو طالب کی صاحبزادی ہیں، ابواحمد عسکری فرماتے ہیں: یہ ام عبداللہ بن ابوسفیان بن حارث بن عبدالمطلب ہیں۔ دار قطنی نے کتاب الاخوہ میں ایسا ہی لکھا ہے۔ ابوسفیان بن حارث نے ان سے نکاح کیا جس سے عبداللہ پیدا ہوئے، یہ بغیر سند کے ہے۔ زبیر بن بکار فرماتے ہیں: ام ھانی کی بہن ہیں، ابن اسحاق(2) نے ان کا ذکر ان لوگوں میں کیا ہے، جن میں نبی کریم صلی اللہ علیہ وسلم نے خیبر سے تیس وسق تقسیم کیے تھے۔ فاکہی نے کتاب مکہ میں عبداللہ بن عثمان بن خثیم کے طریق سے نقل کیا ہے، فرماتے ہیں: میں نے عطاء، مجاہد اور ابن کثیر اور بہت سے لوگوں کو پایا کہ رمضان المبارک کی ستائیسویں رات تنعیم میں پہنچ کر خیمہ جمانہ سے عمرے کا احرام باندھا اور وہ بنت ابو طالب ہیں۔ ابن سعد(3) نے ان کی والدہ فاطمہ بنت اسد کے حالات میں ان کا ذکر کیا ہے۔ اور نبی کریم صلی اللہ علیہ وسلم کی چچا زاد خواتین میں ان کا علیحدہ ذکر کیا ہے۔ اور فرماتے ہیں، ابوسفیان بن حارث کے ان سے بیٹے جعفر بن ابوسفیان ہوئے، رسول اللہ صلی اللہ علیہ وسلم نے خیبر سے تیس وسق کھجوریں انہیں کھانے کے لیے دیں۔","",{"fn":"(1) اسد الغابہ (۶۸۰۱) تجرید (۲۵۴/۲)\n(2) السیرۃ النبویۃ (۲۷۲/۳)\n(3) الطبقات الکبریٰ (۳۲/۸)"}],[9582,"§۱۰۹۷۲ ۔ جمرہ بنت الحارث\nبن عوف، وہ برصاء ہیں، ان کا ذکر گزر چکا ہے۔"],[9583,"§۱۰۹۷۳ ۔ جمرہ بنت عبداللہ\n(1) تمیمیہ، یربوعیہ، بنو یربوع بن حنظلہ بن مالک بن زید مناة بن تمیم سے ہیں۔ ابن مندہ فرماتے تھے: ان کا شمار اہل کوفہ میں ہے۔ انہیں اور ان کے والد کو شرف صحابیت حاصل ہے۔ حسن بن سفیان اور ابو یعلیٰ نے اپنی اپنی مسند میں عطوان بن مشکان کے طریق سے ان کی حدیث کا ذکر کیا ہے (وہ عین اور طاء کے زبر کے ساتھ ہے۔ بعض کا قول ہے: پہلے حرف کے پیش اور دوسرے حرف کے سکون کے ساتھ اور ان کے والد کا نام میم کے پیش اور ش کے سکون کے ساتھ ہے)۔ جمرہ بنت عبداللہ یربوعیہ فرماتی ہیں: میرے والد مجھے نبی کریم صلی اللہ علیہ وسلم کے پاس لے گئے، اور عرض کیا: میری بیٹی کے لیے اللہ تعالیٰ سے برکت کی دعا کر دیجئے۔ فرماتی ہیں: آپ صلی اللہ علیہ وسلم نے مجھے اپنی گود میں بٹھا کر سر پر ہاتھ پھیرا اور میرے لیے برکت کی دعا کی۔(2) عبداللہ نامی اشخاص کے آخر میں ان کے والد کے سوانح میں ان کا ذکر گزر چکا ہے۔ ابو عمر(3) فرماتے ہیں: ان کی حدیث میں اختلاف ہے۔ وہ سند کے لحاظ سے صحیح نہیں، اسی طرح فرمایا: اس میں عطوان نام ہے اور ان کے بارے میں ابن معین نے فرمایا: ان میں کوئی حرج نہیں۔","",{"fn":"(1) اسد الغابہ (۶۸۰۲) تجرید (۲۵۵/۲)\n(2) طبرانی (۵۳۷/۲۴) مجمع الزوائد (۲۶۶/۹) جامع المسانید والسنن (۳۴۳/۱۵)\n(3) الاستيعاب (۱۸۰۱/۴)"}],[9584,"§۱۰۹۷۴ ۔ جمرہ بنت قحافہ الکندیہ\n(1) ابن مندہ فرماتے ہیں: اہل کوفہ میں ان کا شمار ہے، ان سے شبیب بن غرقدہ نے روایت کی۔ ابو عمر(2) فرماتے ہیں: ان سے ان کی صاحبزادی ام کلثوم نے روایت کی، اگر وہ حدیث صحیح ہے، کیونکہ اس کی سند کی کوئی پرواہ نہیں۔ رہی حدیث شبیب جو ان سے مروی ہے، طبرانی(3) وغیرہ نے بشر بن ولید کے طریق سے نقل کیا ہے۔ فرماتے ہیں: ہم سے حسن بن قارب نے بحوالہ شعیب بن غرقدہ بیان کیا، وہ فرماتے ہیں: مجھ سے جمرہ بنت قحافہ نے حدیث بیان کی، وہ فرماتی ہیں، میں حجتہ الوداع کے موقع پر ام سلمہ رضی اللہ عنہا کے ساتھ تھی، میں نے نبی کریم صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"اے میری اُمت! کیا میں نے تم تک پہنچا دیا؟\" فرماتی ہیں: ان کے کسی بیٹے نے ان سے کہا: امی جان! آپ صلی اللہ علیہ وسلم کو کیا ہوا تھا کہ اپنی والدہ کو بلا رہے تھے؟ انہوں نے کہا: اے بیٹے! وہ تو اپنی اُمت کو بلا رہے تھے اور فرما رہے تھے: \"خبردار! تمہاری عزتیں اور تمہارے خون تمہارے لیے اپنے ہی حرمت والے ہیں جیسے تمہارے اس مہینے میں اور اس شہر میں اور تمہارے اس دن میں حرمت ہے۔\" رہی ان کی بیٹی ام کلثوم کی روایت تو وہ مجھے اب یاد نہیں۔ ابن اثیر نے ابو عمر کی حدیث جو ام کلثوم سے مروی ہے، اسے مختصر کیا ہے۔ ان کا قول ہے: ان کی حدیث کی سند کی کوئی پرواہ نہیں جس میں حدیث شعیب خاص طور پر شامل ہے، حالانکہ ایسا نہیں۔","",{"fn":"(1) اسد الغابہ (۶۸۰۳) تجرید (۲۵۵/۲)\n(2) الاستيعاب (۱۸۰۱/۴)\n(3) طبرانی (۵۳۸/۲۴) مجمع الزوائد (۲۷۳/۳)"}],[9585,"§۱۰۹۷۵ ۔ جمرہ بنت النعمان العدویہ\n(1) واقدی و تیمیہ کی کتاب میں ان کی حدیث بحوالہ شعیب بن میمون مخزومی ہے جو وہ ابو مرابہ بلوی سے اور وہ جمرہ بنت نعمان سے روایت کرتے ہیں، انہیں شرف صحابیت حاصل ہے۔ فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے بال اور خون(2) دفن کرنے کا حکم دیا۔ ابونعیم نے کمزور سند کے ساتھ اسے نقل کیا ہے۔ ابو موسیٰ نے اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۸۰۴) تجرید (۲۵۵/۲)\n(2) جامع المسانید والسنن (۳۴۹/۱۵)"}],[9586,"§۱۰۹۷۶ ۔ جُمَل\n(1) بعض کا قول ہے: تصغیر کے صیغے کے ساتھ ہے، ابن یسار مزنیہ، معقل بن یسار کی بہن ہیں، بعض کا قول ہے: یہ وہی نہیں، جب ان کے شوہر نے انہیں طلاق دی، پھر ان سے رجوع کرنے کا ارادہ کیا تو ان کے بھائی نے انہیں نکاح سے منع کیا۔ ان کی حدیث بخاری(2) نے ابراہیم بن طہمان کے طریق سے بحوالہ یونس بن عبید نقل کی ہے۔ وہ حسن سے روایت کرتے ہیں، وہ اس آیت کے بارے میں فرماتے ہیں کہ مجھ سے معقل بن یسار نے بیان کیا کہ یہ ان کے بارے میں نازل ہوئی، فرماتے ہیں: میں نے اپنی بہن کا نکاح ایک آدمی سے کیا جس نے اسے طلاق دے دی، پھر جب اس کی عدت ختم ہوئی تو نکاح کا پیغام لے کر آیا، میں نے اسے کہا: میں نے اس کا نکاح تم سے کیا تھا، میں نے تمہاری عزت کی، اور اسے تمہارا بستر بنایا، تو تم نے اسے طلاق دے دی، پھر اب تم نکاح کا پیغام لے کر آئے ہو، اللہ کی قسم! تم ہرگز اس سے رجوع نہیں کر سکتے۔ راوی کا بیان ہے کہ وہ اچھے آدمی تھے، اور عورت بھی ان کی طرف لوٹنا چاہتی تھی، اللہ تعالیٰ نے یہ آیت نازل فرمائی: \"تم انہیں ان کے شوہروں سے نہ روکو۔\"(3) تو میں نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! میں ابھی کر دوں گا۔ تو انہوں نے اپنی بہن کا نکاح اُن سے کر دیا، صحیح میں ان کا نام نہیں لیا۔ طبرانی نے ابن جریج کے طریق سے نقل کیا ہے کہ ان کا نام جمیلہ تھا، اور کلبی فرماتے ہیں کہ ان کا نام جمیل تھا، ابن ماکولا(4) نے اسے تصغیر کے ساتھ لکھا ہے۔ ثعلبی رحمہ اللہ فرماتے ہیں کہ ان کا نام جُمیلہ ہے، بعض کا قول ہے: ان کا نام لیلیٰ ہے۔","",{"fn":"(1) اسد الغابہ (۶۸۰۵) تجرید (۲۵۵/۲)\n(2) بخاری (۵۱۳۰)\n(3) سورۃ البقرۃ، الآیۃ (۲۳۲)\n(4) الاکمال (۱۲۵/۲)"}],[9587,"§۱۰۹۷۷ ۔ جمیل\nتصغیر کے ساتھ۔ ان سے پہلے والی صحابیہ کے حالات میں ان کا ذکر ہے۔"],[9588,"§۱۰۹۷۸ ۔ جمیلہ بنت ابی الخزرجیہ\n(1) عبد اللہ بن ابی بن سلول کی بہن ہیں، ابن مندہ فرماتے ہیں: ثابت بن قیس بن شماس کی زوجہ تھیں، ان سے ابن عباس اور عبداللہ بن رباح نے روایت کی ہے، پھر ہمام کے طریق سے بحوالہ قتادہ مرسل حدیث نقل کی ہے۔ اور وہ عکرمہ سے روایت کرتے ہیں، اور سعید بن ابو عروبہ کے طریق سے بحوالہ قتادہ موصولاً حدیث نقل کی ہے، جو وہ عکرمہ سے اور وہ ابن عباس رضی اللہ عنہما سے روایت کرتے ہیں کہ جمیلہ بنت ابی بن سلول نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں، وہ اپنے خاوند سے خلع لینا چاہتی تھیں، آپ صلی اللہ علیہ وسلم نے پوچھا: \"تمہارا حق مہر کیا تھا؟\" انہوں نے عرض کیا: باغ۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو اسے اس کا باغ لوٹا دو۔\"(2) خالد حذاء کے طریق سے روایت نقل کی ہے جو وہ عکرمہ سے بحوالہ ابن عباس رضی اللہ عنہما نقل کرتے ہیں کہ ثابت بن قیس کی بیوی جو جمیلہ بنت ابی ہیں، کہنے لگیں: نہ یا رسول اللہ! میرا اور ثابت کا گزر نہیں ہو سکتا۔ پھر انہوں نے حدیث ذکر کی جس میں ان کا اپنے شوہر سے خلع لینے کا ذکر ہے۔ راوی کا قول ہے: ایوب سے بحوالہ عکرمہ متصل روایت کی گئی ہے، درست یہ ہے کہ عکرمہ اور قتادہ سے مرسل روایت ہے، اسی طرح حسین بن واقد نے ثابت سے بحوالہ عکرمہ روایت کیا ہے، اور اسے محمد بن واقد نے ثابت سے بحوالہ عکرمہ روایت کیا ہے، اور اسے محمد بن حمید نے یحییٰ بن واضح سے بحوالہ حسین موصولاً نقل کیا ہے۔ اس میں ابن عباس رضی اللہ عنہما کا نام بھی مذکور ہے۔ ابونعیم نے سعید کے موصولہ طریق سے اس روایت کو متصل نقل کیا ہے۔ متن کے الفاظ یہ ہیں کہ جمیلہ بنت ابی نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! مجھے ثابت میں دین اور اخلاق کے لحاظ سے کوئی عیب نظر نہیں آتا لیکن میں اسلام لانے کے بعد کفر کو ناپسند کرتی ہوں۔ مجھے اس پر غصے میں قابو نہیں رہتا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم اس کا باغ واپس کرنا چاہتی ہو؟\" راوی کہتے ہیں، انہوں نے کہا: جی ہاں! تو آپ صلی اللہ علیہ وسلم نے انہیں حکم دیا کہ وہ باغ ان سے لے لیں۔(3) حفص بن عمر ضریر کی روایت، حماد بن سلمہ سے بحوالہ ثابت البنانی اور ایوب سے وہ دونوں عکرمہ سے روایت کرتے ہیں جو ابن عباس رضی اللہ عنہما سے روایت کرتے ہیں کہ جمیلہ بنت ابی بن سلول نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں، کہنے لگیں۔۔۔۔۔ پہلے بیان کی گئی روایت کی طرح ذکر کیا۔ محمد بن خالد بن عبد اللہ طحان کے طریق سے بحوالہ ان کے والد سے اسے مسنداً نقل کیا ہے۔ اور وہ ابوجلیل سے روایت کرتے ہیں اور وہ جمیلہ بنت ابی بن سلول سے روایت کرتے ہیں، فرماتی ہیں کہ وہ ثابت بن قیس کے نکاح میں تھیں۔ میں کہتا ہوں: ابن حمید کی روایت جس کی طرف ابن مندہ نے اشارہ کیا ہے اسے ابن ابو خیثمہ اور طبرانی نے ان سے روایت کیا ہے۔ متن کے الفاظ یہ ہیں کہ وہ ثابت بن قیس بن شماس کی زوجہ تھیں، ان کا جھگڑا ہو گیا، رسول اللہ صلی اللہ علیہ وسلم نے ان کی طرف پیغام بھیجا: \"اے جمیلہ! تم ثابت میں کیا چیز ناپسند کرتی ہو۔\" کہنے لگیں: اللہ کی قسم! مجھے ان کے پستہ قد کے علاوہ کچھ ناپسند نہیں۔ آپ صلی اللہ علیہ وسلم نے انہیں کہا: \"کیا تم ان کا باغ انہیں واپس کرنا چاہتی ہو؟\" کہنے لگیں: جی ہاں! آپ صلی اللہ علیہ وسلم نے ان کے درمیان جدائی کرا دی۔ ابن عباس رضی اللہ عنہما کی ان سے روایت ہے جسے طبرانی نے ابن جریر کے طریق سے بحوالہ عکرمہ نقل کیا ہے۔ وہ ابن عباس سے روایت کرتے ہیں، فرماتے ہیں: اسلام میں پہلا خلع عبد اللہ بن ابی کی بہن نے لیا، وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں، فرمانے لگیں۔۔۔۔۔ پھر سارا قصہ ذکر کیا۔ ابو عمر(4) فرماتے ہیں: سعید بن مسیب نے ان کی کنیت ام جمیل رکھی ہے۔ ثابت سے پہلے وہ حنظلہ بن ابو عامر (جنہیں فرشتوں نے غسل دیا تھا) کے نکاح میں تھیں۔ ثابت کے بعد ان سے مالک بن دخشم نے نکاح کیا، ان کے بعد خبیب بن اساف نے ان سے شادی کی، ابو عمر فرماتے ہیں: بصریین نے روایت کی ہے کہ وہ جمیلہ ہیں، جنہوں نے ثابت سے خلع لیا، اہل مدینہ کی روایت ہے کہ وہ حبیبہ بنت سہل ہیں۔ میں کہتا ہوں: جس نے یہ کہا کہ یہ جمیلہ بنت عبد اللہ بن ابی بن سلول ہیں، ان کا قول انشاء اللہ تعالیٰ آگے آ رہا ہے۔","",{"fn":"(1) اسد الغابہ (۶۸۰۶) تجرید (۲۵۵/۲)\n(2) بخاری (۵۲۷۳) نسائی (۵۲۶۳) نسائی (۳۲۶۳) ابن ماجہ (۲۰۵۶)\n(3) الاستيعاب (۱۸۰۲/۴)\n(4) الاستيعاب (۱۸۰۲/۴)"}],[9589,"§۱۰۹۷۹ ۔ جمیلہ بنت اوس المریہ\n(1) ان کی ایک حدیث ہے، اور ان کے والد کو شرف صحابیت حاصل ہے۔ یہ تجرید میں ہے۔ میں کہتا ہوں: ابوعلی غسانی نے استیعاب کے اضافے میں ان کا ذکر کیا ہے۔ فرماتے ہیں: اوس جو ان کے والد ہیں، ان کے سوانح میں ان کی حدیث ذکر کی، ان کا ذکر ابن قانع کی کتاب میں ہے، اور ابن قانع نے اوس کے نسب میں لفظی غلطی کی ہے، اور اسے زاء اور نون کے ساتھ لکھا ہے، جبکہ وہ راہ بغیر نقطوں کے ساتھ ہے۔ اس کے بعد ہمزہ ہے جیسا کہ اس کے بیان میں گزر چکا ہے۔ ان کی روایت سے حدیث گزر چکی ہے لیکن اس میں ام جمیل سے مروی ہے گویا یہ ان کی کنیت ہے، جبکہ ان کا نام جمیلہ ہے، کنیتوں میں ان کا ذکر آئے گا۔","",{"fn":"(1) تجرید اسماء الصحابہ (۷۵۵/۲)"}],[9590,"§۱۰۹۸۰ ۔ جمیلہ بنت ثابت بن ابی الاقلح\n(1) عاصم کی بہن ہیں، عمر کی زوجہ ہیں، ان کی کنیت ام عاصم ہے، ان کا نام عاصیہ تھا، رسول اللہ صلی اللہ علیہ وسلم نے جمیلہ رکھا۔ یہ ابو عمر(2) کا قول ہے، فرماتے ہیں: ان سے عمر نے سات ہجری میں نکاح کیا جس سے عاصم بن عمر پیدا ہوئے، انہوں نے انہیں طلاق دے دی پھر ان سے یزید بن حارثہ نے نکاح کیا، جس سے عبدالرحمن بن یزید پیدا ہوئے جو عاصم بن عمر کے ماں شریک بھائی تھے۔ یہ وہی ہیں جن کے بارے میں موطا وغیرہ میں حدیث مذکور ہے کہ عمر رضی اللہ عنہ قباء کی طرف روانہ ہوئے تو ابن عاصم کے بیٹے کو کھیلتے ہوئے دیکھا۔ یہ حرف عین کی قسم ثانی میں عاصم کے سوانح میں گزر چکا ہے۔ ابن مندہ نے ہشام بن حسان کے طریق سے بحوالہ واصل بن ابی شیبہ مسنداً نقل کیا ہے، فرماتے ہیں: عمر کی بیوی کا نام عاصیہ تھا، جب اسلام لائیں تو عمر کے پاس آئیں اور کہنے لگیں: مجھے اپنا نام ناپسند ہے، آپ میرا کوئی اور نام رکھ دیجئے۔ انہوں نے فرمایا: \"تم جمیلہ ہو۔\" وہ غصے ہوئیں اور کہنے لگیں: میرا نام رکھنے کے لیے آپ کو صرف ایک باندی کا نام ملا ہے؟ پھر وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں، اور عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! مجھے اپنا نام ناپسند ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: تم جمیلہ ہو۔ تو وہ غصہ میں آگئیں یعنی عمر کا قول ذکر کیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: کیا تم نہیں جانتی کہ اللہ تعالیٰ عمر کے دل اور زبان کے ساتھ ہے۔ پھر حجاج بن منہال کے طریق سے بحوالہ حماد بن سلمہ نقل کی ہے جو انہوں نے عبید اللہ بن عمر سے، انہوں نے نافع سے، انہوں نے ابن عمر رضی اللہ عنہما سے روایت کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے عاصیہ کا نام بدل دیا اور فرمایا: \"تم جمیلہ ہو۔\"(3) ابن ابی عمر نے بشر بن سری سے دوسری سند سے نقل کیا ہے۔ فرماتے ہیں: حماد سے بحوالہ ثابت، انہوں نے انس سے روایت کیا، فرماتے ہیں: میرا گمان ہے عمر کی لونڈی کا نام عجم کی طرح تھا۔ سیدنا عمر رضی اللہ عنہ نے اس کا نام جمیلہ رکھا، تو وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تو جمیلہ ہے۔\" سیدنا عمر رضی اللہ عنہ نے فرمایا: اس نام کو اپنی ناپسندیدگی کے باوجود لے لو۔ ابن سعد رحمہ اللہ(4) نے اپنی کتاب طبقات النساء کے شروع میں نبی کریم صلی اللہ علیہ وسلم سے بیعت کرنے والی خواتین کے باب میں لکھا ہے۔ ہمیں محمد بن عمر نے بتایا کہ مجھ سے ابن ابی حبیبہ نے بحوالہ عاصم بن عمر اور انہوں نے قتادہ سے بیان کیا، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم سے سب سے پہلے بیعت کی وہ ام سعد بن معاذ ہیں جو کبشہ بنت رافع بن عبید ہیں، اور ام عامر بنت یزید بن سکن، بنو ظفر سے لیلیٰ بنت خطیم، اور بنو عمرو بن عوف سے لیلیٰ، مریم، تمیمہ اور ابوسفیان (جسے ابو بنات کہا جاتا ہے) کی بیٹیاں، یہ اُحد میں شہید ہوئے اور شموس بنت ابو عامر راہب اور ان کی بیٹی جمیلہ بنت ثابت بن ابو الاقلح، اور ظبیہ بنت نعمان بن ثابت بن ابو الاقلح نے بیعت کی۔ میں کہتا ہوں: ان کے قول \"فأنت\" سے پہلے شاید کچھ الفاظ رہ گئے ہیں، اور وہ یہ ہیں: پھر آپ صلی اللہ علیہ وسلم سے ان کی زوجہ نے ان کا نام بدلنے کو کہا، تو آپ صلی اللہ علیہ وسلم نے ان کا نام جمیلہ رکھا، اور وہ ناراض ہوئیں جیسا کہ ابتداء میں واصل کی روایت میں ہے، جس سے بات مکمل ہوتی ہے۔ ان کا نام جمیلہ رکھا گیا جو ان کے غضب کا سبب معلوم ہوتا ہے۔ اس سے دوسری صحابیہ کا فائدہ ہوا، اور وہ عمر کی باندی ہیں۔ ابن سعد رحمہ اللہ نے ایسی سند سے جس میں واقدی ہیں روایت کیا ہے حدیث جابر میں عمر سے روایت ہے، فرماتے ہیں: میں نے کہا، یا رسول اللہ صلی اللہ علیہ وسلم! کیا میں نے جمیلہ بنت ثابت کو اتنے زور سے تھپڑ مارا کہ وہ زمین پر جاگریں، اس لیے کہ انہوں نے مجھ سے ایسی چیز کا سوال کیا ہے جس پر میں قدرت نہیں رکھتا۔","",{"fn":"(1) اسد الغابہ (۶۸۰۹) تجرید (۲۵۵/۲)\n(2) الاستيعاب (۱۸۰۲/۴)\n(3) احمد (الحدیث: ۲/۱۸)\n(4) الطبقات الکبریٰ (۲۵/۸)"}],[9591,"§۱۰۹۸۱ ۔ جمیلہ بنت ابی جہل\n(1) بن ہشام بن مغیرہ، مخزومیہ، نبی کریم صلی اللہ علیہ وسلم سے روایت کی، اور ان سے ان کے شوہر نے روایت کی، ابن مندہ نے ان کی حدیث سماک بن حرب کے طریق سے بحوالہ عبداللہ بن عمیرہ نقل کی ہے، جو ابو جہل کی بیٹی کے شوہر سے اور وہ ابو جہل کی بیٹی سے روایت کرتے ہیں، جن کا نام جمیلہ ہے۔ فرماتی ہیں: نبی کریم صلی اللہ علیہ وسلم ہمارے پاس سے گزرے اور پانی مانگا، میں نے انہیں پانی پلا دیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"میری اُمت میں سب سے بہتر میرے زمانے والے ہیں، پھر وہ لوگ جو ان کے قریب ہیں۔\"(2) ابن ابو عاصم نے اسے اس طریق سے نقل کیا ہے، اور یہ اضافہ کیا ہے: میں صراحی کی طرف بڑھی اور آپ صلی اللہ علیہ وسلم کو پانی پلایا، ایک شخص جس نے دو زرد کپڑے پہن رکھے تھے، آپ صلی اللہ علیہ وسلم سے سوال کیا اور آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ کی عبادت کرو، اس کے ساتھ کسی کو شریک نہ ٹھہراؤ۔ نماز قائم کرو، زکوٰۃ ادا کرو اور صلہ رحمی کرو، بعض نے کہا: یہ وہی ہیں جنہیں علی نے پیغام نکاح دیا تھا، اور محفوظ روایت میں ہے کہ وہ جویریہ ہیں۔","",{"fn":"(1) اسد الغابہ (۶۸۱۰) تجرید (۲۵۵/۲)\n(2) اسد الغابہ (۲۴۱/۵)"}],[9592,"§۱۰۹۸۲ ۔ جمیلہ بنت زید\n(1) علبہ بن زید بن صیفی بن عمرو بن جشم بن حارثہ انصاریہ کی بہن ہیں، نبی کریم صلی اللہ علیہ وسلم سے بیعت ہوئیں۔(2)","",{"fn":"(1) اسد الغابہ (۶۸۱۱) تجرید (۲۵۶/۲)\n(2) الطبقات الکبریٰ (۲۴۰/۸)"}],[9593,"§۱۰۹۸۳ ۔ جمیلہ بنت سعد\n(1) بن ربیع انصاری لیثی، جو اُحد کے دن شہید ہوئے۔ ان کا نسب گزر چکا ہے، انہیں شرف صحابیت حاصل ہے، اپنے والد سے روایت کرتی ہیں، ان سے ثابت بن عبید انصاری نے روایت کی کہ ان کے والد اور چچا یوم اُحد میں شہید ہوئے، ہم نے انہیں ایک قبر میں دفن کر دیا، یہ ابوعمر کا قول ہے، فرماتے ہیں: ان جمیلہ کا نکاح زید بن ثابت سے ہوا، یہ ابن سعد(2) کا قول ہے۔ اور اضافہ کیا ہے کہ ان سے خارجہ، یحییٰ، اسماعیل، سلیمان پیدا ہوئے، ان کی کنیت ام سعد ہے۔ ابن مندہ نے مسعر کے طریق سے بحوالہ ثابت بن عبید نقل کیا ہے۔ فرماتے ہیں: میں سعد بن ربیع کی صاحبزادی جمیلہ کے پاس گیا جو زید بن ثابت کی زوجہ ہیں، وہ میرے پاس خشک اور تر کھجوریں لائیں، میں نے ان سے کہا: میرا خیال ہے یہ تمہارے والد کی میراث ہے۔ کہنے لگیں: مجھے اپنے والد کی میراث نہیں ملی کیونکہ وہ فرائض کے نازل ہونے سے پہلے ہی شہید ہو گئے تھے۔ ابن سعد رحمہ اللہ(3) فرماتے ہیں: سعد کی موجودگی میں ان کی ولادت نہیں ہوئی۔ جب ان کے والد شہید ہوئے تو وہ حمل میں تھیں، پھر واقدی سے بحوالہ ابوزناد مسنداً نقل کیا ہے کہ ان کے والد جب شہید ہوئے وہ حمل میں تھیں۔","",{"fn":"(1) اسد الغابہ (۶۸/۲) تجرید (۲۵۶/۲)\n(2) الطبقات الکبریٰ (۲۶۰/۸، ۲۶۱)\n(3) الطبقات الکبریٰ (۲۴۱/۸)"}],[9594,"§۱۰۹۸۴ ۔ جمیلہ بنت سنان\n(1) بن ثعلبہ بن عامر بن مجدعہ بن جشم بن حارثہ انصاریہ، ابن حبیب نے ان کا ذکر نبی کریم صلی اللہ علیہ وسلم سے بیعت کرنے والی صحابیات میں کیا ہے۔ ابن سعد کا قول ہے: ان کی والدہ خولہ بنت منذر بن عمرو بن حزام انصاریہ خزرجیہ ہیں، اسلام لائیں اور بیعت ہوئیں، وہ ثابت بن عبید السلام بن سلیم انصاری کی والدہ ہیں، بنو خارجہ سے تھیں۔","",{"fn":"(1) اسد الغابہ (۶۸۱۳) تجرید (۲۵۶/۲)"}],[9595,"§۱۰۹۸۵ ۔ جمیلہ بنت صیفی\n(1) بن عمرو بن زید بن جشم بن حارثہ، اسلام لائیں اور بیعت کی۔ یہ ابن سعد کا قول ہے، ان کی والدہ النوار بنت قیس بن لوذان بن ثعلبہ ہیں، وہ علیہ بنت زید بن زید بن عمرو بن جشم کی بہن ہیں، جمیلہ نے عتیک بن قیس بن ہیشہ اوسی سے نکاح کیا جو بنو عمرو بن عوف سے ہیں۔","",{"fn":"(1) تجرید (۲۵۶/۲)"}],[9596,"§۱۰۹۸۶ ۔ جمیلہ بنت ابی صعصعہ\n(1) جن کا نام عمرو بن زید بن عوف بن مبذول بن عمرو بن غنم بن مازن بن نجار ہے۔ ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، اور فرمایا: ان سے عبادہ بن صامت نے نکاح کیا، جس سے ولید پیدا ہوئے، پھر ان سے ربیع بن سراقہ نے نکاح کیا، جس سے عبداللہ، محمد اور بثینہ پیدا ہوئے، پھر ان سے کلدہ بن ابو خالد بن قیس بن خالد بن مخلد بن عامر بن زریق نے نکاح کیا، فرماتے ہیں: ان کی والدہ ائیسہ بنت عاصم بن عمرو بن عوف بن مبذول ہیں۔","",{"fn":"(1) اسد الغابہ (۶۸۰۷) تجرید (۲۵۵/۲)\n(2) الطبقات الکبریٰ (۳۰۴/۸)"}],[9597,"§۱۰۹۸۷ ۔ جمیلہ بنت عبداللہ\n(1) بن ابی ابن سلول، ابن سعد کا قول ہے کہ حنظلہ بن ابو عامر نے ان سے نکاح کیا، وہ یوم اُحد میں شہید ہوئے پھر ان سے ثابت بن قیس نے نکاح کیا، وہ وفات پاگئے۔ پھر مالک بن دخشم نے ان سے نکاح کیا، ان کے بعد خبیب بن اساف نے ان سے نکاح کیا، ابن مندہ کا یہی قول ہے، وہ ثابت بن قیس کے بارے میں فرماتے ہیں کہ وہ وفات پاگئے۔ جبکہ ابن سعد نے یہ نہیں لکھا، ثابت بن قیس یمامہ میں شہید ہوئے۔ اور خبیب بن اساف کے بارے میں فرمایا: انہوں نے ثابت بن قیس کے بعد ان سے نکاح کیا، وہ سیدنا عمر رضی اللہ عنہ کی خلافت تک زندہ رہے۔ جیسا کہ ان کے سوانح میں مذکور ہے اس کا آپس میں تعارض ہے اس لیے کہ میں نے طبقات ابن سعد کی مراجعت کی ان کے قول کا خلاصہ یہ ہے۔ ان سے حنظلہ بن راہب نے نکاح کیا، جو یوم اُحد میں شہید ہوئے، انہیں غسیل ملائکہ کہا جاتا ہے۔ ان سے عبداللہ بن حنظلہ پیدا ہوئے، پھر ان سے ثابت بن قیس بن شماس نے نکاح کیا، جس سے محمد پیدا ہوئے۔ اس کے بعد ان سے مالک بن دخشم نے نکاح کیا، ان کے بعد خبیب بن اساف نے جمیلہ بنت عبداللہ سے نکاح کیا۔ پھر فرماتے ہیں: جمیلہ اسلام لائیں اور بیعت کی، وہ عبداللہ بن عبد اللہ کی سگی بہن ہیں، حرہ کے دن ان کے دو بیٹے عبد اللہ اور محمد شہید ہوئے۔ جو کچھ ابن مندہ نے نقل کیا ہے، ابن اثیر اس پر اعتراض کرنے میں مشغول ہو گئے، فرماتے ہیں: جمیلہ بنت ابی کے سوانح میں مذکور ہے کہ انہوں نے ثابت بن قیس سے خلع لی تھی، اور ان کے بارے میں فرمایا: وہ حنظلہ کی زوجہ تھیں، انہوں نے ان سے پہلی خاتون کے بارے میں ایسا نہیں کہا، فرمایا: ثابت انہیں بیوہ چھوڑ کر وفات پاگئے۔ گویا کہ انہیں گمان ہوا کہ یہ دو خواتین ہیں، جیسا کہ وہ انہیں جمیلہ بنت ابی اور انہیں جمیلہ بنت عبداللہ بن ابی سمجھ بیٹھے، پہلا صحیح ہے اور دوسرا قول وہم ہے، جس کی حقیقت نہیں۔ اگر بغور دیکھتے تو انہیں پتہ چل جاتا وہ دونوں ایک ہیں۔ ابونعیم اس زعم میں ان سے سبقت لے گئے ہیں کہ وہ دونوں ایک ہیں۔ فرماتے ہیں: ایک جماعت نے اس کی مخالفت کی ہے اور انہیں خلع لینے والی سے علیحدہ ذکر کیا ہے جبکہ اس میں وہم ہے۔ ابن اثیر فرماتے ہیں: ابونعیم ٹھیک فرماتے ہیں۔ جس وہم سے میں نے متنبہ کیا ہے کہ وہ ابن مندہ کو پیش آیا ہے وہ تو بدستور باقی ہے۔ ابن اثیر اس سے صرف نظر کر گئے، اور دعویٰ یہ کیا کہ انہیں دو خواتین قرار دینے میں وہم ہوا ہے، حالانکہ جیسا ابن اثیر اور ابونعیم نے سمجھا ویسا نہیں بلکہ درست یہ ہے کہ وہ دو خواتین ہیں، ہوا یہ تھا کہ ثابت بن قیس نے پہلے ان کی پھوپھی سے شادی کی تھی، جنہوں نے ان سے خلع لے لیا تھا، پھر ان سے شادی کی تھی۔ بعد میں ان سے بھی علیحدگی اختیار کر لی تھی۔","",{"fn":"(1) اسد الغابہ (۶۸۱۴)"}],[9598,"§۱۰۹۸۸ ۔ جمیلہ بنت عبداللہ\n(1) بن حنظلہ انصاریہ، بنو حبلی سے ہیں، ابن حبیب نے ان کا ذکر نبی کریم صلی اللہ علیہ وسلم سے بیعت کرنے والی صحابیات میں کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۸۱۵) تجرید (۲۵۶/۲)"}],[9599,"§۱۰۹۸۹ ۔ جمیلہ بنت عبدالعزیٰ\n(1) بن قطن خزاعیہ، بنو مصطلق سے ہیں، بیعت کرنے والی خواتین میں سے ہیں، عبدالرحمن بن عوام کی زوجہ ہیں، جو زبیر کے بھائی ہیں۔ ان کے بیٹوں کی والدہ ہیں، ان سے کوئی روایت مروی نہیں، یہ ابوعمر(2) کا قول ہے۔ میں کہتا ہوں: ابن اثیر نے بنت عبد اللہ۔۔۔۔ اور عمر کے بعد ان کا نام لیا ہے، اس کا تقاضا یہ ہے کہ وہ ان کے نزدیک عظیمہ کے وزن پر ہو اور ایسا نہیں، کیونکہ وہ جُمینہ تصغیر کے ساتھ ہے۔ بعض نے فرمایا: ھاء نون کے ساتھ ہے، اسی طرح یہ الاستیعاب کے نسخے میں تجوید کے ساتھ ہے، اسی طرح زبیر بن بکار کی کتاب النسب کے قابل اعتماد نسخے میں ہے، اور دوسرے نسخے میں حاء بغیر نقطوں سے ہے۔","",{"fn":"(1) اسد الغابہ (۶۸۱۶) تجرید (۲۵۶/۲)\n(2) الاستيعاب (۱۸۰۴/۴)"}],[9600,"§۱۰۹۹۰ ۔ جمیلہ بنت عمر\n(1) بن خطاب، جمیلہ بنت ثابت کے سوانح میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۶۸۱۷) تجرید (۲۵۶/۲)"}],[9601,"§۱۰۹۹۱ ۔ جمیلہ بنت عمرو\nبن ہشام بن مغیرہ وہ ابو جہل کی بیٹی ہیں، جیسا کہ گزر چکا ہے۔"],[9602,"§۱۰۹۹۲ ۔ جمیلہ\n(1) یا خویلہ یا خولہ، اوس بن صامت کی زوجہ ہیں جن سے انہوں نے ظہار کیا تھا۔ ابن مندہ نے ان کا ذکر کیا ہے، ابونعیم نے انہیں لفظی غلطی کے ساتھ منسوب کیا ہے۔ ایسا نہیں جیسا کہ وہ گمان کرتے ہیں، حدیث عائشہ میں ان کا نام اسی طرح مذکور ہے جو مسند احمد کی روایت ہے، لیکن معروف یہ ہے کہ وہ خولہ ہیں، شاید جمیلہ لقب ہو، اس کا بیان حرف خاء (نقطہ والا) میں آئے گا۔ ان شاء اللہ تعالیٰ!","",{"fn":"(1) تجرید (۲۵۵/۲)"}],[9603,"§۱۰۹۹۳ ۔ جمیلہ بنت یسار\nجُمَل کے سوانح میں ان کا ذکر گزر چکا ہے۔"],[9604,"§۱۰۹۹۴ ۔ جمیمہ\n(1) تصغیر کے ساتھ ہے، حمام بن جموح انصاریہ کی بیٹی ہیں جو بنو حبلی سے تھے۔ ابن حبیب نے ان کا ذکر نبی کریم صلی اللہ علیہ وسلم سے بیعت کرنے والی صحابیات میں کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۸۱۸) تجرید (۲۵۶/۲)"}],[9605,"§۱۰۹۹۵ ۔ جمیمہ بنت صیفی\n(1) بن صحر بن خنساء انصاریہ، ابن حبیب نے ان کا ذکر نبی کریم صلی اللہ علیہ وسلم سے بیعت کرنے والی صحابیات میں کیا ہے۔ ابوعلی غسانی نے ابن عبد البر کی کتاب پر اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۸۱۹) تجرید (۲۵۶/۲)"}],[9606,"§۱۰۹۹۶ ۔ جمینہ\nنون کے ساتھ ہیں، بعض کا قول ہے: وہ بنت عبد العزیٰ ہیں، ان کا ذکر جمیلہ کے سوانح میں مذکور ہے۔"],[9607,"§۱۰۹۹۷ ۔ جہدمہ\n(1) بشیر بن خصاصیہ سدوسی، جو مشہور صحابی ہیں، ان کی زوجہ ہیں۔ بنو شیبان سے تھیں، نبی کریم صلی اللہ علیہ وسلم سے دو یا تین حدیثیں روایت کیں۔ یہ ابو عمر کا قول ہے۔ میں کہتا ہوں: ابن مندہ نے ان کی دو حدیثیں ابو عتاب کلبی کے طریق سے بحوالہ زیاد بن لقیط جو جہدمہ سے مروی ہیں، انہیں مسنداً نقل کیا ہے۔ میں کہتا ہوں: بشیر کا نام رحم تھا، نبی کریم صلی اللہ علیہ وسلم نے ان کا نام بشیر رکھا۔ دوسری روایت اس سند سے ہے۔ فرماتی ہیں: میں نے نبی کریم صلی اللہ علیہ وسلم کو دیکھا کہ آپ نماز کے لیے باہر تشریف لائے۔ آپ کے سر اور پیشانی سے مہندی کی مہک پھوٹ رہی تھی۔ ترمذی(2) رحمہ اللہ نے اسے شمائل میں نقل کیا ہے، بعض کا قول ہے: ان کا یہ نام تھا جسے نبی کریم صلی اللہ علیہ وسلم نے بدل کر لیلیٰ رکھ دیا، ابن حبان نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے، فرماتے ہیں: بعض کا قول ہے کہ انہیں شرف صحابیت حاصل ہے، پھر ثقات تابعین میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۸۲۰) تجرید (۲۵۶/۲)\n(2) ترمذی (الحدیث: ۴۵)"}],[9608,"§۱۰۹۹۸ ۔ جویریدہ بنت ابی جہل\n(1) یہ وہی ہیں جنہیں سیدنا علی بن ابی طالب رضی اللہ عنہ نے نکاح کا پیغام دیا تھا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"رسول اللہ صلی اللہ علیہ وسلم کی بیٹی اور اللہ کے دشمن کی بیٹی ایک شخص کے پاس کبھی اکٹھی نہیں ہو سکتیں۔\" سیدنا علی رضی اللہ عنہ نے منگنی کو چھوڑ دیا۔ ان سے عتاب بن اسید جو امیر مکہ تھے، انہوں نے نبی کریم صلی اللہ علیہ وسلم کے عہد میں نکاح کیا، ان سے عبدالرحمن پیدا ہوئے جو جنگ جمل میں شہید ہوئے۔ ابن مندہ نے ان کا ذکر کیا ہے، ان کے علاوہ نے کہا: ان کا نام جمیلہ ہے جیسا کہ گزر چکا ہے، اور ان کا قصہ صحیحین(2) میں مسور مخرمہ کی حدیث میں ہے، جس میں ان کا نام مذکور نہیں۔","",{"fn":"(1) اسد الغابہ (۶۸۲۱) تجرید (۲۵۶/۲)\n(2) بخاری (الحدیث: ۹۲۶) مسلم (الحدیث: ۶۲۶۰)"}],[9609,"§۱۰۹۹۹ ۔ جویریہ بنت الحارث\n(1) بن ابی ضرار بن حبیب بن جذیمہ، وہ مصطلق بن عمرو بن ربیعہ بن حارثہ بن عمرو خزاعیہ مصطلقیہ ہیں، غزوہ مُریسیع ۵ھ یا ۶ھ میں آپ صلی اللہ علیہ وسلم نے بنو مصطلق سے جہاد کیا، قیدیوں میں جویریہ بھی تھیں جو مسافع بن صفوان مصطلقی کے نکاح میں تھیں اور ثابت بن قیس کے حصے میں آئیں۔ ابن اسحاق(2) فرماتے ہیں: مجھ سے محمد بن جعفر بن زبیر نے عروہ بن زبیر کی پھوپھی سے انہوں نے اپنی خالہ عائشہ رضی اللہ عنہا سے بیان کیا، فرماتی ہیں: جب رسول اللہ صلی اللہ علیہ وسلم نے بنو مصطلق کے قیدی تقسیم کیے تو جویریہ ثابت بن قیس بن شماس کے حصے میں یا ان کے چچا زاد کے حصے میں آئیں۔ انہوں نے اپنے نفس پر مکاتبت کر لی، وہ خوش مزاج اور خوش طبع خاتون تھیں جو بھی انہیں دیکھتا اس کا دل چھین لیتیں۔ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس مال مکاتبت میں مدد مانگنے آئیں، سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں: اللہ کی قسم! جب میں نے اسے دیکھا تو مجھے ناگوار ہوا، اور میں نے کہا: رسول اللہ صلی اللہ علیہ وسلم ان میں وہ دیکھیں گے جو میں نے دیکھا، جب وہ نبی کریم صلی اللہ علیہ وسلم کے پاس گئیں، کہنے لگیں: یا رسول اللہ صلی اللہ علیہ وسلم! میں جویریہ، حارث کی بیٹی ہوں جو اپنی قوم کا سردار ہے، مجھے اتنی مصیبتیں پہنچی ہیں جو آپ پر مخفی نہیں ہیں، میں نے اپنے نفس پر مکاتبت کر لی ہے، آپ مال مکاتبت میں میری مدد کریں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا اس سے بہتر چیز نہ ہو؟ میں تمہارا مال مکاتبت ادا کر دوں اور تم سے نکاح کر لوں۔\" کہنے لگیں: جی ہاں! آپ صلی اللہ علیہ وسلم نے ایسا ہی کیا۔(3) لوگوں کو آپ صلی اللہ علیہ وسلم کے نکاح کی خبر پہنچی تو وہ کہنے لگے: یہ نبی کریم صلی اللہ علیہ وسلم کے سسرال ہیں، انہوں نے بنو مصطلق کے تمام قیدی رہا کر دیئے، اللہ تعالیٰ نے ان کے ذریعے بنو مصطلق کے سو(۱۰۰) گھرانے آزاد کیے، اور میں نے اپنی قوم کے حق میں ان سے زیادہ برکت والی خاتون نہیں دیکھی۔ ابن سعد(4) نے واقدی کے حوالے سے ان کی سند سے سیدہ عائشہ رضی اللہ عنہا سے اسی طرح نقل کیا ہے، لیکن ان کے شوہر کا نام صفوان بن مالک لیا ہے، اور شعبہ کے طریق سے محمد بن عبد الرحمن نے جو آل طلحہ کے مولیٰ ہیں، انہوں نے بحوالہ کریب، انہوں نے ابن عباس رضی اللہ عنہما سے نقل کیا ہے، فرماتے ہیں: جویریہ کا نام برہ تھا، نبی کریم صلی اللہ علیہ وسلم نے ان کا نام جویریہ رکھا۔ ترمذی(5) نے شعبہ کے طریق سے اسے نقل کیا ہے اور اس کی سند کو ابن عباس رضی اللہ عنہما تک پہنچایا ہے، جو جویریہ بنت حارث سے روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم ان کے ہاں سے گزرے تو وہ اپنی جائے نماز پر بیٹھی ہوئی تھیں، پھر دوپہر کے وقت وہیں سے گزرے تو فرمایا: کیا تم اسی حالت میں بیٹھی ہو؟ انہوں نے عرض کیا: جی ہاں۔ فرمایا: کیا میں تمہیں چند کلمات سکھا دوں جو تم پڑھو: سُبْحَانَ اللهِ عَدَدَ مَخْلُقِهٖ، \"اللہ کی پاکی جتنی اس کی مخلوق ہے۔\"۔۔۔۔۔ (الحدیث) ابن مندہ کی کتاب معرفة الصحابة میں یہ روایت اونچی سند سے ملی ہے اور وہ سند صحیح ہے۔ ابوقلابہ کی مرسل روایت ہے، فرمایا: نبی صلی اللہ علیہ وسلم نے جویریہ رضی اللہ عنہا کو قیدی بنایا یعنی آپ صلی اللہ علیہ وسلم نے ان سے نکاح کرنے کا ارادہ کیا تو ان کے والد آکر کہنے لگے: میری بیٹی تو ایسی ہے کہ اس جیسی کو قیدی نہیں بنایا جاتا۔ آپ صلی اللہ علیہ وسلم اسے چھوڑ دیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر میں اسے اختیار دوں تو تمہاری رائے میں یہ بہتر ہوگا؟\" انہوں نے کہا: کیوں نہیں۔ چنانچہ وہ اپنی بیٹی کے پاس آئے اور اس بات کا ان سے ذکر کیا تو وہ کہنے لگیں: میں اللہ اور اس کے رسول صلی اللہ علیہ وسلم کو پسند کرتی ہوں۔ اس کی سند صحیح ہے۔ سیدہ جویریہ رضی اللہ عنہا نے نبی کریم صلی اللہ علیہ وسلم سے احادیث روایت کی ہیں، ان سے ابن عباس، جابر، ابن عمر، عبید بن سباق اور طفیل (ان کے بھتیجے) وغیرہ کی احادیث نقل کی ہیں۔ ابن اسحاق نے ذکر کیا ہے کہ ان کے پہلے شوہر کو ابن ذی شعر کہا جاتا ہے، اور واقدی نے ان کا نام مسافع بن صفوان بن ذی شقر بن ابو سرح لیا ہے۔ مریسیع کے دن قتل ہوئے۔ صحیح بخاری میں سیدہ جویریہ رضی اللہ عنہا سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم ان کے پاس جمعہ کے دن آئے اور وہ روزہ دار تھیں، آپ صلی اللہ علیہ وسلم نے پوچھا: \"کیا تم نے کل روزہ رکھا تھا؟\" انہوں نے کہا: نہیں۔ آپ صلی اللہ علیہ وسلم نے پوچھا: \"کیا تم کل روزہ رکھو گی؟\" کہنے لگیں: نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"پھر افطار کر لو۔\" مسلم(6) کی روایت زہری رحمہ اللہ کے طریق سے جو انہوں نے عبید بن سباق سے بحوالہ جویریہ بنت حارث نقل کی ہے، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے اور فرمایا: کیا کھانے کو کچھ ہے؟ (الحدیث) صحیح مسلم میں ہے کہ ان کا نام برہ تھا، نبی کریم صلی اللہ علیہ وسلم نے جویریہ رکھ دیا، آپ صلی اللہ علیہ وسلم کو یہ کہا جانا پسند نہیں تھا کہ آپ نیک کے پاس سے نکلے۔ بعض کا قول ہے (ہجرت کے پچاسویں سال) ۵۰ھ میں فوت ہوئیں۔ بعض نے کہا: ربیع الاول ۵۶ھ میں فوت ہوئیں۔ بعض نے کہا: ربیع الاول ۵۷ھ تک زندہ رہیں۔ یہ واقدی کا قول ہے، فرمایا: مروان نے ان کی نماز جنازہ پڑھی، بقول بعض: پینسٹھ(۶۵) برس زندہ رہیں۔","",{"fn":"(1) اسد الغابہ (۶۸۲۲) تجرید (۲۵۶/۲)\n(2) السیرۃ النبویۃ (۲۳۱/۳)\n(3) المعجم الکبیر (الحدیث: ۱۶)\n(4) الطبقات الکبریٰ (۸۴/۸)\n(5) ترمذی (الحدیث: ۳۵۵۵)\n(6) مسلم (الحدیث: ۲۴۸۰)"}],[9610,"§۱۱۰۰۰ ۔ جویریہ\nابن بطال کی شرح میں لکھا ہے کہ یہ وہی خاتون ہیں جن سے خبیب بن عدی نے استرا مانگے پر لیا تھا۔ صحیح بخاری کی حدیث میں ان کا نام مذکور نہیں۔"],[9611,"§۱۱۰۰۱ ۔ جویریہ بنت المجلل\n(1) حاطب بن حارث نجمی کی زوجہ ہیں۔ ان کی کنیت ام جمیل ہے۔ یہ اپنی کنیت سے مشہور ہیں جبکہ ان کے نام میں اختلاف ہے، یہ ابو عمر کا قول ہے۔","",{"fn":"(1) اسد الغابہ (۶۸۲۳) تجرید (۲۵۷/۲)"}],[9612,"§۱۱۰۰۲ ۔ جمانہ بنت الحسن بن حبہ\nعہد نبوی صلی اللہ علیہ وسلم میں پیدا ہوئیں، ان سے حذیفہ بن یمان نے نکاح کیا، ابن سعد نے ان لوگوں میں ان کا ذکر کیا ہے جنہوں نے آپ صلی اللہ علیہ وسلم سے روایت نہیں کی۔"],[9613,"§۱۱۰۰۳ ۔ جمیلہ بنت عمر\n(1) بن خطاب، ان کا نام عاصیہ تھا، ان کا نام جمیلہ رکھا۔ ابن ابی شیبہ نے حسن بن موسیٰ سے بحوالہ حماد، انہوں نے عبید اللہ بن عمر سے انہوں نے نافع سے، انہوں نے ابن عمر رضی اللہ عنہما سے نقل کیا ہے کہ عمر کی بیٹی کو عاصیہ کہا جاتا تھا، رسول اللہ صلی اللہ علیہ وسلم نے ان کا نام جمیلہ رکھا، ابوعلی غسانی نے استیعاب(2) پر اپنے استدراک میں ان کا ذکر کیا ہے۔ ابن اثیر نے ان کا تعاقب کیا ہے کہ یہ قصہ عمر کی زوجہ کے بارے میں وارد ہوا، نہ کہ ان کی بیٹی کے بارے میں، جیسا کہ گزر چکا ہے۔ جمیلہ بنت ثابت کے سوانح میں گزر چکا ہے کہ وہ عمر کی بیوی ہیں، جس کی نص یہ ہے: حماد بن سلمہ نے ان اسناد کے ساتھ روایت کیا ہے کہ یہ یعنی جمیلہ بنت ثابت بن ابو الاقلح کا نام عاصیہ تھا، جب وہ اسلام لائیں تو ان کا نام جمیلہ رکھا، انہوں نے ایسے ہی نقل کیا ہے، انہوں نے اسے ابن مندہ کی کتاب سے نقل کیا ہے، جس کے الفاظ حجاج بن منہال کے طریق سے بحوالہ حماد ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے عاصیہ نام بدل دیا اور فرمایا: \"تو جمیلہ ہے۔\"(3) تاہم انہوں نے یہ بیان نہیں کیا کہ وہ سیدنا عمر رضی اللہ عنہ کی زوجہ ہیں یا بیٹی، لیکن اس سے پہلے واصل بن ابی عیینہ کی مرسل روایت میں عمر کی زوجہ کے متعلق ذکر ہے جیسا کہ ان کے سوانح میں گزر چکا ہے۔ روایت بالمعنی نقل کرتے ہوئے کچھ کمی بیشی ہوگئی، ان سے جوڑ ٹھیک نہیں بیٹھا، اور اس میں کچھ مانع نہیں کہ ان کی زوجہ اور بیٹی کا نام بدل دیا جائے۔ لیکن ابو علی غسانی نے ابو مسلم کجی کے طریق سے بحوالہ حجاج بن منہال حدیث نقل کی ہے۔ اس کے الفاظ یہ ہیں: ام عاصم کا نام عاصیہ تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے ان کا نام بدل کر جمیلہ رکھ دیا، یہ اس بات کی دلیل ہے کہ یہاں عمر کی زوجہ مراد ہیں۔","",{"fn":"(1) اسد الغابہ (۶۸۱۷) تجرید (۲۵۶/۲)\n(2) استيعاب (۱۸۰۲/۴)\n(3) احمد (الحدیث: ۲/۱۸) بخاری (۸۲۰) طبرانی (الحدیث: ۵۴۴/۲۴)"}],[9614,"§۱۱۰۰۴ ۔ جویریہ بنت ابی سفیان\nبن حرب، معاویہ کی سگی بہن ہیں۔ ابن سعد(1) نے ان کا ذکر کیا ہے۔ اور فرمایا: ان سے سائب بن ابو خبیب اسدی نے نکاح کیا۔","",{"fn":"(1) الطبقات الکبریٰ (۱۷۴/۸)"}],[9615,"§۱۱۰۰۵ ۔ جسرہ بنت دجاجہ\n(1) معروف تابعیہ ہیں۔ ابوذر، علی، عائشہ، ام سلمہ رضی اللہ عنہم سے روایت کی، اہل کوفہ میں ان کا شمار ہے۔ ان سے قدامہ بن عبداللہ عامری، اکفلت بن خلیفہ، ممدوح ہذلی نے روایت کی۔ عجلی فرماتے ہیں: ثقہ ہیں۔ ایک روایت سے پتہ چلتا ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا ہے۔ ابن مندہ نے عثام بن علی کے طریق سے، انہوں نے قدامہ سے بحوالہ جسرہ روایت کیا ہے، وہ فرماتی ہیں: نبی کریم صلی اللہ علیہ وسلم کی وفات کے دن ایک آنے والا پہاڑ کے اوپر چڑھ گیا، اور کہا: اے وادی کے رہنے والو! دین بدل گیا، تین مرتبہ کہا، تمہارا نبی جس کا تم گمان کرتے ہو وفات پا گیا۔ وہ شیطان تھا۔ ہم نے حساب لگایا، یہ وہی دن تھا جب نبی کریم صلی اللہ علیہ وسلم وفات پاگئے۔ ابن مندہ نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے اور ان سے اس کے علاوہ کچھ روایت نہیں کیا۔ ابوعلی بن سکن نے اپنی سند سے اسے نقل کیا ہے، جسے وہ عثام تک لے گئے ہیں (یہ عین بغیر نقطوں کے ہے، اور ث تشدید کے ساتھ ہے)۔ اس بات کی تصریح نہیں کہ انہوں نے دور نبوت پایا، کیونکہ احتمال ہے کہ وہ یہ کہنا چاہتی ہوں کہ ان کی قوم سے ایک آنے والا آیا، اور انہوں نے ان لوگوں سے نقل کر دیا ہو اور اس واقعہ کا زمانہ نہ پایا ہو۔ ابن سکن نے ان کا صحابہ رضی اللہ عنہم میں ذکر نہیں کیا، ان کی صحابہ رضی اللہ عنہم سے مروی حدیث ابوداؤد اور نسائی وغیرہ میں ہے۔","",{"fn":"(1) اسد الغابہ (۶۷۹۸) تجرید (۲۵۴/۲)"}],[9616,"§۱۱۰۰۶ ۔ جمرہ\nعیینہ بن حصن فزاری کی زوجہ ہیں، قیس ابن حازم کی مرسل حدیث جس میں عیینہ کا قصہ ہے، سعید ابن منصور کی کتاب کے آخری حصے کے اخیر میں ان کا ذکر ہے۔"],[9617,"§۱۱۰۰۷ ۔ جاریہ بنت عمرو\nبن مؤمل، یہ ان لوگوں میں سے ہیں جنہیں اللہ تعالیٰ کے راستے میں اذیتیں دی گئیں، تو ابوبکر رضی اللہ عنہ نے انہیں خرید لیا۔ ابن سعد(1) نے امیمہ بنت رقیقہ کے بعد ان کا ذکر کیا ہے۔ بعض کا قول ہے: بریرہ، سیدہ عائشہ رضی اللہ عنہا کی باندی ہیں، راوی کا قول ہے: وہ بنت عمرو نہیں ہیں وہ آل عمرو کی باندی تھیں، شاید وہ گھر کی باندی ہوں، اس لفظ کا اطلاق مرد اور عورت دونوں کی آل پر ہوتا ہے۔ یہاں سے مراد اول ہے۔ معروف جاریہ بنت عمرو بن مؤمل یا جاریہ بن عمرو بن مؤمل ہیں، بعض نے انہیں مرد گمان کیا اور لفظی غلطی کی یہ حارثہ فرماتے ہیں: ث کے ساتھ ہے، اللہ ہی کی توفیق ہے۔","",{"fn":"(1) الطبقات الکبریٰ (۱۸۷/۸)"}],[9618,"§۱۱۰۰۸ ۔ جمیلہ بنت المصفح\nنبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا، ان سے فضیل بن مرزوق نے روایت کی ہے۔ ابو عمر نے ان کا ذکر کیا ہے۔ میں کہتا ہوں: ان کے علاوہ نے ان کے والد کے نام میں مصلح کے بجائے مصبح ذکر کیا ہے۔ میرے خیال میں انہیں کسی صحابی سے روایت حاصل نہیں ہے۔ نسائی نے مسند علی میں ان سے حدیث نقل کی ہے۔ ان کی ایک اور حدیث حاطب سے بحوالہ ابوذر مروی ہے، مجھے کوئی ایسی بات معلوم نہیں جو ان کے دور نبوت پانے پر دلالت کرے۔"],[9619,"§۱۱۰۰۹ ۔ جمیلہ بنت عبد العزی\nقسم اول میں ان کے متعلق تنبیہ گزر چکی ہے۔"],[9620,"§۱۱۰۱۰ ۔ جویریہ بنت الحارث\n(1) بن عبدالمطلب بن ہاشم، ذہبی رحمہ اللہ نے خواتین کے حصے میں حرف جیم کے آخر میں فرمایا: یہ وہی جویریہ ہیں جن سے نبی صلی اللہ علیہ وسلم نے فرمایا: \"میں نے تمہارے بعد چار کلمات کہے۔۔۔۔۔\" (الحدیث) مسلم(2) نے اسے نقل کیا ہے، ابن حبان نے انواع میں فرمایا یہ نبی کریم صلی اللہ علیہ وسلم کی پھوپھی زاد ہیں، اسی طرح فرمایا: یہ ام المومنین ہیں، ابن عباس رضی اللہ عنہما نے ان سے روایت کی ہے۔ میں کہتا ہوں: ام المومنین جویریہ بنت حارث کے سوانح میں ترمذی کے بیان سے میں نے اس کا ذکر کیا ہے۔ مسلم کے الفاظ ہیں سفیان جو ابن عیینہ ہیں، ان کے طریق سے بحوالہ محمد بن عبد الرحمن جو مولی آل طلحہ ہیں، انہوں نے کریب سے، انہوں نے ابن عباس رضی اللہ عنہما سے جنہوں نے سیدہ جویریہ رضی اللہ عنہا سے روایت نقل کی ہے کہ نبی کریم صلی اللہ علیہ وسلم ان کے پاس سے صبح سویرے تشریف لے گئے۔۔۔۔۔ (الحدیث) مسعر کی روایت میں ہے: جو محمد بن عبد الرحمن سے وہ ابی رشدین سے وہ کریب سے اسی طرح روایت کرتے ہیں، لیکن انہوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم ان کے پاس سے گزرے، نماز پڑھنے سے پہلے یا جب وہ نماز پڑھ چکے تھے، جیسا کہ ابن ماجہ میں مشعر کے طریق سے ہے، اور ترمذی اور نسائی میں شعبہ کے طریق سے ہے کہ انہوں نے محمد بن عبد الرحمن سے سفیان کی طرح روایت کیا، اور اس میں ہے: ابن عیاش سے بحوالہ جویریہ بنت حارث بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم ان کے پاس سے گزرے اور وہ تسبیح کر رہی تھیں۔ حسن بن سفیان کی مسند میں بحوالہ قتیبہ، سفیان بن عیینہ سے مسلم کی سند کے ساتھ مروی ہے، وہ ابن عباس رضی اللہ عنہما سے روایت کرتے ہیں کہ جویریہ بنت حارث فرماتی ہیں: نبی کریم صلی اللہ علیہ وسلم باہر تشریف لے گئے، اس وقت میں اپنے جائے نماز پر بیٹھی تھی۔ جب دوپہر ہوئی تو لوٹے۔۔۔۔۔ (الحدیث) ابونعیم نے اپنی مستخرج میں اسے نقل کرنے کے بعد فرمایا: اس کے شروع میں قصہ تھا، میں نے اسے چھوڑ دیا۔ میں کہتا ہوں: ابوعوانہ نے اسے اپنی صحیح میں بحوالہ شعیب نقل کیا ہے، انہوں نے سفیان سے اور سند کو سیدنا ابن عباس رضی اللہ عنہما تک لے گئے ہیں، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم جویریہ رضی اللہ عنہا کے پاس سے ہمارے پاس تشریف لائے، ان کا نام برہ تھا، آپ صلی اللہ علیہ وسلم نے بدل کر جویریہ رکھ دیا، آپ صلی اللہ علیہ وسلم ناپسند کرتے تھے کہ کہا جائے آپ نیکی کے پاس سے نکلے، آپ صلی اللہ علیہ وسلم باہر تشریف لائے تو وہ اپنی جائے نماز پر تھیں۔ پھر حدیث ذکر کی، اس زیادتی سے یہ فائدہ ہوا کہ یہ جویریہ بنت حارث خزاعیہ، نبی کریم صلی اللہ علیہ وسلم کی زوجہ ہیں، کیونکہ مسلم نے حدیث کا یہ جز سفیان بن عیینہ کی روایت سے نقل کیا ہے، اور اس سند کو سیدنا ابن عباس رضی اللہ عنہما تک پہنچایا۔ اسی طرح محمد بن سعد نے جویریہ رضی اللہ عنہا ام المومنین کے سوانح میں بحوالہ سفیان بن عیینہ اسے نقل کیا ہے۔ اور سفیان ثوری کے طریق سے بھی بحوالہ محمد بن عبد الرحمن نقل کیا ہے، اس کی سند ابن عیینہ کی طرح ہے۔ اس کے شروع میں فرماتے ہیں: جویریہ کا نام برہ تھا، رسول اللہ صلی اللہ علیہ وسلم نے جویریہ رکھ دیا۔ فرماتے ہیں: آپ صلی اللہ علیہ وسلم نے فجر کی نماز پڑھی پھر ان کے پاس سے باہر تشریف لائے یہاں تک کہ چاشت کا وقت ہو گیا، پھر آئے اور وہ اپنی جائے نماز پر تھیں۔۔۔۔۔ (الحدیث) اس سے معلوم ہوا کہ وہ ام المومنین میں سے ہیں، اللہ ہی کی توفیق ہے۔","",{"fn":"(1) تجرید (۲۵۷/۲)\n(2) مسلم (الحدیث: ۲۷۲۶)"}],[9621,"§۱۱۰۱۱ ۔ حبانہ\nح کی زیر، اور ب کی تشدید، الف کے بعد نون ہے۔ بنت سلیم بن منبع، ام عامر ہیں، اپنی کنیت سے مشہور ہیں۔ ابن سعد نے ان کا نام لیا ہے، ان کا ذکر کنیتوں میں آئے گا۔"],[9622,"§۱۱۰۱۲ ۔ حبتہ\n(1) ح پر زبر، ب پرسکون، اس کے بعد ت دو نقطوں والی، بنت جبیر ہیں، خوات بن جبیر کی بہن ہیں، ان کا نسب ان کے بھائی کے سوانح میں گزر چکا ہے۔ ابن سعد(2) نے ان کا ذکر کیا اور فرمایا: اسلام لائیں اور نبی کریم صلی اللہ علیہ وسلم سے بیعت ہوئیں۔","",{"fn":"(1) تجرید (۲۵۷/۲)\n(2) الطبقات الکبریٰ (۲۵۷/۸)"}],[9623,"§۱۱۰۱۳ ۔ حبتہ\nسعد بن عمیر کی والدہ ہیں۔ ان کے بیٹے کے سوانح میں ان کا ذکر ہے۔"],[9624,"§۱۱۰۱۴ ۔ حبہ\n(1) ح کے اوپر زبر، برہ کے وزن پر ہے۔ عمرو بن حصن انصاریہ کی صاحبزادی ہیں۔ ابن سعد(2) نے ان کا بیعت کرنے والی خواتین میں ذکر کیا ہے۔","",{"fn":"(1) تجرید (۲۵۷/۲)\n(2) الطبقات الکبریٰ (۲۸۵/۸)"}],[9625,"§۱۱۰۱۵ ۔ حبیبہ بنت ابی امامہ\n(1) اسعد بن زرارہ۔ حرف الف میں ان کا نسب گزر چکا ہے، سہل بن حنیف کی زوجہ ہیں۔ ابوامامہ اسعد کی والدہ ہیں۔ ابراہیم بن محمد بن ابو یحییٰ بحوالہ محمد بن عمارہ فرماتے ہیں: مجھ سے میری والدہ حبیبہ اور میری خالہ کبشہ جو فریعہ بنت ابوامامہ اسعد بن زرارہ کی بہن ہیں۔۔۔۔۔ پھر حدیث ذکر کی۔ عبداللہ بن ادریس دوری نے محمد بن عمارہ سے بحوالہ زینب بنت نبیط جو انس بن مالک کی زوجہ ہیں، سے روایت کیا، فرماتے ہیں: ابوامامہ اسعد بن زرارہ نے میری والدہ اور میری خالہ کو وصیت کی کہ رسول اللہ صلی اللہ علیہ وسلم کی طرف جائیں۔ انہوں نے سونے اور موتیوں کے زیور جنہیں رعاث کہا جاتا تھا پیش کیے، آپ صلی اللہ علیہ وسلم نے یہ رعاث انہیں پہنا دیئے۔ زینب فرماتی ہیں: اس زیور میں سے کچھ میرے گھر والوں کے پاس ہیں۔(2) ابن سکن نے ابن ادریس کی روایت سے اسے نقل کیا ہے اور ابن سعد(3) فرماتے ہیں: حبیبہ اسلام لائیں اور بیعت کی، ان سے سہل بن حنیف نے نکاح کیا جس سے ابو امامہ اسعد پیدا ہوئے، رسول اللہ صلی اللہ علیہ وسلم نے اس کا نام اپنے باپ کے نام پر رکھا، اور اس کی کنیت اپنی کنیت پر رکھی، ان کی والدہ عمیرہ بنت سہل بن ثعلبہ بن حارث ہیں۔","",{"fn":"(1) اسد الغابہ (۶۸۲۵) تجرید (۲۵۷/۲)\n(2) جامع المسانید والسنن (۳۵۵/۱۵)\n(3) الطبقات الکبریٰ (۳۲۲/۸)"}],[9626,"§۱۱۰۱۶ ۔ حبیبہ بنت ابی تجراۃ العبدریہ\n(1) پھر شیبہ، امام شافعی رحمہ اللہ نے ان کی حدیث عبد اللہ بن مؤمل سے روایت کی ہے، اور ابن سعد(2) نے معاذ بن ہانی اور محمد بن سنجر سے، انہوں نے ابو نعیم اور ابن ابو خیثمہ سے، انہوں نے شریح بن نعمان سے، ان سب نے ابن مؤمل سے، انہوں نے عمر بن عبد الرحمن بن محیصن سے، انہوں نے عطا بن ابی رباح سے، وہ فرماتے ہیں کہ مجھ سے صفیہ بنت شیبہ نے حدیث بیان کی، انہوں نے ایک خاتون سے جنہیں حبیبہ بنت ابی تجراۃ کہا جاتا تھا، فرماتی ہیں کہ ہم دار ابی حسین میں قریش کی عورتوں کے ساتھ داخل ہوئے اور نبی کریم صلی اللہ علیہ وسلم کعبہ کا طواف کر رہے تھے اور آپ کا کپڑا بھی پھر رہا تھا، اور وہ اپنے اصحاب سے فرما رہے تھے: \"سعی کرو، اللہ تعالیٰ نے تم پر سعی فرض کی ہے۔\" یہ معاذ کے الفاظ ہیں۔(3) طحاوی نے معاذ کے طریق سے نقل کیا ہے، ابن مندہ کی کتاب میں ان کے طریق سے یہ حدیث ہمیں عالی سند سے ملی ہے۔ ابوعمر(4) فرماتے ہیں، بعض نے کہا: ان کا نام حبیبہ ح کے زبر کے ساتھ بعض کا قول ہے: تصغیر کے ساتھ ہے۔ ان کے علاوہ کا قول ہے: تجراۃ، دار قطنی رحمہ اللہ نے اسے ضبط کیا ہے، ت کے ساتھ، ابو عمر فرماتے ہیں، اس حدیث کی وجہ سے ان کے صحابیہ ہونے میں اختلاف ہے، کیونکہ اس میں صفیہ بنت شیبہ راویہ ہیں میں نے التمہید میں اس کا ذکر کیا ہے۔ میں کہتا ہوں: دوسری سند میں صفیہ سے بحوالہ برہ یہ گزر چکا ہے۔ بعض کا قول ہے: جملک سے، بعض نے کہا: شیبہ کی ام ولد سے، بعض کہتے ہیں: صفیہ سے بلاواسطہ، ابونعیم نے اس کے طرق کے بیان کا استیعاب کیا ہے، ان طرق میں بسرہ بنت محمد بن سباع کا طریق جس میں حبیبہ بنت ابو تجراۃ سے اسی طرح مذکور ہے، نسائی اور ابن ماجہ نے بدیل بن میسرہ کے طریق سے، بحوالہ مغیرہ بن حکیم، انہوں نے صفیہ بنت شیبہ سے انہوں نے ایک خاتون سے نقل کیا ہے، ابن ماجہ کی روایت ہے کہ شیبہ کی ام ولد ہیں، حدیث جملک کی سند حرف ت میں گزر چکی ہے۔","",{"fn":"(1) اسد الغابہ (۶۸۲۶) تجرید (۲۵۷/۲)\n(2) الطبقات الکبریٰ (۱۸۰/۸)\n(3) مسند احمد (۴۲۱/۶)\n(4) استيعاب (۱۸۰۶/۴)"}],[9627,"§۱۱۰۱۷ ۔ حبیبہ بنت جحش\n(1) ابن سعد(2) نے ان کا ذکر کیا ہے، اور فرمایا: حبیب کی والدہ ہیں، اسی طرح زینب کی سگی بہن ہیں، انہیں استحاضہ کا مرض تھا، بعض محدثین فرماتے ہیں: ان کا نام بدل کر ام حبیبہ کہا جانے لگا، پھر ابن ابی ذئب کے طریق سے، زہری سے، بحوالہ عروہ، وہ عائشہ رضی اللہ عنہا سے روایت کرتے ہیں کہ ام حبیبہ بنت جحش کو سات سال تک استحاضہ رہا، وہ عبد الرحمن بن عوف کی زوجہ تھیں، واقدی کا قول ہے: ابن عبدالبر(3) نے ان کا تذکرہ کیا ہے۔ اور فرمایا: ایک جماعت نے کہا ہے، ان کی کنیت ام حبیب بغیر ہاء کے ہے، فرمایا: مشہور ہے کہ وہ ام حبیبہ ہیں، اسی طرح فرمایا: کنیتوں میں اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۶۸۲۷) تجرید (۲۵۷/۲)\n(2) الطبقات الکبریٰ (۱۷۶/۸)\n(3) الاستيعاب (۱۸۰۷/۴)"}],[9628,"§۱۱۰۱۸ ۔ حبیبہ بنت ام حبیبہ\nبنت ابوسفیان، وہ حبیبہ بنت رملہ بنت ابوسفیان بن صخر ہیں، ان کا ذکر آگے آئے گا، ان کے والد کا نام عبد اللہ بن جحش ہے، ان کی والدہ ام المومنین ہیں۔"],[9629,"§۱۱۰۱۹ ۔ حبیبہ بنت الحصین\nبن عبداللہ بن انس بن امیہ بن زید بن دارم، سائب بن ابو سائب کی زوجہ ہیں، زبیر بن بکار نے ان کا ذکر کیا ہے، عبداللہ بن سائب بن ابو سائب کی والدہ ہیں، عبداللہ اور ان کے والدین کو شرف صحابیت حاصل ہے۔"],[9630,"§۱۱۰۲۰ ۔ حبیبہ بنت خارجہ\n(1) بن زید یا بنت زید بن خارجہ خزرجیہ، ابو بکر صدیق کی زوجہ ہیں، ام کلثوم کی والدہ ہیں جو ابو بکر کی بیٹی ہیں، جب ابوبکر فوت ہوئے تو وہ حمل میں تھیں، انہوں نے فرمایا: بنت خارجہ کے بطن والے میرے خیال میں لڑکی ہے، ایسا ہی ہوا، نبی کریم صلی اللہ علیہ وسلم کی وفات کے قصہ میں حضرت عروہ سیدہ عائشہ رضی اللہ عنہا سے روایت کرتے ہیں کہ جب سیدنا ابو بکر صدیق رضی اللہ عنہ نے آپ صلی اللہ علیہ وسلم کی صحت بہتر دیکھی تو خارجہ کے گھر جانے کی اجازت طلب کی، آپ صلی اللہ علیہ وسلم نے انہیں اجازت دے دی۔ ابن سعد(2) فرماتے ہیں: حبیبہ بنت خارجہ بن زید بن ابو زہیر بن مالک بن امرئ القیس بن مالک اغز، ان دونوں کی والدہ بڑیلہ بنت عقبہ بن عمرو بن خدیج بن عامر بن جشم ہیں، اسلام لائیں اور بیعت ہوئیں۔ فرماتے ہیں: ابوبکر رضی اللہ عنہ کے بعد اساف بن عتبہ بن عمرو نے حبیبہ سے شادی کی۔","",{"fn":"(1) اسد الغابہ (۶۸۲۸) تجرید (۲۵۷/۲)\n(2) الطبقات الکبریٰ (۲۶۲/۸)"}],[9631,"§۱۱۰۲۱ ۔ حبیبہ بنت زید\nبن ابو زہیر، ان کے والد کے سوانح میں ان کا ذکر ہے۔"],[9632,"§۱۱۰۲۲ ۔ حبیبہ بنت ابی سفیان\n(1) ابوعمر(2) فرماتے ہیں، ابان بن صمعہ کا قول ہے کہ انہوں نے محمد بن سیرین کو فرماتے ہوئے سنا کہ مجھ سے حبیبہ بنت ابوسفیان نے بیان کیا کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: جس شخص کی اولاد میں سے تین بچے مر گئے۔۔۔۔۔(3) ان سے محمد بن سیرین کے علاوہ کسی نے روایت نہیں کی، نہ ابوسفیان کی کوئی ایسی صاحبزادی ہیں جن کا نام حبیبہ ہو، جس کے کا گمان ہے کہ وہ حبیبہ بنت ام حبیبہ بنت ابوسفیان جن کی حدیث زہری نے عروہ سے بحوالہ زینب بنت ابوسلمہ انہوں نے ان سے، انہوں نے اپنے بیٹے سے، انہوں نے زینب بنت جحش سے یاجوج ماجوج کی دیوار کے بارے میں حدیث روایت کی ہے، اور ان کے والد عبید اللہ بن جحش حبشہ کی سرزمین میں وفات پاگئے۔ موسیٰ بن عقبہ نے ان کا ذکر حبشہ کی طرف ہجرت کرنے والوں میں کیا ہے۔ وہاں ان کے والد عیسائی ہو گئے۔ جیسا گمان ہے ویسا نہیں، کیونکہ یہ حبیبہ بنت ابوسفیان دوسری ہیں، یہ سیدہ عائشہ رضی اللہ عنہا کی خدمت کیا کرتی تھیں، اور ان کے والد ابوسفیان نہیں ہیں، وہ تو ابوحرب ام المؤمنین ام حبیبہ کے والد ہیں، یہ ابوسفیان کوئی اور ہیں جن کا نسب معلوم نہیں۔ ابن مندہ نے عالی سند کے ساتھ نضر بن شمیل کے طریق سے بحوالہ ابان بن صمعہ روایت کیا ہے، فرماتے ہیں: میں نے ابن سیرین کو فرماتے ہوئے سنا: مجھ سے حبیبہ نے بیان کیا کہ وہ سیدہ عائشہ رضی اللہ عنہا کے گھر میں بیٹھی ہوئی تھیں، نبی کریم صلی اللہ علیہ وسلم تشریف لائے اور فرمایا: \"جن مسلمان والدین کے تین بچے فوت ہوں اللہ تعالیٰ ان دونوں کو جنت میں داخل کرے گا\"۔(4) فرماتے ہیں: اسے انصاری وغیرہ نے روایت کیا ہے۔ حسن بن سفیان نے اپنی مسند میں سہل بن یوسف کے طریق سے بحوالہ آبان طویل حدیث نقل کی ہے، اور اس کے آخر میں فرمایا: \"ان بچوں سے کہا جائے گا جنت میں داخل ہو جاؤ!\" وہ کہیں گے: پہلے ہمارے والدین اس میں داخل ہوں، پھر انہیں تیسری یا چوتھی مرتبہ کہا جائے گا: \"تم اور تمہارے والدین داخل ہوں\"۔ فرماتے ہیں: مجھ سے سیدہ عائشہ رضی اللہ عنہا نے فرمایا: کیا تم نے یہ حدیث سنی ہے؟ میں نے کہا: جی ہاں! کہنے لگیں: تو اسے یاد کرلو۔","",{"fn":"(1) اسد الغابہ (۶۸۲۹) تجرید (۲۵۸/۲)\n(2) الاستيعاب (۱۸۰۸/۴)\n(3) المعجم الکبیر (الحدیث: ۵۷۰/۲۴) مجمع الزوائد (۷/۳)\n(4) المعجم الکبیر (۵۷۱/۲۴)"}]])